def report_uncaught_exception(exc_type, exc_value, exc_traceback):
    if issubclass(exc_type, KeyboardInterrupt):
        sys.__excepthook__(exc_type, exc_value, exc_traceback)
        return
    try:
        LOGGER.error('Unbehandelter Programmfehler\n%s', ''.join(
            traceback.format_exception(exc_type, exc_value, exc_traceback)))
    except Exception:
        pass
    try:
        QMessageBox.critical(None, 'MPW – Programmfehler',
                             'Ein unerwarteter Fehler ist aufgetreten.\n'
                             'Details findest du unter System & Diagnose im Fehlerprotokoll.')
    except Exception:
        sys.__excepthook__(exc_type, exc_value, exc_traceback)


def install_project_cover_icon(project_folder):
    """Set the Windows Explorer icon of Band/Projekt using an image in Cover.

    Does not replace an existing desktop.ini or a pre-existing custom icon.
    Returns (changed, explanation). Non-Windows systems are intentionally skipped.
    """
    project_folder = Path(project_folder)
    cover_folder = project_folder / 'Cover'
    if os.name != 'nt':
        return False, 'Windows-Ordnersymbole werden nur unter Windows eingerichtet.'
    if project_folder.is_symlink() or cover_folder.is_symlink() or not cover_folder.is_dir():
        return False, 'Projekt-/Cover-Ordner fehlt oder ist unsicher.'
    ini = project_folder / 'desktop.ini'
    ico = project_folder / 'mpw_project_cover.ico'
    if ini.exists() or ini.is_symlink() or ico.exists() or ico.is_symlink():
        return False, 'Vorhandene Ordneranpassung wird nicht überschrieben.'
    covers = sorted((f for f in cover_folder.iterdir()
                     if f.is_file() and not f.is_symlink() and f.suffix.lower() in KINDS['Cover']),
                    key=lambda f: f.name.casefold())
    if not covers:
        return False, 'Keine Coverdatei vorhanden.'
    pixmap = QPixmap(str(covers[0]))
    if pixmap.isNull():
        return False, 'Coverbild kann nicht gelesen werden.'
    scaled = pixmap.scaled(256, 256, Qt.AspectRatioMode.KeepAspectRatio,
                           Qt.TransformationMode.SmoothTransformation)
    canvas = QPixmap(256, 256)
    canvas.fill(Qt.GlobalColor.transparent)
    painter = QPainter(canvas)
    painter.drawPixmap((256 - scaled.width()) // 2, (256 - scaled.height()) // 2, scaled)
    painter.end()
    payload = QByteArray()
    buffer = QBuffer(payload)
    if not buffer.open(QIODevice.OpenModeFlag.WriteOnly) or not canvas.save(buffer, 'PNG'):
        return False, 'ICO-Bild konnte nicht erstellt werden.'
    png = bytes(payload)
    # Windows Vista+ accepts a PNG-encoded 256x256 image in an ICO container.
    ico_bytes = struct.pack('<HHH', 0, 1, 1) + struct.pack('<BBBBHHII',
        0, 0, 0, 0, 1, 32, len(png), 22) + png
    try:
        with ico.open('xb') as out:
            out.write(ico_bytes)
        with ini.open('x', encoding='utf-16') as out:
            out.write('[.ShellClassInfo]\nIconResource=mpw_project_cover.ico,0\n')
        import ctypes
        get_attrs = ctypes.windll.kernel32.GetFileAttributesW
        get_attrs.argtypes = [ctypes.c_wchar_p]
        get_attrs.restype = ctypes.c_uint32
        set_attrs = ctypes.windll.kernel32.SetFileAttributesW
        set_attrs.argtypes = [ctypes.c_wchar_p, ctypes.c_uint32]
        set_attrs.restype = ctypes.c_int
        # Explorer requires the read-only bit on the folder to honor desktop.ini.
        for path, bits in ((project_folder, 0x01), (ini, 0x06), (ico, 0x02)):
            attrs = get_attrs(str(path))
            if attrs == 0xFFFFFFFF or not set_attrs(str(path), attrs | bits):
                raise OSError(f'Windows-Ordnerattribute konnten nicht gesetzt werden: {path}')
        return True, f'Ordnersymbol aus {covers[0].name} erstellt.'
    except Exception:
        # Do not delete any pre-existing files: only the newly created pair.
        for path in (ini, ico):
            try:
                if path.exists(): path.unlink()
            except OSError:
                pass
        raise


