class ManualBackupWorker(QObject):
    """Run large ZIP creation outside Qt's GUI thread, using its own SQLite connection."""
    completed = Signal(str)
    failed = Signal(str)
    finished = Signal()

    def __init__(self, root, destination):
        super().__init__()
        self.root = Path(root)
        self.destination = Path(destination)

    def run(self):
        partial = self.destination.with_name(self.destination.name + '.incomplete')
        try:
            if self.destination.exists() or partial.exists():
                raise FileExistsError('Backup oder unvollständige Sicherung existiert bereits. Bitte anderen Dateinamen wählen.')
            with closing(sqlite3.connect(str(self.root / 'workstation.db'), timeout=30)) as connection:
                create_backup(connection, self.root, partial)
            # Archive was verified; only now publish it under the chosen filename.
            partial.replace(self.destination)
            self.completed.emit(str(self.destination))
        except Exception as exc:
            LOGGER.exception('Manuelles Vollbackup fehlgeschlagen')
            self.failed.emit(str(exc) + ('\nUnvollständige Datei: ' + str(partial) if partial.exists() else ''))
        finally:
            self.finished.emit()


class GenerationSignals(QObject):
    finished = Signal(str)
    failed = Signal(str, str, str, str)  # kind, provider, HTTP code, provider detail


class GenerationJob(QRunnable):
    def __init__(self, provider, model, key, prompt):
        super().__init__()
        self.provider, self.model, self.key, self.prompt = provider, model, key, prompt
        self.signals = GenerationSignals()

    def run(self):
        try:
            self.signals.finished.emit(call_provider(self.provider, self.model, self.key, self.prompt))
        except ProviderError as exc:
            self.signals.failed.emit(exc.kind, exc.provider, exc.code, exc.detail)
        except Exception as exc:
            LOGGER.exception('Unerwarteter Fehler bei der API-Anfrage')
            detail = str(exc).replace(self.key, '***') if self.key else str(exc)
            self.signals.failed.emit('unexpected', self.provider, '', detail[:300])


class AiConnectionSignals(QObject):
    finished = Signal(object)


class AiConnectionCheckJob(QRunnable):
    """Runs check_ai_connections in the thread pool so the window stays responsive."""

    def __init__(self):
        super().__init__()
        self.signals = AiConnectionSignals()

    def run(self):
        try:
            result = check_ai_connections()
        except Exception as exc:  # never let a check crash MPW
            LOGGER.exception('KI-Verbindungen konnten nicht geprüft werden')
            result = {'error': str(exc)}
        self.signals.finished.emit(result)


class SunoSendJob(QRunnable):
    def __init__(self, command, arguments):
        super().__init__()
        self.command, self.arguments = command, arguments
        self.token = os.urandom(8).hex()
        self.signals = AiConnectionSignals()

    def run(self):
        try:
            result = call_suno_via_claude(self.command, self.arguments)
        except ProviderError as exc:
            result = {'provider_error': (exc.kind, exc.code, exc.detail)}
        except Exception as exc:  # never crash MPW from a worker thread
            LOGGER.exception('Senden an Suno fehlgeschlagen')
            result = {'provider_error': ('unexpected', '', str(exc)[:300])}
        result['token'] = self.token
        self.signals.finished.emit(result)


class CliGenerationJob(QRunnable):
    def __init__(self, provider, command, model, prompt):
        super().__init__()
        self.provider, self.command, self.model, self.prompt = provider, command, model, prompt
        self.signals = GenerationSignals()

    def run(self):
        try:
            self.signals.finished.emit(call_cli(self.provider, self.command, self.model, self.prompt))
        except ProviderError as exc:
            self.signals.failed.emit(exc.kind, exc.provider, exc.code, exc.detail)
        except Exception as exc:
            LOGGER.exception('Unerwarteter Fehler beim CLI-Aufruf')
            self.signals.failed.emit('unexpected', self.provider, '', str(exc)[:300])


class BackgroundPage(QWidget):
    """Paint an optional PNG behind each tab's existing controls."""
    background_pixmap = None
    background_opacity = 0.65
    background_scaling = "cover"

    def paintEvent(self, event):
        super().paintEvent(event)
        source = BackgroundPage.background_pixmap
        if source is None or source.isNull():
            return
        painter = QPainter(self)
        painter.setOpacity(BackgroundPage.background_opacity)
        # Scale within the current tab; never create a pixmap before QApplication.
        mode = BackgroundPage.background_scaling
        if mode == 'stretch':
            painter.drawPixmap(self.rect(), source)
        else:
            aspect = (Qt.AspectRatioMode.KeepAspectRatio if mode == 'contain'
                      else Qt.AspectRatioMode.KeepAspectRatioByExpanding)
            scaled = source.scaled(self.size(), aspect,
                                   Qt.TransformationMode.SmoothTransformation)
            x = (self.width() - scaled.width()) // 2
            y = (self.height() - scaled.height()) // 2
            painter.drawPixmap(x, y, scaled)
        painter.end()


class Workstation(QMainWindow):
    def __init__(self):
        super().__init__()
        self.con = init_database()
        # Create the default backup folder on first launch (no custom path touched).
        default_backup = ROOT / 'backups'
        if not (ROOT / 'backup_settings.json').exists():
            default_backup.mkdir(parents=True, exist_ok=True)
        self.setWindowTitle(f'MPW - Music Production Workstation · v{APP_VERSION}')
        self.resize(1250, 820)
        self.apply_color_theme()
        self.load_background_preference()
        self.tabs = QTabWidget()
        self.setCentralWidget(self.tabs)
        self.build_bands()
        self.build_projects()
        self.build_genre_catalog()
        self.build_songs()
        self.build_ai()
        self.build_media()
        self.build_media_explorer()
        self.build_releases()
        self.build_albums()
        self.build_album_details()
        self.build_album_print()
        self.build_backup()
        self.build_backup_archive()
        self.build_configuration()
        self.build_diagnostics()
        self.run_scheduled_backup()
        # AI Prompt Launcher vor Songs & Suno, ohne feste Tab-Indizes.
        ai_idx = self.tab_index('AI Prompt Launcher')
        ai_page = self.tabs.widget(ai_idx)
        self.tabs.removeTab(ai_idx)
        genre_idx = self.tab_index('Genre-Katalog')
        self.tabs.insertTab(genre_idx + 1, ai_page, 'AI Prompt Launcher')
        self.refresh_language_controls()
        self.threadpool = QThreadPool.globalInstance()
        self.ai_job = None
        self.ai_result = None
        self.refresh_all()
        self.refresh_ai_language()
        self.populate_startup_tab_choices()
        self.restore_initial_tab()
        self.install_field_help()
        self.install_tab_guides()
        self.tabs.currentChanged.connect(self.remember_current_tab)
        self.tabs.currentChanged.connect(self.on_theme_preview_tab_changed)
        QTimer.singleShot(200, self.verify_backups_on_startup)

