    SYSTEM_GUIDE_TRANSLATIONS = {'en': [('System', 'Run system check', 'Checks the MPW installation and displays diagnostic information without changing song data.'), ('System', 'Export diagnostic report as TXT', 'Saves the diagnostic results to a text file.'), ('Error logs', 'Refresh log files', 'Reloads available current and archived log files.'), ('Error logs', 'View error log', 'Opens the selected log file for viewing.'), ('Error logs', 'Export error log', 'Creates an exportable copy of the selected log.'), ('Analysis', 'Show error statistics', 'Summarizes logged errors statistically.'), ('Analysis', 'Error history by day', 'Shows the distribution of logged errors over time.'), ('Analysis', 'Export error statistics as CSV', 'Exports error statistics for spreadsheet use.'), ('Analysis', 'Export error history as CSV', 'Exports daily error trends.'), ('Support', 'Export diagnostic package as ZIP', 'Collects diagnostic information for troubleshooting.'), ('Privacy', 'Review logs', 'Check paths and personal information before sharing diagnostic files.')], 'fr': [('Système', 'Lancer le contrôle du système', 'Vérifie l’installation de MPW et affiche des indications de diagnostic sans modifier les chansons.'), ('Système', 'Exporter le rapport en TXT', 'Enregistre les résultats du diagnostic dans un fichier texte.'), ('Journaux d’erreurs', 'Actualiser les journaux', 'Recharge les journaux actuels et archivés disponibles.'), ('Journaux d’erreurs', 'Afficher le journal d’erreurs', 'Ouvre le journal sélectionné pour consultation.'), ('Journaux d’erreurs', 'Exporter le journal d’erreurs', 'Crée une copie exportable du journal sélectionné.'), ('Analyse', 'Afficher les statistiques d’erreurs', 'Résume statistiquement les erreurs enregistrées.'), ('Analyse', 'Historique des erreurs par jour', 'Affiche la répartition chronologique des erreurs enregistrées.'), ('Analyse', 'Exporter les statistiques en CSV', 'Exporte les statistiques pour un tableur.'), ('Analyse', 'Exporter l’historique en CSV', 'Exporte l’évolution quotidienne des erreurs.'), ('Assistance', 'Exporter le diagnostic en ZIP', 'Regroupe les informations de diagnostic pour le dépannage.'), ('Confidentialité', 'Vérifier les journaux', 'Vérifiez les chemins et données personnelles avant de partager des diagnostics.')], 'es': [('Sistema', 'Iniciar comprobación del sistema', 'Comprueba la instalación de MPW y muestra información de diagnóstico sin modificar las canciones.'), ('Sistema', 'Exportar informe de diagnóstico como TXT', 'Guarda los resultados del diagnóstico en un archivo de texto.'), ('Registros de errores', 'Actualizar registros', 'Vuelve a cargar los registros actuales y archivados disponibles.'), ('Registros de errores', 'Ver registro de errores', 'Abre el registro seleccionado para consultarlo.'), ('Registros de errores', 'Exportar registro de errores', 'Crea una copia exportable del registro seleccionado.'), ('Análisis', 'Mostrar estadísticas de errores', 'Resume estadísticamente los errores registrados.'), ('Análisis', 'Historial de errores por día', 'Muestra la distribución temporal de los errores registrados.'), ('Análisis', 'Exportar estadísticas como CSV', 'Exporta las estadísticas para una hoja de cálculo.'), ('Análisis', 'Exportar historial como CSV', 'Exporta la evolución diaria de errores.'), ('Soporte', 'Exportar paquete de diagnóstico como ZIP', 'Agrupa información de diagnóstico para solucionar problemas.'), ('Privacidad', 'Revisar registros', 'Comprueba las rutas y los datos personales antes de compartir archivos de diagnóstico.')], 'it': [('Sistema', 'Avvia controllo del sistema', 'Controlla l’installazione di MPW e mostra informazioni diagnostiche senza modificare i brani.'), ('Sistema', 'Esporta rapporto diagnostico in TXT', 'Salva i risultati diagnostici in un file di testo.'), ('Registri errori', 'Aggiorna registri', 'Ricarica i registri disponibili, correnti e archiviati.'), ('Registri errori', 'Visualizza registro errori', 'Apre il registro selezionato per la consultazione.'), ('Registri errori', 'Esporta registro errori', 'Crea una copia esportabile del registro selezionato.'), ('Analisi', 'Mostra statistiche errori', 'Riepiloga statisticamente gli errori registrati.'), ('Analisi', 'Cronologia errori per giorno', 'Mostra la distribuzione temporale degli errori registrati.'), ('Analisi', 'Esporta statistiche in CSV', 'Esporta le statistiche per un foglio di calcolo.'), ('Analisi', 'Esporta cronologia in CSV', 'Esporta l’andamento giornaliero degli errori.'), ('Supporto', 'Esporta pacchetto diagnostico ZIP', 'Raccoglie informazioni diagnostiche per la risoluzione dei problemi.'), ('Privacy', 'Controlla registri', 'Verifica percorsi e dati personali prima di condividere file diagnostici.')]}

