    CONFIG_ADDITIONAL_GUIDE_TRANSLATIONS = {
        'Rekursive Audioübernahme': {
            'en': ('Media migration', 'Recursive audio import', 'Imports supported audio files from Music and all subfolders into the shared project Audio folder, retaining the subfolder structure. During a move, each source file is removed only after SHA-256 verification. Existing folders are never deleted.'),
            'fr': ('Migration des médias', 'Import audio récursif', 'Importe les fichiers audio pris en charge depuis Musique et ses sous-dossiers vers le dossier Audio du projet, en conservant la structure. Lors d’un déplacement, chaque source n’est supprimée qu’après vérification SHA-256. Aucun dossier existant n’est supprimé.'),
            'es': ('Migración multimedia', 'Importación recursiva de audio', 'Importa los archivos de audio compatibles desde Música y todas sus subcarpetas a Audio del proyecto, conservando la estructura. Al moverlos, cada origen solo se elimina tras verificar SHA-256. Nunca se eliminan carpetas existentes.'),
            'it': ('Migrazione media', 'Importazione audio ricorsiva', 'Importa i file audio supportati da Musica e tutte le sottocartelle nella cartella Audio del progetto, mantenendo la struttura. Durante lo spostamento, ogni origine viene eliminata solo dopo la verifica SHA-256. Le cartelle esistenti non vengono mai eliminate.'),
        },
        'Vier feste Medienordner': {
            'en': ('Project folders', 'Four fixed media folders', 'Cover, Audio, Documents and Video are protected fixed folders. Up to six additional subfolders may be configured. Existing folders are not deleted.'),
            'fr': ('Dossiers de projet', 'Quatre dossiers médias fixes', 'Cover, Audio, Documents et Video sont des dossiers fixes protégés. Vous pouvez ajouter jusqu’à six sous-dossiers. Les dossiers existants ne sont pas supprimés.'),
            'es': ('Carpetas de proyecto', 'Cuatro carpetas multimedia fijas', 'Cover, Audio, Documents y Video son carpetas fijas protegidas. Se pueden configurar hasta seis subcarpetas adicionales. No se eliminan carpetas existentes.'),
            'it': ('Cartelle di progetto', 'Quattro cartelle multimediali fisse', 'Cover, Audio, Documents e Video sono cartelle fisse protette. È possibile configurare fino a sei sottocartelle aggiuntive. Le cartelle esistenti non vengono eliminate.'),
        },
        'Projektordner-Symbole aus Covern erstellen': {
            'en': ('Project covers', 'Create project folder icons from covers', 'On Windows, creates Explorer folder icons from the first readable image in each project Cover folder. Existing desktop.ini files and custom icons are never overwritten. A new cover import also sets up the icon automatically if no customization exists.'),
            'fr': ('Pochettes de projet', 'Créer des icônes de dossier depuis les pochettes', 'Sous Windows, crée des icônes de dossier à partir de la première image lisible du dossier Cover. Les fichiers desktop.ini et icônes personnalisées ne sont jamais remplacés. Une nouvelle pochette configure aussi l’icône si aucune personnalisation n’existe.'),
            'es': ('Portadas de proyecto', 'Crear iconos de carpeta desde portadas', 'En Windows, crea iconos de carpeta a partir de la primera imagen legible de Cover. Nunca sobrescribe archivos desktop.ini ni iconos personalizados. Al importar una nueva portada, también configura el icono si no existe una personalización.'),
            'it': ('Copertine di progetto', 'Crea icone cartella dalle copertine', 'In Windows crea icone di cartella dalla prima immagine leggibile in Cover. Non sovrascrive mai desktop.ini o icone personalizzate. Anche una nuova copertina imposta l’icona automaticamente se non esistono personalizzazioni.'),
        },
    }

