    def _guide_translation_lookup(self, name, language):
        """Resolve guide translations by stable source labels, preserving groups.

        Translation sources contain either (translated_label, explanation) or
        (translated_group, translated_label, explanation). Normalize both forms
        to a consistent three-tuple for the HTML renderer.
        """
        if language == 'de':
            return {}
        entries = self.DETAILED_TAB_GUIDES.get(name, ())
        original_groups = {label: group for group, label, _ in entries}
        result = {}

        def add(source):
            for label, languages in source.items():
                if label not in original_groups or language not in languages:
                    continue
                translated = languages[language]
                if len(translated) == 2:
                    result[label] = (original_groups[label], *translated)
                elif len(translated) == 3:
                    result[label] = tuple(translated)
                else:
                    raise ValueError(f'Invalid guide translation for {name}: {label}')

        for source in (
            self.GUIDE_TRANSLATIONS_BY_LABEL.get(name, {}),
            self.GUIDE_TRANSLATIONS_ALPHA20_CORE.get(name, {}),
            self.GUIDE_TRANSLATIONS_ALPHA20_PROJECTS.get(name, {}),
            self.GUIDE_TRANSLATIONS_ALPHA20_SUNO.get(name, {}),
            self.MEDIA_RELEASE_GUIDE_TRANSLATIONS.get(name, {}),
            self.ALPHA20_ALBUM_GUIDE_TRANSLATIONS.get(name, {}),
            self.ALPHA20_BACKUP_GUIDE_TRANSLATIONS.get(name, {}),
            self.ALPHA20_MISSING_GUIDE_TRANSLATIONS.get(name, {}),
            self.ALPHA20_FINAL_GUIDE_TRANSLATIONS.get(name, {}),
            self.ALPHA20_COMPLETION_GUIDE_TRANSLATIONS.get(name, {}),
            self.ALPHA20_SUNO_EXTRA_TRANSLATIONS.get(name, {}),
            self.ALPHA20_SUNO_PRODUCTION_TRANSLATIONS.get(name, {}),
            self.ALPHA20_SUNO_WORKFLOW_TRANSLATIONS.get(name, {}),
        ):
            add(source)
        add(self.GUIDE_EXTENDED_HF16.get(name, {}))
        if name == 'Medien & Player' and language == 'en':
            for label, translated in self.GUIDE_MEDIA_EN_HF17.items():
                if label in original_groups:
                    result[label] = (original_groups[label], *translated)
        if name == 'Songs & Suno':
            add(self.GUIDE_SUNO_EXTENDED_HF14)
        if name == 'Medien & Player':
            add(self.ALPHA20_AUDIO_QC_GUIDE_TRANSLATIONS)
        if name == 'Medien Explorer':
            add(self.MEDIA_EXPLORER_GUIDE_TRANSLATIONS)
        if name == 'Konfiguration':
            add(self.CONFIG_EXTENDED_GUIDE_TRANSLATIONS)
            add(self.CONFIG_ADDITIONAL_GUIDE_TRANSLATIONS)
        if language == 'en':
            add(self.GUIDE_EN_HF18.get(name, {}))
            add(self.GUIDE_EN_HF19.get(name, {}))
        return result

