    def general_detailed_guide_html(self, name):
        """Funktionsorientierte Offline-Hilfe zu allen weiteren Reitern."""
        entries = self.DETAILED_TAB_GUIDES.get(name, [])
        intro = self.TAB_GUIDES.get(name, ('Übersicht', 'Bedienhinweise', '', ''))
        language = self.effective_language()
        intro = self.TAB_GUIDE_INTRO_TRANSLATIONS_ALPHA20.get(name, {}).get(language, intro)
        headings = {
            'de': ('vollständige Anleitung', 'Zweck', 'Empfohlener Ablauf', 'Wichtiger Hinweis'),
            'en': ('Complete guide', 'Purpose', 'Recommended workflow', 'Important note'),
            'fr': ('Guide complet', 'Objectif', 'Procédure recommandée', 'Remarque importante'),
            'es': ('Guía completa', 'Objetivo', 'Procedimiento recomendado', 'Nota importante'),
            'it': ('Guida completa', 'Scopo', 'Procedura consigliata', 'Nota importante'),
        }[language]
        parts = ['<html><head><meta charset="utf-8"><style>'
                 'body{font-family:sans-serif;font-size:10.5pt;line-height:1.45}'
                 'h2{margin-bottom:5px}h3{margin-top:18px;margin-bottom:6px}'
                 'p{margin-top:3px;margin-bottom:8px}li{margin-bottom:7px}'
                 '</style></head><body>',
                 '<h2>' + html.escape(self.GUIDE_TITLE_HF16.get(name, {}).get(language, name)) + ' – ' + html.escape(headings[0]) + '</h2>',
                 '<p><b>' + html.escape(headings[1]) + ':</b> ' + html.escape(intro[1]) + '</p>']
        section = None
        language = self.effective_language()
        # Use original labels as stable lookup keys. Never let an inserted guide
        # entry shift translations onto unrelated controls.
        translation_lookup = self._guide_translation_lookup(name, language)
        for original_group, original_label, original_explanation in entries:
            group, label, explanation = translation_lookup.get(
                original_label, (original_group, original_label, original_explanation))
            # Translate the original section key even if the label translation
            # contains a source-language group. Do not mutate guide data.
            group = self.GUIDE_SECTION_TRANSLATIONS_ALPHA20.get(
                original_group, {}).get(language, group)
            # HF17: Section identity comes from the original guide structure,
            # never from per-label translation records. Mixed source dictionaries
            # previously split one section into German/English duplicates.
            group = self.GUIDE_CANONICAL_SECTIONS_HF17.get(
                name, {}).get(original_group, {}).get(language, group)
            if language == 'en':
                group = self.GUIDE_SECTIONS_EN_HF18.get(name, {}).get(original_group, group)
            if group != section:
                if section is not None:
                    parts.append('</ul>')
                parts.append('<h3>' + html.escape(group) + '</h3><ul>')
                section = group
            parts.append('<li><b>' + html.escape(label) + ':</b> ' + html.escape(explanation) + '</li>')
        if section is not None:
            parts.append('</ul>')
        parts.extend(['<h3>' + html.escape(headings[2]) + '</h3><p>' + html.escape(intro[2]) + '</p>',
                      '<h3>' + html.escape(headings[3]) + '</h3><p>' + html.escape(intro[3]) + '</p>',
                      '</body></html>'])
        return ''.join(parts)

    def install_tab_guides(self):
        """Insert a help row into each existing tab layout without replacing tabs.

        Reparenting a tab page into a wrapper can leave its original content
        detached or invisible on some Qt versions. Never remove or reinsert tabs.
        """
        self.tab_help_buttons = []
        for index in range(self.tabs.count()):
            page = self.tabs.widget(index)
            if page is None:
                logging.warning('Hilfe: Reiter %s ohne Seite', index)
                continue
            # Einige Tabs sind QScrollArea-Container. Deren eigentliche
            # Inhaltsseite besitzt das QVBoxLayout, nicht die ScrollArea.
            from PySide6.QtWidgets import QScrollArea
            content_page = page.widget() if isinstance(page, QScrollArea) else page
            layout = content_page.layout() if content_page is not None else None
            if not isinstance(layout, QVBoxLayout):
                logging.warning('Hilfe: Reiter %s besitzt kein unterstütztes Inhaltslayout', self.tab_key(index))
                continue
            title = self.tab_key(index)
            header = QWidget(content_page)
            header.setObjectName('mpwHelpHeader')
            header.setFixedHeight(39)
            header_layout = QHBoxLayout(header)
            header_layout.setContentsMargins(8, 3, 10, 3)
            header_layout.addStretch(1)
            button = QPushButton('ⓘ  Anleitung', header)
            button.setObjectName('mpwTabHelpButton')
            button.setFixedHeight(31)
            button.setMinimumWidth(112)
            button.setToolTip('Detaillierte Anleitung zu diesem Reiter öffnen')
            button.setAccessibleName('Anleitung öffnen: ' + title)
            button.clicked.connect(lambda checked=False, tab=page: self.show_tab_guide(tab))
            header_layout.addWidget(button)
            layout.insertWidget(0, header)
            self.tab_help_buttons.append((page, button))
        self.style_tab_help_buttons()

    def style_tab_help_buttons(self, palette=None):
        """Contrast the help action against regular inputs using theme accent."""
        if not hasattr(self, 'tab_help_buttons'):
            return
        c = dict(palette) if palette is not None else self.current_color_theme()
        accent = QColor(c['accent'])
        text_color = '#ffffff'  # Einheitliche weiße Button-Beschriftungen
        hover = accent.lighter(115) if accent.lightness() < 150 else accent.darker(112)
        for _page, button in self.tab_help_buttons:
            button.setStyleSheet(
                f'background-color: {accent.name()}; color: {text_color}; '
                f'border: 1px solid {c["border"]}; border-radius: 7px; '
                'font-weight: bold; padding: 4px 12px;'
            )

    def show_tab_guide(self, page):
        index = self.tabs.indexOf(page)
        if index >= 0:
            self.show_current_tab_guide(index)

    def show_current_tab_guide(self, tab_index=None):
        """Open a separate, read-only information sheet for the active tab."""
        if tab_index is None:
            tab_index = self.tabs.currentIndex()
        # Qt gibt den tatsächlichen Tab-Titel zurück. Das & gehört zum Namen
        # (z. B. 'Songs & Suno') und darf nicht entfernt werden.
        name = self.tab_key(tab_index)
        if name not in self.TAB_GUIDES:
            # Nur bei abweichender Darstellung Qt-Mnemonics normalisieren.
            name = name.replace('&&', '&')
        guide = self.TAB_GUIDES.get(name)
        if guide is None:
            guide = ('Übersicht', 'Informationen zum gewählten Reiter.',
                     'Verwende die angezeigten Eingabefelder und Schaltflächen.',
                     'Vor größeren Änderungen eine Datensicherung erstellen.')
        subtitle, purpose, tasks, note = guide
        help_ui = {
            'de': ('Anleitung', 'Anleitung durchsuchen …', 'Suchbegriff für die Reiter-Anleitung', 'Zurück', 'Weiter', 'Vorherigen Treffer anzeigen (Umschalt + Eingabe)', 'Nächsten Treffer anzeigen (Eingabe)', 'Suchbegriff eingeben, um die Anleitung zu durchsuchen.', 'Treffer markiert – mit Weiter/Zurück weitere Fundstellen anzeigen.', 'Keine Treffer für „{term}“ gefunden.', 'Schließen'),
            'en': ('Guide', 'Search this guide …', 'Search term for the tab guide', 'Previous', 'Next', 'Previous match (Shift + Enter)', 'Next match (Enter)', 'Enter a search term to search this guide.', 'Match highlighted – use Next/Previous to browse other matches.', 'No matches found for “{term}”.', 'Close'),
            'fr': ('Guide', 'Rechercher dans ce guide …', 'Terme à rechercher dans le guide', 'Précédent', 'Suivant', 'Résultat précédent (Maj + Entrée)', 'Résultat suivant (Entrée)', 'Saisissez un terme pour rechercher dans ce guide.', 'Résultat surligné – utilisez Suivant/Précédent pour parcourir les résultats.', 'Aucun résultat pour « {term} ».', 'Fermer'),
            'es': ('Guía', 'Buscar en esta guía …', 'Término de búsqueda de la guía', 'Anterior', 'Siguiente', 'Coincidencia anterior (Mayús + Intro)', 'Coincidencia siguiente (Intro)', 'Introduzca un término para buscar en esta guía.', 'Coincidencia resaltada; use Siguiente/Anterior para ver más.', 'No se encontraron coincidencias para «{term}».', 'Cerrar'),
            'it': ('Guida', 'Cerca in questa guida …', 'Termine da cercare nella guida', 'Precedente', 'Successivo', 'Risultato precedente (Maiusc + Invio)', 'Risultato successivo (Invio)', 'Inserisci un termine per cercare nella guida.', 'Risultato evidenziato: usa Successivo/Precedente per gli altri.', 'Nessun risultato per «{term}».', 'Chiudi'),
        }.get(self.effective_language(), ())
        dialog = QDialog(self)
        dialog.setWindowTitle('MPW – ' + help_ui[0] + ': ' + name)
        dialog.resize(660, 520)
        dialog.setMinimumSize(460, 350)
        layout = QVBoxLayout(dialog)
        browser = QTextBrowser(dialog)
        browser.setOpenExternalLinks(False)
        if name == 'AI Prompt Launcher':
            browser.setHtml(self.ai_launcher_detailed_guide_html())
        else:
            browser.setHtml(self.general_detailed_guide_html(name))
        # Search bar belongs to the help dialog, not to the tab bar.
        search_row = QHBoxLayout()
        search_input = QLineEdit(dialog)
        search_input.setPlaceholderText(help_ui[1])
        search_input.setClearButtonEnabled(True)
        search_input.setAccessibleName(help_ui[2])
        search_row.addWidget(search_input, 1)
        previous_button = QPushButton('◀ ' + help_ui[3], dialog)
        next_button = QPushButton(help_ui[4] + ' ▶', dialog)
        previous_button.setToolTip(help_ui[5])
        next_button.setToolTip(help_ui[6])
        search_row.addWidget(previous_button)
        search_row.addWidget(next_button)
        layout.addLayout(search_row)
        search_status = QLabel(help_ui[7], dialog)
        search_status.setWordWrap(True)
        layout.addWidget(search_status)
        layout.addWidget(browser)

        def navigate_help_search(backwards=False, from_start=False):
            term = search_input.text().strip()
            if not term:
                search_status.setText(help_ui[7])
                return
            flags = QTextDocument.FindFlag.FindBackward if backwards else QTextDocument.FindFlags()
            if from_start:
                cursor = browser.textCursor()
                cursor.movePosition(cursor.MoveOperation.End if backwards else cursor.MoveOperation.Start)
                browser.setTextCursor(cursor)
            found = browser.find(term, flags)
            if not found and not from_start:
                cursor = browser.textCursor()
                cursor.movePosition(cursor.MoveOperation.End if backwards else cursor.MoveOperation.Start)
                browser.setTextCursor(cursor)
                found = browser.find(term, flags)
            if found:
                search_status.setText(help_ui[8])
                browser.ensureCursorVisible()
            else:
                search_status.setText(help_ui[9].format(term=term))

        search_input.textChanged.connect(lambda _text: navigate_help_search(from_start=True))
        search_input.returnPressed.connect(lambda: navigate_help_search())
        previous_button.clicked.connect(lambda: navigate_help_search(backwards=True))
        next_button.clicked.connect(lambda: navigate_help_search())
        close_button = QPushButton(help_ui[10])
        close_button.clicked.connect(dialog.accept)
        layout.addWidget(close_button, alignment=Qt.AlignmentFlag.AlignRight)
        dialog.exec()

    def ai_launcher_detailed_guide_html(self):
        """Ausführliche, offline verfügbare Bedienungsanleitung aller AI-Launcher-Elemente."""
        language = self.effective_language()
        if language == 'en':
            return self.ai_launcher_english_guide_html()
        if language == 'de':
            return self.ai_launcher_german_guide_html()
        # The generic guide has translated headings, introduction and controls
        # for French, Spanish and Italian; never display an empty document.
        return self.general_detailed_guide_html('AI Prompt Launcher')

    def ai_launcher_english_guide_html(self):
        """Complete English AI Prompt Launcher guide; never mix in German HTML."""
        return """
        <html><head><meta charset="utf-8"><style>
        body { font-family:sans-serif; font-size:10.5pt; line-height:1.4; }
        h2 { margin-bottom:3px; } h3 { margin-top:19px; margin-bottom:6px; }
        p { margin-top:3px; margin-bottom:9px; } li { margin-bottom:5px; }
        </style></head><body>
        <h2>AI Prompt Launcher – Complete Guide</h2>
        <p><b>Open Song Prompts Folder:</b> Opens the selected band's existing prompt archive in File Explorer. If the folder does not exist yet, this action will not create it; it is created when saving a prompt version.</p>
        <p><b>Automatic TXT backup:</b> Saving a new version also creates a text file in the band's fixed <code>Song-Prompts</code> subfolder. The file includes the song title, timestamp, version ID, Style and Lyrics. Existing files are never overwritten. This folder is not part of the editable project-folder template.</p>
        <p>The launcher creates and imports Suno prompts, checks Style and Lyrics, stores different versions, and transfers selected versions to Songs. All operations use the currently selected band and project.</p>
        <h3>1. Select band and target song</h3>
        <p><b>Band:</b> Determines which band owns the prompt. Changing the band reloads the available projects.</p>
        <p><b>Target song / project:</b> Select the project for this prompt. The project name is used as the target song. A project can exist without a song database record.</p>
        <p><b>Create song entry:</b> After confirmation, creates a missing song record using the project name. An existing record is not duplicated; project folders and files remain unchanged. A song record is required for API generation, importing and saving.</p>
        <h3>2. Configure AI and hardware</h3>
        <p><b>AI platform:</b> Choose ChatGPT, Gemini or Claude. This selects the API provider and the website opened in your browser; imported text is also labeled with its source.</p>
        <p><b>Hardware for this prompt:</b> Choose an existing hardware preset. Without a preset, the API instruction uses the instruments and hardware from the band profile. This does not modify saved band hardware.</p>
        <p><b>API model:</b> Enter the model name for the selected provider. A suggested value is supplied when changing platforms; availability depends on the provider.</p>
        <p><b>API key (optional):</b> Enter an API key or use <code>OPENAI_API_KEY</code>, <code>GEMINI_API_KEY</code> or <code>ANTHROPIC_API_KEY</code> from the environment. The input is masked. API requests may incur charges.</p>
        <p><b>CLI command:</b> Name or full path of a locally installed AI command-line tool, used by <b>Generate prompt (CLI)</b>. Changing the platform fills in the default: <code>claude</code> (Claude Code) for Claude, <code>gemini</code> (Gemini CLI) for Gemini and <code>codex</code> (Codex CLI) for ChatGPT. A custom path you entered is kept. The CLI uses its own sign-in (e.g. your subscription), so no API key is needed in MPW.</p>
        <p><b>CLI model:</b> Optional model name for the CLI. Leave empty to use the CLI's default model. CLI model names can differ from API model names.</p>
        <p><b>Check CLI:</b> Looks for the CLI and shows the path found. Nothing is sent to the AI.</p>
        <p><b>Song idea / instruction:</b> Describe the theme, genres, mood, instruments, language and requirements. API generation also incorporates the band name, song title, genres, persona and chosen hardware.</p>
        <h3>3. Generate or import a prompt</h3>
        <p><b>Generate prompt (API):</b> Sends the assembled instruction to the selected provider. Requires a song record, valid model and API key. The response is split into Style and Lyrics when possible, but is <b>not saved automatically</b>. Review both fields, then save a version.</p>
        <p><b>Generate prompt (CLI):</b> Sends the same instruction to the CLI entered under <b>CLI command</b>. The text is passed directly to the program, without a command shell or console window. The CLI runs in an empty temporary folder that is deleted afterwards, so it cannot see project files or the MPW database; Codex additionally runs read-only. The request is stopped after 5 minutes. As with the API, the answer is only placed in Style and Lyrics and is <b>not saved automatically</b>. Requirement: start the CLI once in a terminal and sign in.</p>
        <p><b>Open platform in browser:</b> Copies the assembled instruction to the clipboard and opens the selected AI website. Paste it there. The response is <b>not sent back automatically</b>; copy and import the result yourself.</p>
        <p><b>Prompt from clipboard:</b> Reads copied text from the Windows clipboard and distributes recognized Style and Lyrics sections into their editors.</p>
        <p><b>Prompt from file:</b> Imports a local UTF-8 <code>.txt</code>, <code>.md</code> or <code>.json</code> file, up to 2 MB.</p>
        <p><b>Prompt from web link:</b> Loads a directly accessible public HTTPS file ending in <code>.txt</code>, <code>.md</code> or <code>.json</code>. Shared chat pages, private network addresses and automatic redirects are unsupported; maximum 2 MB.</p>
        <p><b>Validate imported prompt:</b> Checks that Style and Lyrics are present and meet Suno character limits. Correct any errors in the editors and validate again.</p>
        <p><b>Import source and status:</b> Displays whether content came from the clipboard, file or web link, plus feedback on API calls, validation and saving.</p>
        <h3>4. Edit Style and Lyrics</h3>
        <p><b>Style:</b> Separate editor for genre, arrangement, instrumentation and production requirements. <b>Maximum 1,000 characters.</b></p>
        <p><b>Lyrics:</b> Separate editor for song text, sections such as <code>[Verse 1]</code> and <code>[Chorus]</code>, and production instructions. <b>Maximum 5,000 characters.</b></p>
        <p><b>Character counters:</b> Show the current lengths and warn about empty fields or exceeded limits. Do not type <code>[STYLE]</code>, <code>[/STYLE]</code>, <code>[LYRICS]</code> or <code>[/LYRICS]</code> into the editors; MPW adds these markers when exporting text.</p>
        <p><b>Save as new version:</b> Enabled when a song record is selected and both texts are valid. Saves a new version with provider, model and song idea in the MPW database. The active prompt in Songs &amp; Suno remains unchanged.</p>
        <h3>5. Manage saved versions</h3>
        <p><b>Saved prompt versions:</b> Lists versions for this song with version number, provider, model and date; newest first. The list updates when the project changes.</p>
        <p><b>Version A / Version B:</b> Select two versions to compare, including the active song prompt currently shown in Songs &amp; Suno.</p>
        <p><b>Show differences:</b> Compares Style and Lyrics line by line. Choose two different versions; unchanged sections are identified in the comparison output.</p>
        <p><b>Apply Version B to song editor:</b> Makes the selected saved version the active song prompt. MPW asks for confirmation and saves the previous active prompt as a backup version. Other song metadata and versions remain intact.</p>
        <p><b>Export Version B to project:</b> Writes the selected version as UTF-8 text to the existing project folder <code>Dokumente</code>, for example <code>Suno_Prompt_Version_12.txt</code>. Style and Lyrics markers are added automatically. If the folder is missing, export is not performed; overwriting an existing file requires confirmation.</p>
        <p><b>Comparison output:</b> Displays differences in a read-only text area without changing prompts.</p>
        <h3>6. Recommended workflow</h3><ol>
        <li>Select the band and target song / project.</li>
        <li>Create a song record if needed.</li>
        <li>Choose the AI platform, hardware preset and song idea.</li>
        <li>Generate via API or CLI, or import via browser, clipboard, file or web link.</li>
        <li>Review and edit Style and Lyrics separately.</li>
        <li>Check character limits and save as a new version.</li>
        <li>Optionally compare versions, apply Version B to the active song, or export it as text.</li>
        </ol>
        <h3>7. Frequently asked questions and errors</h3>
        <p><b>Invalid Style/Lyrics structure:</b> Imported text could not be separated into both sections. Paste Style and Lyrics directly into their respective editors.</p>
        <p><b>Save button disabled:</b> Check that a song record exists, both fields contain text and neither character limit is exceeded.</p>
        <p><b>Missing API key:</b> Enter a key or configure the appropriate environment variable. Browser-based prompting does not require an API key in MPW.</p>
        <p><b>CLI not found:</b> Install the CLI or enter its full path under <b>CLI command</b>, then use <b>Check CLI</b>. Programs installed via npm are usually found in <code>%APPDATA%\\npm</code>.</p>
        <p><b>CLI exited with error code:</b> Usually the CLI is not signed in or the CLI model is unknown. Start the CLI once in a terminal, sign in, and leave <b>CLI model</b> empty if unsure.</p>
        <p><b>Cannot export:</b> Select a saved Version B and ensure the project's <code>Dokumente</code> folder exists.</p>
        <p><b>Where is the data stored?</b> Prompt versions are stored in the central MPW database under the configured band root in the <code>MPW</code> subfolder. Exported text files are written to the project's <code>Dokumente</code> folder.</p>
        </body></html>
        """

    def ai_launcher_german_guide_html(self):
        """Complete German AI Prompt Launcher help, separate from English."""
        return """
        <html><head><meta charset="utf-8"><style>
        body { font-family: sans-serif; font-size: 10.5pt; line-height: 1.4; }
        h2 { margin-bottom: 3px; } h3 { margin-top: 19px; margin-bottom: 6px; }
        h4 { margin-bottom: 3px; } p { margin-top: 3px; margin-bottom: 9px; }
        li { margin-bottom: 5px; } code { font-family: monospace; }
        </style></head><body>
        <h2>AI Prompt Launcher – vollständige Anleitung</h2><p><b>Song-Prompts-Ordner öffnen:</b> Öffnet den vorhandenen Archivordner der ausgewählten Band im Dateiexplorer. Fehlt der Ordner noch, wird er durch diese Aktion nicht angelegt; die automatische Anlage erfolgt erst beim Speichern einer Prompt-Version.</p><p><b>Automatische TXT-Sicherung:</b> Beim Klick auf „Als neue Version speichern“ wird zusätzlich im festen Band-Unterordner „Song-Prompts“ eine Textdatei mit Songtitel, Zeitstempel, Versions-ID, Style und Lyrics erstellt. Vorhandene Dateien werden niemals überschrieben. Der Ordner ist nicht Teil der editierbaren Projektordner-Vorlage.</p>
        <p>Der Launcher erstellt und importiert Suno-Prompts, prüft Style und Lyrics,
        speichert unterschiedliche Fassungen und überträgt ausgewählte Versionen in Songs.
        Alle Arbeitsschritte beziehen sich auf die aktuell ausgewählte Band und das Projekt.</p>

        <h3>1. Band und Ziel-Song auswählen</h3>
        <p><b>Band:</b> Legt fest, zu welcher Band der Prompt gehört. Die Projektauswahl wird
        beim Wechsel der Band neu geladen.</p>
        <p><b>Ziel-Song / Projekt:</b> Wähle das Projekt, für das du einen Prompt bearbeiten
        möchtest. Der Projektname dient als Ziel-Song. Ein Projekt kann bereits existieren,
        obwohl noch kein Song-Datenbankeintrag vorhanden ist.</p>
        <p><b>Song-Eintrag anlegen:</b> Erstellt nach einer Rückfrage einen fehlenden
        Song-Datenbankeintrag mit dem Projektnamen. Existiert bereits ein Eintrag, wird
        kein weiterer angelegt. Vorhandene Projektordner und Dateien bleiben unverändert.
        Für API-Erstellung, Import und Speichern wird ein Song-Eintrag benötigt.</p>

        <h3>2. KI und Hardware konfigurieren</h3>
        <p><b>KI-Plattform:</b> Auswahl zwischen ChatGPT, Gemini und Claude. Die Auswahl
        bestimmt den API-Anbieter und die Webseite, die über den Browser geöffnet wird.
        Bei manuell importierten Texten dient sie außerdem zur Kennzeichnung der Herkunft.</p>
        <p><b>Hardware für diesen Prompt:</b> Wählt ein vorhandenes Hardware-Preset.
        Ist kein Preset gewählt, verwendet die API-Anweisung die im Bandprofil
        hinterlegten Instrumente und Hardwareangaben. Die Auswahl verändert keine
        gespeicherten Band-Hardwaredaten.</p>
        <p><b>API-Modell:</b> Bezeichnung des gewünschten KI-Modells. Beim Wechsel der
        KI-Plattform wird ein Vorschlagswert eingetragen; das Modell kann angepasst
        werden. Die Verfügbarkeit hängt vom jeweiligen Anbieter ab.</p>
        <p><b>API-Schlüssel (optional):</b> Zugangsschlüssel für die direkte API-Erstellung.
        Alternativ wird eine Umgebungsvariable gelesen: <code>OPENAI_API_KEY</code>,
        <code>GEMINI_API_KEY</code> oder <code>ANTHROPIC_API_KEY</code>.
        Das Eingabefeld ist als Passwortfeld ausgeführt. API-Anfragen können Kosten verursachen.</p>
        <p><b>CLI-Befehl:</b> Name oder vollständiger Pfad einer lokal installierten
        KI-Kommandozeile für „Prompt erstellen (CLI)“. Beim Wechsel der KI-Plattform wird
        der Standard eingetragen: <code>claude</code> (Claude Code) für Claude,
        <code>gemini</code> (Gemini CLI) für Gemini und <code>codex</code> (Codex CLI)
        für ChatGPT. Ein selbst eingetragener Pfad bleibt erhalten. Die CLI nutzt ihre
        eigene Anmeldung (z. B. dein Abo); in MPW ist kein API-Schlüssel nötig.</p>
        <p><b>CLI-Modell:</b> Optionaler Modellname für die CLI. Leer lassen, um das
        Standardmodell der CLI zu verwenden. CLI-Modellnamen können von den
        API-Modellnamen abweichen.</p>
        <p><b>CLI prüfen:</b> Sucht die CLI und zeigt den gefundenen Pfad an.
        Es wird nichts an die KI gesendet.</p>
        <p><b>Songidee / Anweisung:</b> Hier beschreibst du Thema, Genres, Atmosphäre,
        Instrumente, Sprache und weitere Wünsche. Bei der API-Erstellung fließen außerdem
        Bandname, Songtitel, Genres, Persona und die gewählte Hardware in die Anweisung ein.</p>

        <h3>3. Prompt erzeugen oder importieren</h3>
        <p><b>Prompt erstellen (API):</b> Sendet die zusammengestellte Songanweisung
        an den ausgewählten KI-Anbieter. Erfordert einen Song-Eintrag, ein gültiges
        API-Modell und einen API-Schlüssel. Die Antwort wird nach Möglichkeit in Style
        und Lyrics aufgeteilt. Sie wird <b>nicht automatisch gespeichert</b>.
        Kontrolliere beide Felder und speichere anschließend eine Version.</p>
        <p><b>Prompt erstellen (CLI):</b> Sendet dieselbe Songanweisung an die unter
        „CLI-Befehl“ eingetragene CLI. Der Text wird direkt an das Programm übergeben,
        ohne Kommandoshell und ohne Konsolenfenster. Die CLI läuft in einem leeren
        Temp-Ordner, der danach gelöscht wird; Projektdateien und die MPW-Datenbank
        sieht sie nicht. Codex läuft zusätzlich nur mit Leserechten. Nach 5 Minuten
        wird die Anfrage abgebrochen. Wie bei der API landet die Antwort nur in Style
        und Lyrics und wird <b>nicht automatisch gespeichert</b>. Voraussetzung: CLI
        einmal in einem Terminal starten und anmelden.</p>
        <p><b>Plattform im Browser öffnen:</b> Kopiert die zusammengestellte
        Songanweisung in die Zwischenablage und öffnet die gewählte KI-Webseite.
        Füge die Anweisung dort ein. Das Ergebnis wird <b>nicht automatisch</b>
        an MPW zurückgesendet; kopiere es anschließend zurück und importiere es.</p>
        <p><b>Prompt aus Zwischenablage:</b> Liest einen kopierten Prompt-Text
        aus der Windows-Zwischenablage und verteilt erkannte Style-/Lyrics-Bereiche
        auf die beiden Editoren.</p>
        <p><b>Prompt aus Datei:</b> Importiert eine lokale <code>.txt</code>-,
        <code>.md</code>- oder <code>.json</code>-Datei in UTF-8.
        Die Datei darf höchstens 2 MB groß sein.</p>
        <p><b>Prompt über Weblink:</b> Liest eine direkt erreichbare, öffentliche
        HTTPS-Datei mit der Endung <code>.txt</code>, <code>.md</code> oder
        <code>.json</code>. Chat-Freigabeseiten, private Netzwerkadressen und
        automatische Weiterleitungen werden nicht unterstützt; maximal 2 MB.</p>
        <p><b>Importierten Prompt prüfen:</b> Kontrolliert, ob Style und Lyrics
        vorhanden sind und innerhalb der Suno-Zeichenlimits liegen.
        Bei einem Fehler die Texte in den Editoren korrigieren und erneut prüfen.</p>
        <p><b>Importquelle:</b> Zeigt an, ob der Text beispielsweise aus der
        Zwischenablage, einer Datei oder einem Weblink übernommen wurde.
        <b>Status-/Hinweiszeile:</b> Zeigt Rückmeldungen zu API-Aufrufen,
        Importprüfung und Speicherung an.</p>

        <h3>4. Style und Lyrics bearbeiten</h3>
        <p><b>Style:</b> Eigenständiger Editor für Musikrichtung, Arrangement,
        Instrumentierung und Produktionsvorgaben. <b>Maximal 1.000 Zeichen.</b></p>
        <p><b>Lyrics:</b> Eigenständiger Editor für Songtext, Abschnitte wie
        <code>[Verse 1]</code> oder <code>[Chorus]</code> sowie Produktionsanweisungen.
        <b>Maximal 5.000 Zeichen.</b></p>
        <p><b>Zeichenzähler:</b> Zeigt laufend die Zeichenzahl beider Editoren
        und meldet leere Felder oder überschrittene Limits. Die Abschnittsmarkierungen
        <code>[STYLE]</code>, <code>[/STYLE]</code>, <code>[LYRICS]</code> und
        <code>[/LYRICS]</code> gehören <b>nicht</b> in die Eingabefelder.
        MPW ergänzt sie beim Text-Export automatisch.</p>
        <p><b>Als neue Version speichern:</b> Wird aktiv, wenn ein Song-Eintrag
        gewählt ist und beide Texte gültig sind. Legt eine neue Fassung in der
        MPW-Datenbank ab, zusammen mit Anbieter, Modell und Songidee.
        Der aktive Prompt im Reiter „Songs &amp; Suno“ bleibt unverändert.
        Die Schaltfläche erstellt <b>nicht automatisch</b> eine TXT-Datei.</p>

        <h3>5. Gespeicherte Versionen verwalten</h3>
        <p><b>Gespeicherte Prompt-Versionen:</b> Liste der zu diesem Song
        vorhandenen Fassungen, mit Versionsnummer, Anbieter, Modell und Zeitangabe.
        Die jüngsten Einträge stehen oben. Beim Projektwechsel wird die Liste aktualisiert.</p>
        <p><b>Version A / Version B:</b> Zwei Auswahllisten für den Vergleich.
        Beide enthalten auch „Aktiver Song-Prompt“, also den derzeitigen
        Style-/Lyrics-Stand aus „Songs &amp; Suno“.</p>
        <p><b>Unterschiede anzeigen:</b> Vergleicht Style und Lyrics zeilenweise.
        Wähle zwei unterschiedliche Einträge. Das Ergebnis erscheint im unteren
        Vergleichsfeld; unveränderte Abschnitte werden als solche gekennzeichnet.</p>
        <p><b>Version B in Song-Editor übernehmen:</b> Macht eine gespeicherte
        Version zum aktiven Prompt des Songs. Vor dem Ersetzen fragt MPW nach
        Bestätigung und speichert den bisherigen aktiven Prompt als Sicherungsversion.
        Song-Metadaten und andere Versionen bleiben bestehen.</p>
        <p><b>Version B ins Projekt exportieren:</b> Schreibt die ausgewählte
        gespeicherte Version als UTF-8-Textdatei in den vorhandenen Projektordner
        <code>Dokumente</code>, z. B. <code>Suno_Prompt_Version_12.txt</code>.
        Die Style-/Lyrics-Markierungen werden automatisch ergänzt.
        Fehlt der Ordner, erfolgt kein Export; vorhandene Dateien werden nur
        nach Bestätigung überschrieben.</p>
        <p><b>Vergleichsausgabe:</b> Schreibt die gefundenen Unterschiede in
        ein schreibgeschütztes Textfeld. Die Anzeige ändert keine Prompts.</p>

        <h3>6. Empfohlener Arbeitsablauf</h3>
        <ol>
        <li>Band und Ziel-Song / Projekt auswählen.</li>
        <li>Falls nötig, „Song-Eintrag anlegen“ anklicken.</li>
        <li>KI-Plattform, Hardware-Preset und Songidee festlegen.</li>
        <li>Prompt per API oder CLI erzeugen oder über Browser, Zwischenablage, Datei
        beziehungsweise Weblink importieren.</li>
        <li>Style und Lyrics in ihren getrennten Feldern kontrollieren und
        gegebenenfalls bearbeiten.</li>
        <li>Zeichenlimits prüfen und „Als neue Version speichern“ wählen.</li>
        <li>Bei Bedarf Version A und B vergleichen, Version B in den aktiven
        Song übernehmen oder als Textdatei in „Dokumente“ exportieren.</li>
        </ol>
        <h3>7. Häufige Fragen und Fehlermeldungen</h3>
        <p><b>„Keine gültige Style/Lyrics-Struktur“:</b> Der Importtext konnte
        nicht automatisch in beide Bereiche zerlegt werden. Bei manueller
        Eingabe die Texte direkt in die getrennten Editoren einfügen.</p>
        <p><b>Speichern ist deaktiviert:</b> Prüfe Song-Eintrag, leere Felder
        und Zeichenlimits (Style 1.000, Lyrics 5.000).</p>
        <p><b>API-Schlüssel fehlt:</b> Schlüssel im Feld eingeben oder passende
        Umgebungsvariable einrichten. Für den Browsermodus ist keine API-Eingabe nötig.</p>
        <p><b>CLI nicht gefunden:</b> CLI installieren oder den vollständigen Pfad
        unter „CLI-Befehl“ eintragen und mit „CLI prüfen“ kontrollieren. Über npm
        installierte Programme liegen meist in <code>%APPDATA%\\npm</code>.</p>
        <p><b>CLI mit Fehlercode beendet:</b> Meist ist die CLI nicht angemeldet
        oder das CLI-Modell unbekannt. CLI einmal in einem Terminal starten,
        anmelden und „CLI-Modell“ im Zweifel leer lassen.</p>
        <p><b>Export nicht möglich:</b> Wähle unter Version B eine gespeicherte
        Fassung und prüfe, ob der Projektordner „Dokumente“ existiert.</p>
        <p><b>Wo liegen die Daten?</b> Gespeicherte Prompt-Versionen liegen in
        der zentralen MPW-Datenbank unter dem eingestellten Band-Stammordner
        im Unterordner <code>MPW</code>. Textdateien entstehen nur beim Export
        im jeweiligen Projektordner <code>Dokumente</code>.</p>
        </body></html>
        """

    def install_field_help(self):
        """Provide hover descriptions on field labels throughout every tab.

        Run after all tabs are constructed so labels from nested forms, groups,
        and scrollable pages are included. Existing widget tooltips are retained.
        """
        descriptions = {
            'Band': 'Wähle die Band, der der Song oder das Projekt zugeordnet wird.',
            'Bandname': 'Name der Band; dient zur eindeutigen Zuordnung von Song/Projekten.',
            'Ziel-Song': 'Song beziehungsweise Projekt, für das der KI-Prompt erstellt wird.',
            'Ziel-Song / Projekt': 'Wähle das Projekt der Band. Der Projektname wird als Ziel-Song verwendet.',
            'KI-Plattform': 'Wähle den KI-Dienst, der den Prompt erstellt oder importiert.',
            'Hardware für diesen Prompt': 'Wähle die Instrumenten- und Studiohardware-Vorgabe für den Prompt.',
            'API-Modell': 'Modellbezeichnung des ausgewählten KI-Dienstes, sofern eine API genutzt wird.',
            'API-Schlüssel (optional)': 'Optionaler persönlicher API-Zugang. Wird nur für die aktuelle Sitzung verwendet.',
            'Songidee / Anweisung': 'Beschreibe Thema, Genre, Instrumente und gewünschte Besonderheiten des Songs.',
            'Style (maximal 1.000 Zeichen)': 'Nur Musikstil und Soundbeschreibung eingeben. Maximal 1.000 Zeichen; Abschnittsmarkierungen werden beim Export ergänzt.',
            'Lyrics (maximal 5.000 Zeichen)': 'Songtext und Produktionsanweisungen eingeben. Maximal 5.000 Zeichen; Abschnittsmarkierungen werden beim Export ergänzt.',
            'Gespeicherte Prompt-Versionen': 'Hier findest du frühere Prompt-Fassungen des gewählten Songs.',
            'Version A': 'Erste gespeicherte Prompt-Version für den Vergleich.',
            'Version B': 'Zweite gespeicherte Prompt-Version; kann übernommen oder exportiert werden.',
            'Speicherort für neue Bands': 'Übergeordneter Ordner für Bands. MPW-Programmdaten liegen im Unterordner MPW.',
            'Datenbank': 'Speicherort der MPW-Datenbank mit Bands, Songs, Song/Projekten und Prompt-Versionen.',
            'Mediendateien': 'Ordner für die von MPW verwalteten Mediendateien.',
            'Konfigurationsdatei': 'Datei mit den gespeicherten MPW-Einstellungen.',
            'Beim Start anzeigen': 'Legt fest, welcher Reiter beim Programmstart geöffnet wird.',
            'Release-Datum': 'Datum, an dem die Veröffentlichung erscheinen soll oder erschienen ist.',
            'Veröffentlichung': 'Veröffentlichungsdatum des Albums.',
            'Genre': 'Musikalische Stilrichtung des Songs oder Albums.',
            'Label': 'Name des Musiklabels für die Veröffentlichung.',
            'UPC / EAN': 'Internationaler Produktcode der Albumveröffentlichung.',
            'Sicherungsintervall': 'Zeitlicher Abstand zwischen automatischen Sicherungen.',
            'Aufbewahrung': 'Anzahl oder Zeitraum der Backups, die MPW behalten soll.',
            'Vorlage': 'Wähle eine vordefinierte Farbkombination für die Benutzeroberfläche.',
            'Eigene Vorlagen': 'Verwalte selbst gespeicherte Farbvorlagen.',
            'Vorlagen austauschen': 'Importiere oder exportiere Farbvorlagen als Datei.',
            'Unverbindlich testen': 'Zeigt die ausgewählte Farbvorlage als Vorschau, ohne sie dauerhaft zu speichern.',
            'PNG-Hintergrund': 'Optionales PNG-Bild als Hintergrund der Programmoberfläche.',
            'Gespeicherte Motive': 'Bereits in MPW gespeicherte Hintergrundbilder.',
            'Motiv-Vorschau': 'Vorschau der gespeicherten Hintergrundmotive.',
            'Bildanpassung': 'Legt fest, wie das Hintergrundbild auf die verfügbare Fläche skaliert wird.',
            'Deckkraft': 'Steuert, wie stark das Hintergrundbild sichtbar ist.',
        }
        import re

        def normalize(value):
            value = re.sub(r'<[^>]*>', '', str(value or ''))
            return re.sub(r'\s+', ' ', value).strip().rstrip(':').strip()

        def describe(label):
            key = normalize(label)
            if not key:
                return ''
            if key in descriptions:
                return descriptions[key]
            lower = key.casefold()
            if 'pfad' in lower or 'ordner' in lower or 'speicherort' in lower:
                return f'{key}: Hier wird der zugehörige Ordner oder Dateipfad festgelegt beziehungsweise angezeigt.'
            if 'datum' in lower:
                return f'{key}: Hier wird das zugehörige Datum ausgewählt oder angezeigt.'
            if 'status' in lower:
                return f'{key}: Zeigt oder ändert den aktuellen Bearbeitungsstand.'
            if 'name' in lower or 'titel' in lower:
                return f'{key}: Trage hier die entsprechende Bezeichnung ein oder wähle sie aus.'
            if 'genre' in lower or 'stil' in lower:
                return f'{key}: Musikalische Einordnung oder Stilbeschreibung auswählen.'
            if 'version' in lower:
                return f'{key}: Wähle die entsprechende gespeicherte Fassung aus.'
            return f'{key}: Dieses Feld enthält die zugehörige Angabe. Bewege die Maus über das Eingabefeld, um vorhandene zusätzliche Hinweise zu sehen.'

        # Form labels, including auto-generated labels from QFormLayout.addRow().
        for form in self.findChildren(QFormLayout):
            for row in range(form.rowCount()):
                label_item = form.itemAt(row, QFormLayout.ItemRole.LabelRole)
                field_item = form.itemAt(row, QFormLayout.ItemRole.FieldRole)
                label = label_item.widget() if label_item else None
                field = field_item.widget() if field_item else None
                if isinstance(label, QLabel):
                    help_text = describe(label.text())
                    if help_text:
                        label.setToolTip(help_text)
                        label.setStatusTip(help_text)
                        if field is not None and not field.toolTip():
                            field.setToolTip(help_text)

        # Also covers field labels built with QVBoxLayout / QHBoxLayout.
        for label in self.findChildren(QLabel):
            if label.toolTip():
                continue
            name = normalize(label.text())
            if not name or len(name) > 75 or '\n' in label.text():
                continue
            # Only field-like labels; do not turn status and explanatory text into help labels.
            if (name in descriptions or name.endswith(':') or
                    any(word in name.casefold() for word in ('style (maximal', 'lyrics (maximal', 'version a', 'version b'))):
                help_text = describe(name)
                label.setToolTip(help_text)
                label.setStatusTip(help_text)

