    def backup_validation_text(self, key, **values):
        variants = self.BACKUP_VALIDATION_TRANSLATIONS[key]
        return variants.get(self.effective_language(), variants["en"]).format(**values)

    def backup_selection_text(self, key, **values):
        variants = self.BACKUP_SELECTION_TRANSLATIONS[key]
        return variants.get(self.effective_language(), variants["en"]).format(**values)

    def backup_dialog_text(self, key, **values):
        variants = self.BACKUP_DIALOG_TRANSLATIONS[key]
        return variants.get(self.effective_language(), variants["en"]).format(**values)

    def dynamic_confirmation_text(self, key, **values):
        variants = self.DYNAMIC_CONFIRMATION_TRANSLATIONS[key]
        return variants.get(self.effective_language(), variants["en"]).format(**values)

    def confirmation_text(self, key, **values):
        translations = self.CONFIRMATION_TRANSLATIONS[key]
        language = self.effective_language()
        template = translations.get(language, translations['en'])
        return template.format(**values)

