    def backup_scan_text(self, key, **values):
        language = self.effective_language()
        return self.BACKUP_SCAN_I18N.get(language, self.BACKUP_SCAN_I18N['en'])[key].format(**values)

    def localized_message_text(self, text):
        """Translate known user-facing message bodies without changing program data."""
        original = str(text)
        return self.UI_MESSAGE_TRANSLATIONS.get(self.effective_language(), {}).get(original, original)

    def message(self, title, text):
        QMessageBox.information(self, self.localized_dialog_title(title), self.localized_message_text(text))

    def error(self, exc):
        LOGGER.error('Behandelter Anwendungsfehler: %s', exc)
        QMessageBox.warning(self, self.localized_dialog_title('Hinweis'), self.localized_message_text(exc))

    def text(self, layout, title, default=''):
        edit = QLineEdit(default)
        layout.addRow(title, edit)
        return edit

    def combo(self, layout, title, values=None):
        cb = QComboBox()
        if values:
            cb.addItems(values)
        layout.addRow(title, cb)
        return cb

    def build_bands(self):
        page = BackgroundPage(); layout = QVBoxLayout(page)
        group = QGroupBox('Bandprofil'); form = QFormLayout(group)
        self.band_name = self.text(form, 'Band / Künstler')
        self.genre = self.combo(form, 'Hauptgenre')
        self.second = self.combo(form, 'Zweitgenre')
        for genre_combo in (self.genre, self.second):
            genre_combo.setEditable(True)
            genre_combo.setInsertPolicy(QComboBox.InsertPolicy.NoInsert)
            genre_combo.setMaxVisibleItems(20)
        self.persona = self.combo(form, 'Persona', ['Keep Current','Keine','Individuell'])
        band_actions = QHBoxLayout()
        add = QPushButton('Band anlegen'); add.clicked.connect(self.add_band); band_actions.addWidget(add)
        update = QPushButton('Ausgewähltes Bandprofil speichern'); update.clicked.connect(self.update_band); band_actions.addWidget(update)
        seed = QPushButton('Mondfunken Kollektiv Beispielprofil anlegen'); seed.clicked.connect(self.seed); band_actions.addWidget(seed)
        form.addRow(band_actions)
        layout.addWidget(group)
        self.band_list = QListWidget(); layout.addWidget(self.band_list, 1)
        self.band_list.currentItemChanged.connect(self.load_band)
        self.band_list.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.band_list.customContextMenuRequested.connect(self.show_band_context_menu)
        inst = QGroupBox('Instrumente / Hardware'); inf = QFormLayout(inst)
        self.inst_band = self.combo(inf,'Band')
        # Editable menus: pick a saved entry or type a new one (like the genre menus above).
        self.inst_cat = self.combo(inf,'Gruppe')
        self.inst_detail = self.combo(inf,'Instrumente / Hardware')
        for hardware_combo in (self.inst_cat, self.inst_detail):
            hardware_combo.setEditable(True)
            hardware_combo.setInsertPolicy(QComboBox.InsertPolicy.NoInsert)
            hardware_combo.setMaxVisibleItems(20)
        self.inst_cat.currentTextChanged.connect(self.refresh_instrument_detail_choices)
        instrument_actions = QHBoxLayout()
        btn = QPushButton('Instrument hinzufügen'); btn.clicked.connect(self.add_instrument); instrument_actions.addWidget(btn)
        edit_btn = QPushButton('Ausgewählte Hardware speichern'); edit_btn.clicked.connect(self.update_instrument); instrument_actions.addWidget(edit_btn)
        delete_btn = QPushButton('Ausgewählte Hardware löschen'); delete_btn.clicked.connect(self.delete_instrument); instrument_actions.addWidget(delete_btn)
        inf.addRow(instrument_actions)
        layout.addWidget(inst)
        self.inst_list = QListWidget(); layout.addWidget(self.inst_list, 2)
        self.inst_band.currentIndexChanged.connect(self.refresh_instruments)
        self.inst_list.currentItemChanged.connect(self.load_instrument)
        presets = QGroupBox('Hardware-Preset-Bibliothek')
        preset_layout = QVBoxLayout(presets)
        preset_row = QHBoxLayout()
        self.preset_select = QComboBox()
        self.preset_select.setMinimumWidth(240)
        preset_row.addWidget(QLabel('Gespeichertes Setup'))
        preset_row.addWidget(self.preset_select, 1)
        preset_layout.addLayout(preset_row)
        # Target band for transferring a preset; follows the band above until changed here.
        target_row = QHBoxLayout()
        self.preset_target_band = QComboBox()
        self.preset_target_band.setMinimumWidth(240)
        target_row.addWidget(QLabel('Zielband'))
        target_row.addWidget(self.preset_target_band, 1)
        preset_layout.addLayout(target_row)
        self.inst_band.currentIndexChanged.connect(self.sync_preset_target_band)
        preset_actions = QHBoxLayout()
        for label, callback in [
            ('Band-Hardware als Preset speichern', self.save_hardware_preset),
            ('Preset zur Band hinzufügen', self.add_hardware_preset_to_band),
            ('Preset auf Band anwenden', self.apply_hardware_preset),
            ('Preset löschen', self.delete_hardware_preset),
        ]:
            button = QPushButton(label)
            button.clicked.connect(callback)
            preset_actions.addWidget(button)
        preset_layout.addLayout(preset_actions)
        layout.addWidget(presets)
        self.refresh_hardware_presets()
        layout.addStretch()
        self.tabs.addTab(self._scroll_page(page), 'Bands')

    def _scroll_page(self, page):
        from PySide6.QtWidgets import QScrollArea
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setWidget(page)
        scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        return scroll

    def build_projects(self):
        page = BackgroundPage()
        layout = QVBoxLayout(page)
        project = QGroupBox('Projekt erstellen'); pf = QFormLayout(project)
        self.project_band = self.combo(pf,'Band')
        self.project_name = self.text(pf,'Projektname')
        btn = QPushButton('Neues Projekt anlegen'); btn.clicked.connect(self.add_project)
        import_btn = QPushButton('Vorhandene Projektordner in Datenbank übernehmen')
        import_btn.clicked.connect(self.import_existing_projects)
        repair_all_btn = QPushButton('Fehlende Unterordner für alle Song/Projekte ergänzen')
        repair_all_btn.clicked.connect(self.repair_all_project_subfolders)
        update_project = QPushButton('Projektänderungen speichern')
        update_project.clicked.connect(self.update_project)
        # Four equally weighted project actions; guidance is available via Instructions.
        project_actions = QHBoxLayout()
        for action in (btn, import_btn, repair_all_btn, update_project):
            action.setMinimumWidth(0)
            project_actions.addWidget(action, 1)
        pf.addRow(project_actions)
        layout.addWidget(project)
        self.project_search = QLineEdit()
        self.project_search.setPlaceholderText('Song/Projekte nach Band oder Projektname suchen …')
