    def refresh_genre_static_hf6(self):
        if not all(hasattr(self, key) for key in ('genre_new', 'genre_search', 'genre_index')):
            return
        new_placeholder, search_placeholder, index_tooltip = self.GENRE_STATIC_HF6[self.effective_language()]
        self.genre_new.setPlaceholderText(new_placeholder)
        self.genre_search.setPlaceholderText(search_placeholder)
        self.genre_index.setToolTip(index_tooltip)

    def refresh_genre_index(self, *_):
        query = self.genre_search.text().strip().casefold()
        genres = [row[0] for row in self.con.execute('SELECT name FROM genre_catalog ORDER BY name COLLATE NOCASE')]
        visible = [genre for genre in genres if query in genre.casefold()]
        selected = self.genre_index.currentItem().text() if self.genre_index.currentItem() else None
        self.genre_index.clear()
        self.genre_index.addItems(visible)
        if selected in visible:
            self.genre_index.setCurrentRow(visible.index(selected))
        self.genre_index_count.setText(f'{len(visible)} von {len(genres)} Genres' if query else f'{len(genres)} Genres')

    def show_genre_context_menu(self, pos):
        item = self.genre_index.itemAt(pos)
        if item is None:
            return
        self.genre_index.setCurrentItem(item)
        name = item.text()
        menu = QMenu(self.genre_index)
        edit_action = menu.addAction(self.translated_context_label('Genre bearbeiten …'))
        delete_action = menu.addAction(self.translated_context_label('Genre löschen …'))
        action = menu.exec(self.genre_index.viewport().mapToGlobal(pos))
        if action == edit_action:
            self.edit_catalog_genre(name)
        elif action == delete_action:
            self.delete_catalog_genre(name)

