    def genre_dialog_text(self, key, **values):
        language = self.effective_language()
        return self.GENRE_DIALOG_I18N.get(language, self.GENRE_DIALOG_I18N['de'])[key].format(**values)

    def edit_catalog_genre(self, old_name):
        new_name, ok = QInputDialog.getText(
            self, self.genre_dialog_text('edit_title'), self.genre_dialog_text('new_name'), text=old_name)
        if not ok:
            return
        new_name = new_name.strip()
        if not new_name:
            return self.error(self.genre_dialog_text('empty'))
        if new_name == old_name:
            return
        duplicate = self.con.execute(
            'SELECT name FROM genre_catalog WHERE name=? COLLATE NOCASE AND name<>?',
            (new_name, old_name)).fetchone()
        if duplicate:
            return self.error(self.genre_dialog_text('duplicate', name=duplicate[0]))
        try:
            with self.con:
                self.con.execute('UPDATE genre_catalog SET name=? WHERE name=?', (new_name, old_name))
                self.con.execute('UPDATE bands SET genre=? WHERE genre=? COLLATE NOCASE', (new_name, old_name))
                self.con.execute('UPDATE bands SET second_genre=? WHERE second_genre=? COLLATE NOCASE', (new_name, old_name))
                self.con.execute('UPDATE albums SET genre=? WHERE genre=? COLLATE NOCASE', (new_name, old_name))
        except sqlite3.Error as exc:
            return self.error(self.genre_dialog_text('edit_error', error=exc))
        self.refresh_all()
        self.message(self.genre_dialog_text('edited_title'), self.genre_dialog_text('edited', old=old_name, new=new_name))

    def delete_catalog_genre(self, name):
        band_count = self.con.execute(
            'SELECT COUNT(*) FROM bands WHERE genre=? COLLATE NOCASE OR second_genre=? COLLATE NOCASE',
            (name, name)).fetchone()[0]
        album_count = self.con.execute(
            'SELECT COUNT(*) FROM albums WHERE genre=? COLLATE NOCASE', (name,)).fetchone()[0]
        if band_count or album_count:
            return self.error(
                self.genre_dialog_text('in_use', name=name, bands=band_count, albums=album_count))
        answer = QMessageBox.question(
            self, self.localized_dialog_title('Genre löschen'),
            self.confirmation_text('delete_genre', name=name),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if answer != QMessageBox.StandardButton.Yes:
            return
        try:
            with self.con:
                self.con.execute('DELETE FROM genre_catalog WHERE name=?', (name,))
        except sqlite3.Error as exc:
            return self.error(self.genre_dialog_text('delete_error', error=exc))
        self.refresh_all()
        self.message(self.genre_dialog_text('deleted_title'), self.genre_dialog_text('deleted', name=name))

    def refresh_hardware_presets(self):
        entries = self.con.execute('SELECT id,name FROM hardware_presets ORDER BY name COLLATE NOCASE').fetchall()
        self.set_combo(self.preset_select, [(name, pid) for pid, name in entries])

    def save_hardware_preset(self):
        bid = self.inst_band.currentData()
        if bid is None:
            return self.error('Bitte zuerst eine Band auswählen.')
        items = self.con.execute('SELECT category,details FROM instruments WHERE band_id=? ORDER BY id', (bid,)).fetchall()
        if not items:
            return self.error('Diese Band hat noch keine Hardware-Einträge.')
        name, ok = QInputDialog.getText(self, 'Hardware-Preset speichern', 'Name des Studio-Setups:')
        if not ok or not name.strip():
            return
        name = name.strip()
        existing = self.con.execute('SELECT id FROM hardware_presets WHERE name=? COLLATE NOCASE', (name,)).fetchone()
        if existing and QMessageBox.question(
            self, self.localized_dialog_title('Preset überschreiben'), self.confirmation_text('overwrite_preset', name=name),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No
        ) != QMessageBox.StandardButton.Yes:
            return
        with self.con:
            if existing:
                self.con.execute('UPDATE hardware_presets SET items_json=? WHERE id=?', (json.dumps(items, ensure_ascii=False), existing[0]))
            else:
                self.con.execute('INSERT INTO hardware_presets(name,items_json) VALUES(?,?)', (name,json.dumps(items,ensure_ascii=False)))
        self.refresh_hardware_presets()
        self.refresh_all()
        self.message('Hardware-Preset', f'„{name}“ mit {len(items)} Einträgen gespeichert.')

    def sync_preset_target_band(self, *args):
        """Default the preset target to the band chosen above; it can be changed afterwards."""
        index = self.preset_target_band.findData(self.inst_band.currentData())
        if index >= 0:
            self.preset_target_band.setCurrentIndex(index)

    def _selected_preset_and_target(self):
        """(preset name, items, band id, band name) or None after showing an error."""
        bid = self.preset_target_band.currentData()
        pid = self.preset_select.currentData()
        if bid is None or pid is None:
            self.error('Bitte Band und Hardware-Preset auswählen.')
            return None
        row = self.con.execute('SELECT name,items_json FROM hardware_presets WHERE id=?',(pid,)).fetchone()
        if not row:
            self.error('Das ausgewählte Preset wurde nicht gefunden.')
            return None
        try:
            items = json.loads(row[1])
            if not isinstance(items,list) or any(not isinstance(x,list) or len(x)!=2 or not all(isinstance(v,str) for v in x) for x in items):
                raise ValueError('Ungültige Preset-Daten.')
        except (ValueError, TypeError) as exc:
            self.error(f'Preset kann nicht geladen werden: {exc}')
            return None
        band = self.con.execute('SELECT name FROM bands WHERE id=?',(bid,)).fetchone()
        if not band:
            self.error('Bitte zuerst eine Band auswählen.')
            return None
        return row[0], items, bid, band[0]

    def show_band_hardware(self, bid):
        """After a transfer, show the target band's hardware in the list above."""
        index = self.inst_band.findData(bid)
        if index >= 0 and index != self.inst_band.currentIndex():
            self.inst_band.setCurrentIndex(index)  # triggers refresh_instruments
        else:
            self.refresh_instruments()

