    def preset_transfer_text(self, key, **values):
        texts = self.PRESET_TRANSFER_TEXTS.get(self.effective_language(), self.PRESET_TRANSFER_TEXTS['en'])
        return texts[key].format(**values)

    def add_hardware_preset_to_band(self):
        """Copy a preset to the target band without removing its existing hardware."""
        selected = self._selected_preset_and_target()
        if selected is None:
            return
        name, items, bid, band = selected
        existing = self.con.execute('SELECT category,details FROM instruments WHERE band_id=?',(bid,)).fetchall()
        new_items = preset_items_missing(existing, items)
        skipped = len(items) - len(new_items)
        if not new_items:
            return self.message('Hardware-Preset', self.preset_transfer_text('nothing', name=name, band=band))
        if QMessageBox.question(
            self, self.localized_dialog_title('Preset zur Band hinzufügen'),
            self.preset_transfer_text('confirm', name=name, band=band, new=len(new_items), skipped=skipped),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No
        ) != QMessageBox.StandardButton.Yes:
            return
        with self.con:
            self.con.executemany('INSERT INTO instruments(band_id,category,details) VALUES(?,?,?)',
                                 [(bid, cat, detail) for cat, detail in new_items])
        self.show_band_hardware(bid)
        self.message('Hardware-Preset', self.preset_transfer_text('added', name=name, band=band, new=len(new_items)))

    def apply_hardware_preset(self):
        """Replace the target band's hardware with the preset (after confirmation)."""
        selected = self._selected_preset_and_target()
        if selected is None:
            return
        name, items, bid, band = selected
        existing = self.con.execute('SELECT COUNT(*) FROM instruments WHERE band_id=?',(bid,)).fetchone()[0]
        choice = QMessageBox.question(
            self, self.localized_dialog_title('Hardware-Preset anwenden'),
            self.confirmation_text('apply_preset', name=name, count=len(items), band=band, existing=existing),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No
        )
        if choice != QMessageBox.StandardButton.Yes:
            return
        with self.con:
            self.con.execute('DELETE FROM instruments WHERE band_id=?',(bid,))
            self.con.executemany('INSERT INTO instruments(band_id,category,details) VALUES(?,?,?)', [(bid,cat,detail) for cat,detail in items])
        self.show_band_hardware(bid)
        self.message('Hardware-Preset', self.preset_transfer_text('replaced', name=name, band=band))

    def delete_hardware_preset(self):
        pid = self.preset_select.currentData()
        if pid is None:
            return self.error('Bitte ein Preset auswählen.')
        name = self.preset_select.currentText()
        if QMessageBox.question(self,self.localized_dialog_title('Preset löschen'),self.confirmation_text('delete_preset', name=name),
             QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
             QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
            return
        with self.con:
            self.con.execute('DELETE FROM hardware_presets WHERE id=?',(pid,))
        self.refresh_hardware_presets()
        self.refresh_all()

