        self.new_title.setPlaceholderText(t['title'])
        self.song_quick_search.setPlaceholderText(t['search'])
        self.song_dist.setPlaceholderText(t['dist'])
        self.song_platforms.setPlaceholderText(t['platforms'])
        for combo, text in ((self.song_band_filter, t['all_bands']), (self.song_select, t['select'])):
            if combo.count():
                combo.setItemText(0, text)
        selected = self.status.currentData()
        self.status.blockSignals(True)
        try:
            for index, text in enumerate(t['statuses']):
                self.status.setItemText(index, text)
            if selected is not None:
                idx = self.status.findData(selected)
                if idx >= 0:
                    self.status.setCurrentIndex(idx)
        finally:
            self.status.blockSignals(False)
        count = self.song_select.count() - 1
        self.song_result_count.setText(t['count'].format(n=max(0,count), suffix='' if count == 1 else 's'))

