    def ai_editor_values(self):
        """Return content only; delimiters never appear in the editor."""
        return self.ai_style.toPlainText().strip(), self.ai_lyrics.toPlainText().strip()

    def set_ai_editor_values(self, style, lyrics):
        self.ai_style.setPlainText(style)
        self.ai_lyrics.setPlainText(lyrics)
        self.update_ai_limits()

    def update_ai_limits(self):
        """Validate Suno limits using only the content of the two editors."""
        style, lyrics = self.ai_editor_values()
        valid = bool(style and lyrics and len(style) <= 1000 and len(lyrics) <= 5000)
        self.ai_limits.setText(f'Style: {len(style)}/1000 · Lyrics: {len(lyrics)}/5000 {self.AI17_TRANSLATIONS.get(self.effective_language(), {}).get("Zeichen", "Zeichen")}'
                               + (' · OK' if valid else ' · Limit überschritten oder Feld leer'))
        self.ai_save.setEnabled(valid and self.ai_selected_song_id() is not None)

    def export_ai_version_to_project(self):
        """Export a saved prompt into the existing project's Dokumente folder safely."""
        pid = self.ai_song.currentData()
        sid = self.ai_selected_song_id()
        vid = self.compare_right.currentData()
        if pid is None or sid is None or vid is None:
            return self.error('Bitte Band, Projekt und rechts eine gespeicherte Version auswählen.')
        row = self.con.execute(
            'SELECT p.name,b.name FROM projects p JOIN bands b ON b.id=p.band_id WHERE p.id=?',
            (pid,)).fetchone()
        if row is None:
            return self.error('Projekt nicht gefunden.')
        try:
            style, lyrics = self.prompt_for_compare(vid, sid)
            band_folder = self.existing_named_folder(self.band_root_directory(), row[1])
            project_folder = self.existing_named_folder(band_folder, row[0]) if band_folder else None
            docs = self.existing_named_folder(project_folder, 'Dokumente') if project_folder else None
            if docs is None:
                return self.error('Projektordner/Dokumente nicht gefunden. Es werden keine Ordner automatisch erstellt.')
            output = docs / f'Suno_Prompt_Version_{int(vid)}.txt'
            if output.exists():
                answer = QMessageBox.question(self, self.localized_dialog_title('Datei überschreiben?'),
                    f'Die Datei existiert bereits:\n{output}\n\nÜberschreiben?',
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                    QMessageBox.StandardButton.No)
                if answer != QMessageBox.StandardButton.Yes:
                    return
            payload = f'[STYLE]\n{style}\n[/STYLE]\n\n[LYRICS]\n{lyrics}\n[/LYRICS]\n'
            with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', newline='\n',
                                             dir=docs, prefix='.mpw_prompt_', suffix='.tmp', delete=False) as temp:
                temp.write(payload)
                temp_path = Path(temp.name)
            try:
                os.replace(temp_path, output)
            finally:
                temp_path.unlink(missing_ok=True)
        except (OSError, ValueError, sqlite3.Error) as exc:
            return self.error(f'Export fehlgeschlagen: {exc}')
        self.message('Prompt exportiert', f'Version #{vid} gespeichert unter:\n{output}')

    def refresh_ai_project_choices(self, *args):
        """Projekt-Auswahl der gewählten Band; Einträge ohne Song bleiben sichtbar."""
        old = self.ai_song.currentData()
        bid = self.ai_band.currentData()
        self.ai_song.blockSignals(True)
        self.ai_song.clear()
        if bid is not None:
            rows = self.con.execute(
                'SELECT id,name FROM projects WHERE band_id=? ORDER BY name COLLATE NOCASE', (bid,)
            ).fetchall()
            for pid, name in rows:
                self.ai_song.addItem(name, pid)
        index = self.ai_song.findData(old)
        if index >= 0:
            self.ai_song.setCurrentIndex(index)
        self.ai_song.blockSignals(False)
        self.refresh_ai_versions()

    def ai_selected_song_id(self):
        """Bestehenden Song-Eintrag zum gewählten Projekt ermitteln, ohne Daten zu verändern."""
        pid = self.ai_song.currentData()
        if pid is None:
            return None
        row = self.con.execute(
            'SELECT id FROM songs WHERE project_id=? ORDER BY id LIMIT 1', (pid,)
        ).fetchone()
        return row[0] if row else None

    def ensure_ai_project_song(self):
        """Fehlenden Song-Eintrag nur nach ausdrücklicher Bestätigung erzeugen."""
        pid = self.ai_song.currentData()
        if pid is None:
            return self.error('Bitte zuerst eine Band und ein Projekt auswählen.')
        existing = self.ai_selected_song_id()
        if existing is not None:
            return self.message('Song vorhanden', 'Für dieses Projekt existiert bereits ein Song-Eintrag.')
        row = self.con.execute('SELECT name FROM projects WHERE id=?', (pid,)).fetchone()
        if row is None:
            return self.error('Das ausgewählte Projekt existiert nicht mehr.')
        answer = QMessageBox.question(
            self, self.localized_dialog_title('Song-Eintrag anlegen?'),
            self.dynamic_confirmation_text('create_song', project=row[0]),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if answer != QMessageBox.StandardButton.Yes:
            return
        try:
            with self.con:
                self.con.execute('INSERT INTO songs(project_id,title) VALUES(?,?)', (pid, row[0]))
        except sqlite3.Error as exc:
            return self.error(f'Song-Eintrag konnte nicht erstellt werden: {exc}')
        self.refresh_all()
        self.message('Song angelegt', f'Der Ziel-Song „{row[0]}“ wurde dem Projekt zugeordnet.')

    def ai_provider_changed(self, *args):
        models = {'ChatGPT':'gpt-4.1-mini','Gemini':'gemini-2.5-flash','Claude':'claude-sonnet-5-5'}
        provider = self.ai_provider.currentText()
        self.ai_model.setText(models.get(provider,''))
        envs = {'ChatGPT':'OPENAI_API_KEY','Gemini':'GEMINI_API_KEY','Claude':'ANTHROPIC_API_KEY'}
        self.ai_key.setPlaceholderText('Alternativ: ' + envs.get(provider,''))
        # Only replace the CLI command if the user has not entered a custom name/path.
        current = self.ai_cli_command.text().strip()
        if not current or current in CLI_DEFAULT_COMMANDS.values():
            self.ai_cli_command.setText(CLI_DEFAULT_COMMANDS.get(provider, ''))
        self.ai_cli_command.setPlaceholderText(CLI_DEFAULT_COMMANDS.get(provider, ''))

    def ai_prompt(self, sid):
        return suno_prompt_request(self.con, sid, self.ai_hardware_preset.currentData(),
                                   self.ai_brief.toPlainText().strip())

    def generate_ai(self):
        sid = self.ai_selected_song_id()
        if sid is None: return self.error('Bitte einen Ziel-Song auswählen oder über „Song-Eintrag anlegen“ zuerst einen Song zum Projekt erstellen.')
        provider = self.ai_provider.currentText()
        envs = {'ChatGPT':'OPENAI_API_KEY','Gemini':'GEMINI_API_KEY','Claude':'ANTHROPIC_API_KEY'}
        key = self.ai_key.text().strip() or os.environ.get(envs[provider],'')
        if not key: return self.error('API-Schlüssel fehlt. Schlüssel eingeben oder Umgebungsvariable setzen.')
        model = self.ai_model.text().strip()
        if not model or not re.fullmatch(r'[a-zA-Z0-9._-]+',model): return self.error('Ungültiger Modellname.')
        try:
            prompt = self.ai_prompt(sid)
        except ValueError as exc:
            # e.g. a damaged hardware preset: nothing was sent, do not keep the key around.
            self.ai_key.clear()
            return self.error(str(exc))
        self.ai_pending = (sid,provider,model,self.ai_brief.toPlainText().strip())
        job = GenerationJob(provider,model,key,prompt)
        self.ai_job = job
        job.signals.finished.connect(self.ai_generated)
        job.signals.failed.connect(self.ai_failed)
        self.ai_generate.setEnabled(False)
        self.ai_info.setText('Anfrage läuft …')
        self.threadpool.start(job)

    def ai_cli_prompt(self, sid):
        """Same request as the API mode, plus a note that no files or tools are needed."""
        return (self.ai_prompt(sid) + '\nArbeite ohne Werkzeuge und ohne Dateizugriff; '
                'gib nur das JSON-Objekt als Antwort aus.')

    def check_ai_cli(self):
        provider = self.ai_provider.currentText()
        try:
            path = resolve_cli_executable(provider, self.ai_cli_command.text())
        except ProviderError as exc:
            text, _status = self.ai_api_error_text(exc.kind, provider, exc.code, exc.detail)
            return QMessageBox.warning(self, self.localized_dialog_title('Hinweis'), text)
        self.ai_info.setText(f'CLI gefunden: {path}')
        self.message('CLI gefunden', f'{provider}-CLI gefunden:\n{path}\n\n'
                     'Falls noch nicht geschehen, die CLI einmal in einem Terminal starten und anmelden.')

    def generate_ai_cli(self):
        sid = self.ai_selected_song_id()
        if sid is None: return self.error('Bitte einen Ziel-Song auswählen oder über „Song-Eintrag anlegen“ zuerst einen Song zum Projekt erstellen.')
        provider = self.ai_provider.currentText()
        command = self.ai_cli_command.text().strip() or CLI_DEFAULT_COMMANDS.get(provider, '')
        model = self.ai_cli_model.text().strip()
        if model and not re.fullmatch(r'[a-zA-Z0-9._:-]+', model): return self.error('Ungültiger Modellname.')
        try:
            prompt = self.ai_cli_prompt(sid)
        except ValueError as exc:
            return self.error(str(exc))
        self.ai_pending = (sid, provider, model or 'CLI', self.ai_brief.toPlainText().strip())
        job = CliGenerationJob(provider, command, model, prompt)
        self.ai_job = job
        job.signals.finished.connect(self.ai_generated)
        job.signals.failed.connect(self.ai_failed)
        self.ai_generate.setEnabled(False)
        self.ai_cli_generate.setEnabled(False)
        self.ai_info.setText('CLI-Anfrage läuft … (kann einige Minuten dauern)')
        self.threadpool.start(job)

    def ai_generated(self, answer):
        self.ai_generate.setEnabled(True)
        self.ai_cli_generate.setEnabled(True)
        self.ai_import_source.setText('Importquelle: keine · KI-Plattform oben auswählen')
        try:
            style, lyrics = extract_prompt(answer)
        except ValueError as exc:
            self.ai_info.setText('KI-Antwort konnte nicht automatisch aufgeteilt werden.')
            return self.error(str(exc))
        self.set_ai_editor_values(style, lyrics)
        self.ai_info.setText('Antwort empfangen. Vor dem Speichern prüfen; keine automatische Überschreibung.')
        self.ai_key.clear()

