    def ai_api_error_text(self, kind, provider, code='', detail=''):
        texts = self.AI_API_ERRORS.get(self.effective_language(), self.AI_API_ERRORS['en'])
        model = self.ai_pending[2] if getattr(self, 'ai_pending', None) else self.ai_model.text().strip()
        text = texts.get(kind, texts['unexpected']).format(provider=provider, code=code or '?', model=model)
        # Detail is only informative where it adds something (e.g. "model not found").
        if detail and kind not in ('timeout', 'truncated', 'empty', 'cli_timeout'):
            text += f'\n\n{texts["detail"]} {detail}'
        return text, texts['status']

    def ai_failed(self, kind, provider='', code='', detail=''):
        self.ai_generate.setEnabled(True)
        self.ai_cli_generate.setEnabled(True)
        self.ai_key.clear()
        LOGGER.error('API-Anfrage fehlgeschlagen: %s %s %s %s', provider, kind, code, detail)
        text, status = self.ai_api_error_text(kind, provider or self.ai_provider.currentText(), code, detail)
        self.ai_info.setText(status)
        QMessageBox.warning(self, self.localized_dialog_title('Hinweis'), text)

    def show_ai_clipboard_notice(self):
        """Non-blocking five-second confirmation; the user can dismiss it earlier."""
        notice = QMessageBox(self)
        notice.setIcon(QMessageBox.Icon.Information)
        notice.setWindowTitle('Hardware-Preset kopiert')
        notice.setText('Die vorbereitete KI-Anforderung inklusive Hardware-Preset wurde in die Zwischenablage kopiert.')
        notice.setInformativeText('Im Browser mit Strg+V einfügen. Dieses Fenster schließt sich nach 5 Sekunden automatisch.')
        notice.setStandardButtons(QMessageBox.StandardButton.Ok)
        notice.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
        QTimer.singleShot(5000, notice.close)
        notice.open()
        self._ai_clipboard_notice = notice

    def open_ai_browser(self):
        import webbrowser
        urls = {'ChatGPT':'https://chatgpt.com/','Gemini':'https://gemini.google.com/','Claude':'https://claude.ai/'}
        sid = self.ai_selected_song_id()
        if sid is None: return self.error('Bitte zuerst einen Song-Eintrag zum ausgewählten Projekt anlegen.')
        prompt_text = self.ai_prompt(sid)
        # Browser workflow: two copy-ready sections instead of API-only JSON.
        prompt_text = prompt_text.replace(
            'Antworte ausschließlich als JSON-Objekt mit den Schlüsseln "style" und "lyrics" (beide Strings). Keine Markdown-Codeblöcke.',
            'Erstelle den Prompt in zwei separaten Copy-Boxen. '
            'Die erste Copy-Box enthält ausschließlich den Style, die zweite ausschließlich die Lyrics. '
            'Beschrifte sie mit STYLE und LYRICS.'
        )
        clipboard = QApplication.clipboard()
        clipboard.setText(prompt_text)
        if clipboard.text() != prompt_text:
            return self.error('Die KI-Anforderung konnte nicht in die Zwischenablage kopiert werden.')
        platform_url = urls.get(self.ai_provider.currentText())
        if not platform_url:
            return self.error('Bitte eine gültige KI-Plattform auswählen.')
        browser_opened = webbrowser.open(platform_url)
        if not browser_opened:
            self.ai_info.setText('KI-Anforderung kopiert; Browser konnte nicht automatisch geöffnet werden.')
        else:
            self.ai_info.setText('KI-Anforderung kopiert. Im Browser mit Strg+V einfügen; Ergebnis anschließend importieren.')
        self.show_ai_clipboard_notice()

    def import_ai_clipboard(self):
        text = QApplication.clipboard().text().strip()
        if not text: return self.error('Die Zwischenablage enthält keinen Text.')
        self.load_ai_import(text, 'Zwischenablage')

    def import_ai_file(self):
        filename, _ = QFileDialog.getOpenFileName(self, 'KI-Prompt importieren', '',
                                                  'Prompt-Dateien (*.txt *.md *.json);;Alle Dateien (*)')
        if not filename: return
        try:
            path = Path(filename)
            if path.stat().st_size > 2 * 1024 * 1024:
                return self.error('Die Importdatei darf maximal 2 MB groß sein.')
            content = path.read_text(encoding='utf-8-sig')
        except (OSError, UnicodeError) as exc:
            return self.error(f'Datei konnte nicht gelesen werden: {exc}')
        self.load_ai_import(content, path.name)

    def import_ai_url(self):
        url, ok = QInputDialog.getText(self, 'Prompt über Weblink importieren',
                                       'Öffentliche URL einer TXT-, MD- oder JSON-Promptdatei:')
        if not ok or not url.strip(): return
        url = url.strip()
        try:
            parsed = urlparse(url)
            if parsed.scheme != 'https' or not parsed.hostname or parsed.username or parsed.password:
                raise ValueError('Nur öffentliche HTTPS-Links ohne Zugangsdaten sind erlaubt.')
            if parsed.port not in (None, 443):
                raise ValueError('Nur der HTTPS-Standardport ist erlaubt.')
            # Restrict URL imports to explicit prompt file URLs, not private chat pages.
            if Path(parsed.path).suffix.lower() not in ('.txt', '.md', '.json'):
                raise ValueError('Bitte einen direkten TXT-, MD- oder JSON-Link verwenden. Chat-Freigabeseiten können nicht zuverlässig automatisch ausgelesen werden.')
            def check_public(host):
                for record in socket.getaddrinfo(host, 443, type=socket.SOCK_STREAM):
                    address = ipaddress.ip_address(record[4][0])
                    if not address.is_global:
                        raise ValueError('Lokale oder private Netzwerkadressen sind nicht erlaubt.')
            check_public(parsed.hostname)
            class RestrictedRedirect(urllib.request.HTTPRedirectHandler):
                def redirect_request(self, request, fp, code, msg, headers, newurl):
                    raise ValueError('Automatische Weiterleitungen sind beim URL-Import deaktiviert.')
            opener = urllib.request.build_opener(RestrictedRedirect)
            request = urllib.request.Request(url, headers={'User-Agent':'MPW/0.5.7', 'Accept':'text/plain, text/markdown, application/json'})
            with opener.open(request, timeout=12) as response:
                length = response.headers.get('Content-Length')
                if length and int(length) > 2 * 1024 * 1024:
                    raise ValueError('Der Prompt ist größer als 2 MB.')
                payload = response.read(2 * 1024 * 1024 + 1)
                if len(payload) > 2 * 1024 * 1024:
                    raise ValueError('Der Prompt ist größer als 2 MB.')
            content = payload.decode('utf-8-sig')
            self.load_ai_import(content, url)
        except (ValueError, OSError, UnicodeError, urllib.error.URLError) as exc:
            self.error(f'Weblink-Import fehlgeschlagen: {exc}')

    def load_ai_import(self, content, source):
        if self.ai_selected_song_id() is None:
            return self.error('Bitte zuerst einen Song-Eintrag zum ausgewählten Projekt anlegen.')
        try:
            style, lyrics = extract_prompt(content)
        except ValueError as exc:
            return self.error(str(exc) + '\nBitte eine Antwort mit Style- und Lyrics-Abschnitt importieren.')
        self.set_ai_editor_values(style, lyrics)
        self.ai_import_source.setText(f'Importquelle: {source} · Plattform: {self.ai_provider.currentText()}')
        self.check_ai_import()

    def check_ai_import(self):
        style, lyrics = self.ai_editor_values()
        if not style or not lyrics:
            return self.error('Style und Lyrics müssen beide ausgefüllt sein.')
        self.ai_info.setText(f'Import geprüft: Style {len(style)}/1000 · Lyrics {len(lyrics)}/5000 Zeichen.')
        if len(style) > 1000 or len(lyrics) > 5000:
            return self.error('Suno-Zeichenlimit überschritten. Bitte vor dem Speichern kürzen.')
        self.ai_save.setEnabled(True)

    def save_ai_version(self):
        sid = self.ai_selected_song_id()
        if sid is None: return self.error('Bitte zuerst einen Song-Eintrag zum ausgewählten Projekt anlegen.')
        style, lyrics = self.ai_editor_values()
        if not style or not lyrics: return self.error('Style und Lyrics dürfen nicht leer sein.')
        if len(style)>1000 or len(lyrics)>5000:
            return self.error(f'Zeichenlimit überschritten: Style {len(style)}/1000, Lyrics {len(lyrics)}/5000.')
        provider = self.ai_provider.currentText(); model = 'Import (manuell)' if self.ai_import_source.text() != 'Importquelle: keine · KI-Plattform oben auswählen' else self.ai_model.text().strip()
        with self.con:
            cursor = self.con.execute('INSERT INTO prompt_versions(song_id,provider,model,style,lyrics,brief) VALUES(?,?,?,?,?,?)',
                                      (sid,provider,model,style,lyrics,self.ai_brief.toPlainText().strip()))
            version_id = cursor.lastrowid
        self.refresh_ai_versions()
        try:
            prompt_path = self.save_ai_prompt_text_file(sid, version_id, style, lyrics)
        except (OSError, ValueError) as exc:
            self.ai_info.setText('Prompt-Version in der Datenbank gespeichert; TXT-Archivierung fehlgeschlagen.')
            return self.error('Prompt-Version wurde in der Datenbank gespeichert, '
                              'aber die Textdatei konnte nicht erstellt werden.\n'
                              f'Grund: {exc}\nDie gespeicherte Version bleibt erhalten.')
        self.ai_info.setText(f'Version gespeichert und als Textdatei archiviert: {prompt_path.name}')
        self.message('Version und Textdatei gespeichert',
                     f'Prompt-Version gespeichert.\nTextdatei: {prompt_path}\n'
                     'Der aktive Song-Prompt bleibt unverändert.')

    def refresh_ai_versions(self, *args):
        self.ai_versions.clear()
        sid = self.ai_selected_song_id()
        rows = [] if sid is None else self.con.execute(
            'SELECT id,provider,model,created_at FROM prompt_versions WHERE song_id=? ORDER BY id DESC', (sid,)
        ).fetchall()
        old_left = self.compare_left.currentData()
        old_right = self.compare_right.currentData()
        for cb in (self.compare_left, self.compare_right):
            cb.blockSignals(True)
            cb.clear()
            cb.addItem('Aktiver Song-Prompt', None)
            for vid, provider, model, created in rows:
                cb.addItem(f'#{vid} · {provider} · {model} · {created}', vid)
            cb.blockSignals(False)
        for vid,provider,model,created in rows:
            self.ai_versions.addItem(f'#{vid} · {provider} · {model} · {created}')
            self.ai_versions.item(self.ai_versions.count() - 1).setData(Qt.ItemDataRole.UserRole, vid)
        self.ai_load_saved.setEnabled(bool(rows))
        if rows:
            self.ai_versions.setCurrentRow(0)
        li = self.compare_left.findData(old_left)
        ri = self.compare_right.findData(old_right)
        self.compare_left.setCurrentIndex(max(li, 0))
        self.compare_right.setCurrentIndex(ri if ri >= 0 else (1 if rows else 0))
        self.ai_diff.clear()

