    EXPLORER_STATUS_HF9 = {
        'de': ('Keine Datei ausgewählt.', 'Ordner bereit. Datei oder Unterordner auswählen.', 'Ordner nicht vorhanden oder Laufwerk nicht erreichbar.', 'Dateitypfilter angewendet. Ordner bleiben sichtbar.', 'Pfad in die Zwischenablage kopiert: {path}', 'Ordner', 'Datei', 'Geändert', 'Nicht verfügbar'),
        'en': ('No file selected.', 'Folder ready. Select a file or subfolder.', 'Folder not found or drive unavailable.', 'File type filter applied. Folders remain visible.', 'Path copied to clipboard: {path}', 'Folder', 'File', 'Modified', 'Unavailable'),
        'fr': ('Aucun fichier sélectionné.', 'Dossier prêt. Sélectionnez un fichier ou un sous-dossier.', 'Dossier introuvable ou lecteur indisponible.', 'Filtre de fichiers appliqué. Les dossiers restent visibles.', 'Chemin copié dans le presse-papiers : {path}', 'Dossier', 'Fichier', 'Modifié', 'Indisponible'),
        'es': ('Ningún archivo seleccionado.', 'Carpeta lista. Seleccione un archivo o subcarpeta.', 'Carpeta no encontrada o unidad no disponible.', 'Filtro aplicado. Las carpetas siguen visibles.', 'Ruta copiada al portapapeles: {path}', 'Carpeta', 'Archivo', 'Modificado', 'No disponible'),
        'it': ('Nessun file selezionato.', 'Cartella pronta. Seleziona un file o una sottocartella.', 'Cartella non trovata o unità non disponibile.', 'Filtro applicato. Le cartelle rimangono visibili.', 'Percorso copiato negli appunti: {path}', 'Cartella', 'File', 'Modificato', 'Non disponibile'),
    }

    def explorer_status_hf9(self, index, **kwargs):
        return self.EXPLORER_STATUS_HF9[self.effective_language()][index].format(**kwargs)

    def refresh_explorer_status_hf9(self):
        if not hasattr(self, 'explorer_details'):
            return
        current = self.explorer_tree.currentIndex()
        if current.isValid():
            self.show_explorer_selection(current, None)
        else:
            root = Path(self.explorer_path.text())
            self.explorer_details.setText(self.explorer_status_hf9(1 if root.is_dir() else 2))

    def apply_explorer_type_filter(self, _choice=None):
        """Filter file names without hiding directories or changing files."""
        patterns = [
            [],
            ['*.wav', '*.mp3', '*.flac', '*.ogg', '*.m4a', '*.aiff', '*.aif', '*.wma'],
            ['*.png', '*.jpg', '*.jpeg', '*.webp', '*.tif', '*.tiff', '*.bmp', '*.gif'],
            ['*.mp4', '*.mov', '*.mkv', '*.avi', '*.webm', '*.wmv'],
            ['*.pdf', '*.txt', '*.docx', '*.doc', '*.csv', '*.md', '*.rtf'],
        ]
        index = self.explorer_type_filter.currentIndex()
        self.explorer_model.setNameFilters(patterns[index] if 0 <= index < len(patterns) else [])
        self.explorer_details.setText(self.explorer_status_hf9(3))

    def copy_explorer_selection_path(self):
        path = self.explorer_selected_path()
        if path is None:
            self.message('Medien Explorer', 'Bitte zuerst eine Datei oder einen Ordner auswählen.')
            return
        QApplication.clipboard().setText(str(path))
        self.explorer_details.setText(self.explorer_status_hf9(4, path=path))

    def set_explorer_root(self, folder):
        folder = Path(folder).expanduser()
        if not folder.is_dir():
            self.explorer_path.setText(str(folder))
            self.explorer_details.setText(self.explorer_status_hf9(2))
            self.explorer_tree.setRootIndex(self.explorer_model.setRootPath(''))
            self.explorer_tree.setEnabled(False)
            return
        self.explorer_tree.setEnabled(True)
        root_index = self.explorer_model.setRootPath(str(folder.resolve()))
        self.explorer_tree.setRootIndex(root_index)
        self.explorer_path.setText(str(folder.resolve()))
        self.explorer_details.setText(self.explorer_status_hf9(1))

    def change_explorer_root(self, choice):
        if choice == 0:
            self.set_explorer_root(self.band_root_directory())
        elif choice == 1:
            self.set_explorer_root(ROOT / 'media')
        elif choice == 2:
            if self.explorer_custom_root is not None:
                self.set_explorer_root(self.explorer_custom_root)
            else:
                self.choose_explorer_root()

    def choose_explorer_root(self):
        folder = QFileDialog.getExistingDirectory(
            self, 'Ordner für Medien Explorer auswählen',
            str(self.band_root_directory() if self.band_root_directory().is_dir() else Path.home()))
        if not folder:
            return
        self.explorer_custom_root = Path(folder)
        self.explorer_root_choice.blockSignals(True)
        self.explorer_root_choice.setCurrentIndex(2)
        self.explorer_root_choice.blockSignals(False)
        self.set_explorer_root(folder)

    def refresh_media_explorer(self):
        self.change_explorer_root(self.explorer_root_choice.currentIndex())

    def explorer_selected_path(self):
        index = self.explorer_tree.currentIndex()
        return Path(self.explorer_model.filePath(index)) if index.isValid() else None

    def show_explorer_selection(self, current, _previous):
        if not current.isValid():
            self.explorer_details.setText(self.explorer_status_hf9(0))
            return
        path = Path(self.explorer_model.filePath(current))
        try:
            stat = path.stat()
            kind = self.explorer_status_hf9(5 if path.is_dir() else 6)
            size = '' if path.is_dir() else f' · {stat.st_size:,} Bytes'
            modified = datetime.fromtimestamp(stat.st_mtime).strftime('%d.%m.%Y %H:%M')
            self.explorer_details.setText(f'{kind}{size} · {self.explorer_status_hf9(7)}: {modified} · {path}')
        except OSError as exc:
            self.explorer_details.setText(f'{self.explorer_status_hf9(8)}: {exc}')

    def open_explorer_item(self, index):
        if not index.isValid():
            return
        path = Path(self.explorer_model.filePath(index))
        if path.is_dir():
            self.explorer_tree.setExpanded(index, not self.explorer_tree.isExpanded(index))
        elif path.is_file():
            if not QDesktopServices.openUrl(QUrl.fromLocalFile(str(path))):
                self.error(f'Datei konnte nicht geöffnet werden: {path}')
        else:
            self.error(f'Datei oder Ordner nicht mehr vorhanden: {path}')

    def open_explorer_selection(self):
        index = self.explorer_tree.currentIndex()
        if index.isValid():
            self.open_explorer_item(index)
        else:
            self.message('Medien Explorer', 'Bitte zuerst eine Datei oder einen Ordner auswählen.')

    def show_explorer_in_windows(self):
        path = self.explorer_selected_path()
        if path is None:
            self.message('Medien Explorer', 'Bitte zuerst eine Datei oder einen Ordner auswählen.')
            return
        if not path.exists():
            self.error(f'Pfad nicht mehr vorhanden: {path}')
            return
        if sys.platform == 'win32' and path.is_file():
            try:
                subprocess.Popen(['explorer.exe', '/select,', str(path)])
            except OSError as exc:
                self.error(f'Windows-Explorer konnte nicht geöffnet werden: {exc}')
        elif not QDesktopServices.openUrl(QUrl.fromLocalFile(str(path if path.is_dir() else path.parent))):
            self.error(f'Ordner konnte nicht geöffnet werden: {path}')

