    def automatic_backup_failure_text(self, error):
        title, body = self.AUTOMATIC_BACKUP_FAILURE_TRANSLATIONS.get(
            self.effective_language(), self.AUTOMATIC_BACKUP_FAILURE_TRANSLATIONS['en'])
        return title, body.format(error=str(error))

    def run_scheduled_backup(self):
        """At startup, create a backup if the configured interval has elapsed.

        Automatic retention never deletes manual or pre-operation safety backups.
        """
        settings = self.backup_settings()
        interval = settings.get('automatic_interval_days', 0)
        if not isinstance(interval, int) or interval <= 0:
            return
        folder = self.backup_directory()
        try:
            if not folder.is_dir():
                raise OSError(f'Backup-Laufwerk nicht erreichbar: {folder}')
            backups = list(folder.glob('MPW_auto_*.zip'))
            newest = max((p.stat().st_mtime for p in backups if p.is_file()), default=None)
            if newest is not None and (datetime.now().timestamp() - newest) < interval * 86400:
                return
            destination = self.automatic_backup_path('MPW_auto')
            create_backup(self.con, ROOT, destination)
            # Only delete backups made by the automatic scheduler. Never delete
            # a file that is currently being written or a manual safety backup.
            keep = settings.get('automatic_keep_count', 10)
            if not isinstance(keep, int) or keep < 1:
                keep = 10
            backups = sorted(
                (p for p in folder.glob('MPW_auto_*.zip') if p.is_file()),
                key=lambda p: p.stat().st_mtime, reverse=True)
            for old in backups[keep:]:
                old.unlink()
            self.refresh_backup_history()
        except (OSError, sqlite3.Error, zipfile.BadZipFile) as exc:
            # Backup failures must never prevent the application from starting.
            title, body = self.automatic_backup_failure_text(exc)
            QMessageBox.warning(self, title, body)

    def choose_backup_directory(self):
        selected = QFileDialog.getExistingDirectory(
            self, 'Backup-Laufwerk oder Ordner wählen', str(self.backup_directory()))
        if not selected:
            return
        folder = Path(selected)
        try:
            folder.mkdir(parents=True, exist_ok=True)
            # Verify that the target is writable before saving it as the default.
            with tempfile.NamedTemporaryFile(prefix='mpw_backup_test_', dir=folder, delete=True):
                pass
            self.save_backup_settings(backup_directory=str(folder))
        except OSError as exc:
            return self.error(f'Backup-Ziel kann nicht verwendet werden: {exc}')
        self.backup_location.setText(str(folder))
        self.refresh_backup_history()
        self.message('Backup-Ziel gespeichert', f'Zukünftige Backups werden standardmäßig hier gespeichert:\n{folder}')

    def export_backup_inventory_csv(self):
        """Export all or only currently visible archive metadata to an Excel-compatible CSV."""
        folder = self.backup_directory()
        if not folder.is_dir():
            return QMessageBox.warning(self, 'Backup-Inventar',
                                       f'Das Backup-Ziel ist nicht erreichbar:\n{folder}')
        choice = QMessageBox(self)
        choice.setWindowTitle('Backup-Inventar exportieren')
        choice.setText('Welche Sicherungen sollen in der CSV-Datei enthalten sein?')
        visible_button = choice.addButton('Nur sichtbare Backups', QMessageBox.AcceptRole)
        all_button = choice.addButton('Alle Backups', QMessageBox.AcceptRole)
        choice.addButton('Abbrechen', QMessageBox.RejectRole)
        choice.exec()
        selected = choice.clickedButton()
        if selected not in (visible_button, all_button):
            return
        if selected is visible_button:
            archives = []
            for index in range(self.backup_history.count()):
                item = self.backup_history.item(index)
                path = item.data(Qt.ItemDataRole.UserRole)
                if path and not item.isHidden():
                    archives.append(Path(path))
            selection_name = 'Sichtbare Backups'
        else:
            try:
                archives = sorted(folder.glob('*.zip'), key=lambda path: path.name.casefold())
            except OSError as exc:
                return self.error(exc)
            selection_name = 'Alle Backups'
        if not archives:
            return QMessageBox.information(self, 'Backup-Inventar',
                                           'Keine Backups für den gewählten Export vorhanden.')
        default = str(Path.home() / f'MPW_Backup_Inventar_{datetime.now():%Y%m%d_%H%M%S}.csv')
        filename, _ = QFileDialog.getSaveFileName(
            self, 'Backup-Inventar exportieren', default, 'CSV-Dateien (*.csv)')
        if not filename:
            return
        destination = Path(filename)
        if destination.suffix.lower() != '.csv':
            destination = destination.with_suffix('.csv')
        try:
            with destination.open('w', encoding='utf-8-sig', newline='') as output:
                writer = csv.writer(output, delimiter=';')
                writer.writerow(['Dateiname', 'Größe (MiB)', 'Geändert am', 'Typ'])
                for archive in archives:
                    try:
                        stat = archive.stat()
                        kind = ('Automatisch' if archive.name.startswith('MPW_auto_')
                                else 'Manuell/Sicherheit/Andere')
                        writer.writerow([archive.name, f'{stat.st_size / 1024**2:.2f}',
                                         datetime.fromtimestamp(stat.st_mtime).strftime('%Y-%m-%d %H:%M:%S'),
                                         kind])
                    except OSError:
                        writer.writerow([archive.name, 'Nicht lesbar', '', 'Unbekannt'])
            self.message('Backup-Inventar exportiert',
                         f'{selection_name}: {len(archives)} ZIP-Dateien erfasst:\n{destination}\n\n'
                         'Nur Dateimetadaten; keine Integritätsprüfung.')
        except OSError as exc:
            self.error(exc)

    def test_backup_destination(self):
        """Check selected backup location without creating or changing any backup."""
        folder = self.backup_directory()
        if not folder.is_dir():
            return QMessageBox.warning(self, self.localized_dialog_title('Backup-Ziel nicht erreichbar'),
                f'Der eingestellte Backup-Ordner ist nicht verfügbar:\n{folder}\n\n'
                'Bitte das Laufwerk anschließen oder einen anderen Ordner auswählen.')
        try:
            # Check real write access, then remove only our own temporary test file.
            with tempfile.NamedTemporaryFile(prefix='mpw_zieltest_', suffix='.tmp',
                                             dir=folder, delete=True) as test:
                test.write(b'MPW backup target write test\n')
                test.flush()
                os.fsync(test.fileno())
            available, required = check_backup_free_space(ROOT, folder / 'MPW_test.zip')
        except (OSError, ValueError) as exc:
            return QMessageBox.warning(self, 'Backup-Zielprüfung fehlgeschlagen',
                                       f'Backup-Ziel: {folder}\n\n{exc}')
        QMessageBox.information(self, 'Backup-Ziel einsatzbereit',
            f'Backup-Ziel: {folder}\n'
            'Schreibtest erfolgreich; temporäre Testdatei entfernt.\n'
            f'Freier Speicher: {available / 1024**3:.2f} GiB\n'
            f'Geschätzter Mindestbedarf: {required / 1024**3:.2f} GiB\n\n'
            'Es wurde kein Backup erstellt und keine Datenbank verändert.')

    def automatic_backup_path(self, prefix):
        folder = self.backup_directory()
        if not folder.is_dir():
            raise OSError(f'Das konfigurierte Backup-Laufwerk ist nicht verfügbar: {folder}')
        return folder / f'{prefix}_{datetime.now():%Y%m%d_%H%M%S_%f}.zip'

