    def translate_backup_status_hf12(self, message):
        # Replace longest phrases first; timestamps, filenames and paths stay untouched.
        translations = self.BACKUP_STATUS_HF12.get(self.effective_language(), {})
        for source in sorted(translations, key=len, reverse=True):
            message = message.replace(source, translations[source])
        return message

    def refresh_backup_language_hf12(self):
        if not hasattr(self, 'backup_intro_hf12'):
            return
        words = self.BACKUP_I18N_HF12[self.effective_language()]
        self.backup_intro_hf12.setText(words[9])
        self.backup_note_hf12.setText(words[10])
        self.backup_interval_label_hf12.setText(words[0])
        self.backup_retention_label_hf12.setText(words[1])
        for combo, indices in ((self.auto_interval, range(2, 8)),):
            combo.blockSignals(True)
            try:
                for i, text_index in enumerate(indices):
                    combo.setItemText(i, words[text_index])
            finally:
                combo.blockSignals(False)
        self.auto_retention.blockSignals(True)
        try:
            for i in range(self.auto_retention.count()):
                self.auto_retention.setItemText(i, words[8].format(n=self.auto_retention.itemData(i)))
        finally:
            self.auto_retention.blockSignals(False)
        self.update_backup_status()

    def update_backup_statistics(self):
        """Summarize persistent audit entries and flag the latest failed backup."""
        if not hasattr(self, 'backup_statistics'):
            return
        folder = self.backup_directory()
        log_path = folder / 'MPW_Backup_Pruefprotokoll.jsonl'
        if not folder.is_dir():
            self.backup_statistics.setText(self.translate_backup_status_hf12('⚠ Backup-Statistik: Sicherungslaufwerk nicht erreichbar.'))
            return
        if not log_path.is_file():
            self.backup_statistics.setText(self.translate_backup_status_hf12('Backup-Statistik: Noch keine protokollierten Sicherungen.'))
            return
        try:
            ok_count = error_count = 0
            latest = None
            with log_path.open('r', encoding='utf-8') as handle:
                for line in handle:
                    if not line.strip():
                        continue
                    try:
                        entry = json.loads(line)
                    except (ValueError, TypeError):
                        continue
                    status = entry.get('status')
                    if status == 'OK':
                        ok_count += 1
                    elif status == 'FEHLER':
                        error_count += 1
                    else:
                        continue
                    latest = entry
            if latest is None:
                self.backup_statistics.setText(self.translate_backup_status_hf12('Backup-Statistik: Keine auswertbaren Prüfeinträge.'))
                return
            summary = f'Backup-Statistik: {ok_count} erfolgreich · {error_count} fehlgeschlagen'
            if latest.get('status') == 'FEHLER':
                summary += ('\n⚠ LETZTES BACKUP FEHLGESCHLAGEN: '
                            f"{latest.get('timestamp', '?')} · {latest.get('file', '?')}"
                            f"\nGrund: {latest.get('details', 'Unbekannt')}")
                self.backup_statistics.setStyleSheet('color: #b45309; font-weight: bold;')
            else:
                summary += (f"\nLetzte erfolgreiche Prüfung: {latest.get('timestamp', '?')} · "
                            f"{latest.get('file', '?')}")
                self.backup_statistics.setStyleSheet('')
            self.backup_statistics.setText(self.translate_backup_status_hf12(summary))
        except (OSError, UnicodeError) as exc:
            self.backup_statistics.setText(self.translate_backup_status_hf12(f'⚠ Backup-Statistik nicht lesbar: {exc}'))

    def update_backup_status(self):
        """Show the actual last completed automatic backup and next startup due date."""
        self.update_backup_statistics()
        if not hasattr(self, 'backup_status'):
            return
        folder = self.backup_directory()
        if not folder.is_dir():
            self.backup_status.setText(
                f'⚠ Backup-Laufwerk nicht erreichbar: {folder}\n'
                'Automatische Sicherungen können derzeit nicht erstellt werden.')
            self.backup_status.setText(self.translate_backup_status_hf12(self.backup_status.text()))
            return
        try:
            backups = [p for p in folder.glob('MPW_auto_*.zip') if p.is_file()]
            newest = max(backups, key=lambda p: p.stat().st_mtime) if backups else None
            last = datetime.fromtimestamp(newest.stat().st_mtime) if newest else None
            interval = self.backup_settings().get('automatic_interval_days', 0)
            if not isinstance(interval, int) or interval <= 0:
                next_text = 'Deaktiviert'
            elif last is None:
                next_text = 'Beim nächsten Programmstart fällig'
            else:
                from datetime import timedelta
                due = last + timedelta(days=interval)
                next_text = f'{due:%d.%m.%Y %H:%M} (beim nächsten Start nach diesem Zeitpunkt)'
            last_text = f'{last:%d.%m.%Y %H:%M} – {newest.name}' if last else 'Keine automatische Sicherung gefunden'
            self.backup_status.setText(self.translate_backup_status_hf12(f'Letzte automatische Sicherung: {last_text}\nNächste Sicherung: {next_text}'))
        except OSError as exc:
            self.backup_status.setText(self.translate_backup_status_hf12(f'⚠ Backup-Status konnte nicht gelesen werden: {exc}'))

