    def album_summary_text_hf11(self, count, duration, release):
        words = self.RECORD_I18N_HF11.get(self.effective_language(), self.RECORD_I18N_HF11['de'])
        return f'Tracks: {count}  ·  {words[3]}: {duration}  ·  {words[4]}: {release}'

    def album_duration_partial_hf11(self, known, count):
        words = self.RECORD_I18N_HF11.get(self.effective_language(), self.RECORD_I18N_HF11['de'])
        return ' (' + words[5].format(known=known, count=count) + ')'

    def album_duration_unknown_hf11(self):
        return self.RECORD_I18N_HF11.get(self.effective_language(), self.RECORD_I18N_HF11['de'])[6]

    def refresh_record_language_hf11(self):
        words = self.RECORD_I18N_HF11.get(self.effective_language(), self.RECORD_I18N_HF11['de'])
        for index, button in enumerate(getattr(self, 'album_track_action_buttons_hf11', ())):
            button.setText(words[index])
        if hasattr(self, 'album_summary'):
            # Recompute from database/audio on next selection; avoid changing stored data.
            self.load_album()

