        cover = QPushButton('Cover auswählen / ändern'); cover.clicked.connect(self.choose_album_cover); rl.addWidget(cover)
        rl.addWidget(QLabel('Songs hinzufügen (ein Song kann auf mehreren Platten erscheinen)'))
        line = QHBoxLayout()
        self.album_song = QComboBox(); line.addWidget(self.album_song, 1)
