        rl.addLayout(line)
        self.album_show_all_songs = QCheckBox('Auch Songs anderer Interpreten anzeigen (Sampler / Gastbeiträge)')
        self.album_show_all_songs.toggled.connect(self.refresh_album_song_choices)
        rl.addWidget(self.album_show_all_songs)
