    def build_album_details(self):
        # Erweiterte Metadaten und Exporte getrennt von der Track-Zusammenstellung.
        page = BackgroundPage()
        layout = QVBoxLayout(page)
        hint = QLabel('Album-Details · Platte zunächst im Reiter „Plattensammlung“ auswählen.')
        hint.setWordWrap(True)
        layout.addWidget(hint)
        metadata = QGroupBox('Album-Metadaten')
        mf = QFormLayout(metadata)
        self.album_release_date = QDateEdit()
        self.album_release_date.setCalendarPopup(True)
        self.album_release_date.setDisplayFormat('dd.MM.yyyy')
        self.album_release_date.setMinimumDate(QDate(1900, 1, 1))
        self.album_release_date.setSpecialValueText('Nicht festgelegt')
        self.album_release_date.setDate(self.album_release_date.minimumDate())
