    def archive_word_hf13(self, key):
        return self.ARCHIVE_I18N_HF13.get(self.effective_language(), self.ARCHIVE_I18N_HF13['en'])[key]

    def refresh_archive_language_hf13(self):
        if not hasattr(self, 'archive_intro_hf13'):
            return
        bindings = {
            'intro': 'archive_intro_hf13', 'history': 'archive_history_group_hf13',
            'type': 'archive_type_label_hf13', 'age': 'archive_age_label_hf13',
            'sort': 'archive_sort_label_hf13', 'tip': 'archive_tip_hf13',
            'reset': 'archive_reset_hf13', 'refresh': 'archive_refresh_hf13',
            'folder': 'archive_folder_hf13', 'reveal': 'archive_reveal_hf13',
            'copy': 'archive_copy_hf13', 'verify': 'archive_verify_hf13',
            'inspect': 'archive_inspect_hf13', 'compare': 'archive_compare_hf13',
            'manifest': 'archive_manifest_hf13', 'export': 'archive_export_hf13',
            'verify_all': 'archive_verify_all_hf13',
            'restore_selected': 'archive_restore_selected_hf13',
            'inventory': 'archive_inventory_hf13', 'recovery': 'archive_recovery_group_hf13',
            'restore': 'archive_restore_hf13', 'log': 'archive_log_hf13',
            'danger': 'archive_danger_group_hf13',
            'danger_note': 'archive_danger_note_hf13', 'clear': 'archive_clear_hf13',
        }
        for key, attribute in bindings.items():
            widget = getattr(self, attribute)
            value = self.archive_word_hf13(key)
            if isinstance(widget, QGroupBox):
                widget.setTitle(value)
            else:
                widget.setText(value)
        self.archive_toggle_hf13.setText(self.archive_word_hf13(
            'toggle_hide' if self.archive_toggle_hf13.isChecked() else 'toggle_show'))
        self.backup_history_filter.setPlaceholderText(self.archive_word_hf13('placeholder'))
        if self.backup_scan_status.text() in (
                row['scan_idle'] for row in self.ARCHIVE_I18N_HF13.values()):
            self.backup_scan_status.setText(self.archive_word_hf13('scan_idle'))
        # Keep filter and sort indices unchanged: archive logic uses currentIndex().
        for combo, keys in ((self.backup_type_filter, ('all', 'auto', 'other')),
                            (self.backup_age_filter, ('all_age', '7', '30', '90')),
                            (self.backup_history_sort, ('new', 'old', 'az', 'za', 'large', 'small'))):
            combo.blockSignals(True)
            try:
                for i, key in enumerate(keys):
                    combo.setItemText(i, self.ARCHIVE_COMBOS_HF13[self.effective_language()][key])
            finally:
                combo.blockSignals(False)

