    LANGUAGE_TEXTS = {'en': ['Language / Language', 'User interface language:', 'Automatic (operating system language)', 'German', 'English', 'French', 'Spanish', 'Italian', 'Language changed immediately. Further UI translations will follow in the next development stage.'], 'fr': ['Langue / Language', 'Langue de l’interface :', 'Automatique (langue du système)', 'Allemand', 'Anglais', 'Français', 'Espagnol', 'Italien', 'La langue change immédiatement. D’autres traductions suivront.'], 'es': ['Idioma / Language', 'Idioma de la interfaz:', 'Automático (idioma del sistema)', 'Alemán', 'Inglés', 'Francés', 'Español', 'Italiano', 'El idioma cambia inmediatamente. Seguirán más traducciones.'], 'it': ['Lingua / Language', 'Lingua dell’interfaccia:', 'Automatico (lingua del sistema)', 'Tedesco', 'Inglese', 'Francese', 'Spagnolo', 'Italiano', 'La lingua cambia immediatamente. Seguiranno altre traduzioni.'], 'de': ['Sprache / Language', 'Sprache der Benutzeroberfläche:', 'Automatisch (Betriebssystemsprache)', 'Deutsch', 'Englisch', 'Französisch', 'Spanisch', 'Italienisch', 'Die Sprache wird sofort umgestellt. Weitere Oberflächenübersetzungen folgen in der nächsten Entwicklungsstufe.']}

    def effective_language(self):
        selected = self.app_configuration().get('ui_language', 'auto')
        if selected in self.LANGUAGE_NAMES:
            return selected
        system = QLocale.system().name().split('_')[0].lower()
        return system if system in self.LANGUAGE_NAMES else 'en'

    def change_ui_language(self, _index=None):
        selected = self.language_choice.currentData()
        if selected not in ('auto', *self.LANGUAGE_NAMES):
            return
        self.save_app_configuration(ui_language=selected)
        self.refresh_language_controls()

