    def tab_key(self, index):
        """Language-independent tab identity, stored on the page widget."""
        if index < 0 or index >= self.tabs.count():
            return ''
        page = self.tabs.widget(index)
        key = page.property('mpw_tab_key')
        if key is None:
            key = self.tabs.tabText(index)
            page.setProperty('mpw_tab_key', key)
        return key

    def tab_index(self, key):
        return next((i for i in range(self.tabs.count()) if self.tab_key(i) == key), -1)

