    def deletion_warning_text(self, key, **values):
        lang = self.effective_language()
        return self.DELETE_WARNING_I18N.get(lang, self.DELETE_WARNING_I18N['de'])[key].format(**values)

    def project_band_dialog_text(self, key, **values):
        language = self.effective_language()
        return self.PROJECT_BAND_DIALOG_I18N.get(language, self.PROJECT_BAND_DIALOG_I18N['de'])[key].format(**values)

    def translated_project_context_status(self, original):
        return self.PROJECT_CONTEXT_STATUS_TRANSLATIONS.get(self.effective_language(), {}).get(original, original)

    def translated_context_label(self, original):
        """Translate presentation only; menu action identity remains unchanged."""
        return self.UI_CONTEXT_TRANSLATIONS.get(self.effective_language(), {}).get(original, original)

