    def refresh_alpha18_language(self):
        """Translate presentation-only widgets; preserve underlying values and selection."""
        lang = self.effective_language()
        catalog = self.ALPHA18_TEXTS.get(lang, {})
        known = self.ALPHA18_TEXTS["en"]
        if not hasattr(self, "tabs"):
            return
        for widget in self.tabs.findChildren(QLabel) + self.tabs.findChildren(QPushButton) + self.tabs.findChildren(QCheckBox):
            original = widget.property("mpw_alpha18_original")
            if original is None and widget.text() in known:
                original = widget.text()
                widget.setProperty("mpw_alpha18_original", original)
            if original in known:
                widget.setText(catalog.get(original, original))
        for widget in self.tabs.findChildren(QLineEdit) + self.tabs.findChildren(QTextEdit):
            original = widget.property("mpw_alpha18_placeholder")
            if original is None and widget.placeholderText() in known:
                original = widget.placeholderText()
                widget.setProperty("mpw_alpha18_placeholder", original)
            if original in known:
                widget.setPlaceholderText(catalog.get(original, original))
        for widget in self.tabs.findChildren(QWidget):
            original = widget.property("mpw_alpha18_tooltip")
            if original is None and widget.toolTip() in known:
                original = widget.toolTip()
                widget.setProperty("mpw_alpha18_tooltip", original)
            if original in known:
                widget.setToolTip(catalog.get(original, original))
        # These controls are audited by index or currentData, not currentText.
        for name in ("explorer_type_filter", "startup_tab_choice", "error_period"):
            combo = getattr(self, name, None)
            if combo is None:
                continue
            combo.blockSignals(True)
            try:
                for index in range(combo.count()):
                    original = combo.itemData(index, Qt.ItemDataRole.UserRole + 2)
                    if original is None and combo.itemText(index) in known:
                        original = combo.itemText(index)
                        combo.setItemData(index, original, Qt.ItemDataRole.UserRole + 2)
                    if original in known:
                        combo.setItemText(index, catalog.get(original, original))
            finally:
                combo.blockSignals(False)
        date = getattr(self, "album_release_date", None)
        if date is not None:
            date.setSpecialValueText(catalog.get("Nicht festgelegt", "Nicht festgelegt"))

    def refresh_ai_language(self):
        """Translate UI-only strings, never database values or user-authored content."""
        language = self.effective_language()
        translations = self.AI17_TRANSLATIONS.get(language, {})
        page = self.ai_band.parentWidget()
        if page is None:
            return
        # Form labels, buttons and initial informational labels are included.
        for widget in (page.findChildren(QLabel) + page.findChildren(QPushButton) + page.findChildren(QLineEdit) + page.findChildren(QTextEdit)):
            if isinstance(widget, (QLabel, QPushButton)):
                original = widget.property('mpw_ai17_text')
                if original is None and widget.text() in self.AI17_TRANSLATIONS['en']:
                    original = widget.text()
                    widget.setProperty('mpw_ai17_text', original)
                if original in self.AI17_TRANSLATIONS['en']:
                    widget.setText(translations.get(original, original))
            if isinstance(widget, (QLineEdit, QTextEdit)):
                original = widget.property('mpw_ai17_placeholder')
                if original is None and widget.placeholderText() in self.AI17_TRANSLATIONS['en']:
                    original = widget.placeholderText()
                    widget.setProperty('mpw_ai17_placeholder', original)
                if original in self.AI17_TRANSLATIONS['en']:
                    widget.setPlaceholderText(translations.get(original, original))
        # This option is a sentinel: currentData() remains None.
        if self.ai_hardware_preset.count() and self.ai_hardware_preset.itemData(0) is None:
            self.ai_hardware_preset.setItemText(0, translations.get('Bandprofil-Hardware verwenden', 'Bandprofil-Hardware verwenden'))
        self.update_ai_limits()

