    def refresh_project_display_hf5(self):
        if not hasattr(self, 'project_filter_status'):
            return
        words = self.PROJECT_DISPLAY_HF5[self.effective_language()]
        self.project_search.setPlaceholderText(words[0])
        for combo, labels in ((self.project_filter_band, (words[1],)),
                              (self.project_sort, words[3]),
                              (self.project_filter_status, (words[2], *words[4]))):
            combo.blockSignals(True)
            try:
                for index, label in enumerate(labels):
                    if index < combo.count():
                        combo.setItemText(index, label)
            finally:
                combo.blockSignals(False)
        self.refresh_project_index()

    def refresh_language_controls(self):
        language = self.effective_language()
        words = self.LANGUAGE_TEXTS[language]
        self.language_group.setTitle(words[0])
        self.language_label.setText(words[1])
        self.language_choice.blockSignals(True)
        try:
            for index, value in enumerate(('auto', 'de', 'en', 'fr', 'es', 'it')):
                self.language_choice.setItemText(index, words[index + 2])
        finally:
            self.language_choice.blockSignals(False)
        self.language_hint.setText(words[8])
        # Stable original-text keys: never translate user-generated or dynamic content.
        control_translations = self.UI_CONTROL_TRANSLATIONS.get(language, {})
        if hasattr(self, 'tabs'):
            for control in self.tabs.findChildren(QPushButton):
                original = control.property('mpw_original_button_text')
                if original is None:
                    original = control.text()
                    if original in self.UI_CONTROL_TRANSLATIONS['en']:
                        control.setProperty('mpw_original_button_text', original)
                if original in self.UI_CONTROL_TRANSLATIONS['en']:
                    control.setText(control_translations.get(original, original))
        # Translate only whitelisted static labels and checkboxes. Never touch
        # user content, song titles, file names, or dynamic status text.
        fields = self.UI_FIELD_TRANSLATIONS.get(language, {})
        if hasattr(self, 'tabs'):
            for widget in self.tabs.findChildren(QLabel) + self.tabs.findChildren(QCheckBox):
                original = widget.property('mpw_original_field_text')
                if original is None and widget.text() in self.UI_FIELD_TRANSLATIONS['en']:
                    original = widget.text()
                    widget.setProperty('mpw_original_field_text', original)
                if original in self.UI_FIELD_TRANSLATIONS['en']:
                    widget.setText(fields.get(original, original))
        # Static help tooltips: preserve the original key for reversible switching.
        tooltips = self.UI_TOOLTIP_TRANSLATIONS.get(language, {})
        if hasattr(self, 'tabs'):
            for widget in self.tabs.findChildren(QWidget):
                original = widget.property('mpw_original_tooltip')
                if original is None and widget.toolTip() in self.UI_TOOLTIP_TRANSLATIONS['en']:
                    original = widget.toolTip()
                    widget.setProperty('mpw_original_tooltip', original)
                if original in self.UI_TOOLTIP_TRANSLATIONS['en']:
                    widget.setToolTip(tooltips.get(original, original))
        # Translate only audited index/data-driven combos. Preserve indices and
        # currentData; never translate status, genre or provider values that
        # existing business logic may read via currentText().
        combo_translations = self.UI_SAFE_COMBO_TRANSLATIONS.get(language, {})
        for attribute in self.UI_SAFE_COMBO_NAMES:
            combo = getattr(self, attribute, None)
            if combo is None:
                continue
            combo.blockSignals(True)
            try:
                for index in range(combo.count()):
                    original = combo.itemData(index, Qt.ItemDataRole.UserRole + 1)
                    if original is None:
                        candidate = combo.itemText(index)
                        if candidate not in self.UI_SAFE_COMBO_TRANSLATIONS['en']:
                            continue
                        original = candidate
                        combo.setItemData(index, original, Qt.ItemDataRole.UserRole + 1)
                    combo.setItemText(index, combo_translations.get(original, original))
            finally:
                combo.blockSignals(False)
        self.refresh_archive_language_hf13()
        self.refresh_backup_language_hf12()
        self.refresh_record_language_hf11()
        self.refresh_releases_language_hf10()
        self.refresh_explorer_status_hf9()
        self.refresh_genre_static_hf6()
        self.refresh_suno_language_hf7()
        self.refresh_project_display_hf5()
        if hasattr(self, 'ai_band'):
            self.refresh_ai_language()
        self.refresh_alpha18_language()
        self.refresh_platform_status_choices()
        if hasattr(self, 'platform_list'):
            self.refresh_platforms()
        # Translate stable tab/group labels from their original German IDs,
        # not from the currently displayed text, so switching is reversible.
        translations = self.UI_SECTION_TRANSLATIONS.get(language, {})
        if hasattr(self, 'tabs'):
            for index in range(self.tabs.count()):
                original = self.tab_key(index)
                self.tabs.setTabText(index, translations.get(original, original))
            for group in self.tabs.findChildren(QGroupBox):
                original = group.property('mpw_original_group_title')
                if original is None:
                    original = group.title()
                    group.setProperty('mpw_original_group_title', original)
                if group is not self.language_group:
                    group.setTitle(translations.get(original, original))
        self.refresh_configuration_text_p33()
        self.refresh_configuration_text_p34()
        self.refresh_appearance_text_p35()
        self.refresh_ai_connections_entry_text()
        self.refresh_suno_send_text()

