    def refresh_releases_language_hf10(self):
        if not hasattr(self, 'release_check_result'):
            return
        date, result, placeholder, url = self.RELEASE_FORM_I18N_HF10.get(
            self.effective_language(), self.RELEASE_FORM_I18N_HF10['de'])
        for attr, value in (('release_date_form_label', date),
                            ('release_check_form_label', result),
                            ('release_platform_url_label', url)):
            label = getattr(self, attr, None)
            if label is not None:
                label.setText(value)
        self.release_check_result.setPlaceholderText(placeholder)

    def refresh_configuration_text_p33(self):
        if not hasattr(self, 'config_static_p33'):
            return
        words = self.CONFIG_TEXT_P33[self.effective_language()]
        for index, widget in self.config_static_p33.items():
            if isinstance(widget, QGroupBox):
                widget.setTitle(words[index])
            else:
                widget.setText(words[index])
        if hasattr(self, 'startup_tab_choice'):
            combo = self.startup_tab_choice
            index = combo.findData('__last__')
            if index >= 0:
                combo.blockSignals(True)
                try:
                    combo.setItemText(index, words[3])
                finally:
                    combo.blockSignals(False)

