    def ai_connection_text(self, key, **values):
        texts = self.AI_CONNECTION_TEXTS.get(self.effective_language(), self.AI_CONNECTION_TEXTS['en'])
        return texts[key].format(**values) if values else texts[key]

    def refresh_ai_connections_entry_text(self):
        if not hasattr(self, 'ai_connections_entry'):
            return
        t = self.ai_connection_text
        self.ai_connections_entry.setTitle(t('entry_group'))
        self.ai_connections_entry_hint.setText(t('entry_hint'))
        self.ai_connections_entry_button.setText(t('entry_button'))
        if self.ai_connections_dialog is not None:
            self._retranslate_ai_connections_dialog()

    def open_ai_connections_window(self):
        if self.ai_connections_dialog is None:
            self._build_ai_connections_dialog()
        self.ai_connections_dialog.show()
        self.ai_connections_dialog.raise_()
        self.ai_connections_dialog.activateWindow()
        self.refresh_ai_connections()

    def _build_ai_connections_dialog(self):
        from PySide6.QtWidgets import QScrollArea
        dialog = QDialog(self)
        dialog.resize(820, 760)
        self.ai_connections_dialog = dialog
        self._ai_conn_widgets = {}   # key -> widget whose text comes from AI_CONNECTION_TEXTS
        self._ai_conn_status = {}    # status labels, filled by _apply_ai_connection_status
        outer = QVBoxLayout(dialog)
        content = BackgroundPage()
        layout = QVBoxLayout(content)
        scroll = QScrollArea(dialog)
        scroll.setWidgetResizable(True)
        scroll.setWidget(content)
        outer.addWidget(scroll)

        def label(key=None, status=None):
            widget = QLabel()
            widget.setWordWrap(True)
            widget.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
            if key:
                self._ai_conn_widgets[key] = widget
            if status:
                self._ai_conn_status[status] = widget
            return widget

        def button(key, callback):
            widget = QPushButton()
            widget.clicked.connect(callback)
            self._ai_conn_widgets[key] = widget
            return widget

        def group(key, statuses, note=None, buttons=()):
            box = QGroupBox()
            self._ai_conn_widgets[key] = box
            box_layout = QVBoxLayout(box)
            for status in statuses:
                box_layout.addWidget(label(status=status))
            if note:
                box_layout.addWidget(label(key=note))
            if buttons:
                row = QHBoxLayout()
                for key_, callback in buttons:
                    row.addWidget(button(key_, callback))
                row.addStretch()
                box_layout.addLayout(row)
            layout.addWidget(box)
            return box

        open_link = lambda name: (lambda: QDesktopServices.openUrl(QUrl(AI_CONNECTION_LINKS[name])))
        layout.addWidget(label(key='intro'))
        group('grp_claude', ['claude_path', 'claude_login'],
              buttons=[('btn_install', open_link('claude_install')), ('btn_login', self.ai_connection_login)])
        group('grp_cli', ['gemini_path', 'codex_path', 'node'],
              buttons=[('btn_gemini', open_link('gemini_install')), ('btn_codex', open_link('codex_install')),
                       ('btn_node', open_link('node_install'))])
        group('grp_keys', ['key_Claude', 'key_ChatGPT', 'key_Gemini'], note='keys_note',
              buttons=[('btn_key_claude', open_link('anthropic_keys')), ('btn_key_openai', open_link('openai_keys')),
                       ('btn_key_gemini', open_link('gemini_keys'))])
        mpw_box = group('grp_mpw', [f'mcp_mpw_{c}' for c in MCP_CLIENTS], note='mpw_note',
                        buttons=[('btn_connect', self.ai_connection_add_mpw),
                                 ('btn_disconnect', self.ai_connection_remove_mpw),
                                 ('btn_desktop', self.ai_connection_copy_desktop_config)])
        suno_box = group('grp_suno', [f'mcp_suno_{c}' for c in MCP_CLIENTS], note='suno_note',
                         buttons=[('btn_suno_add', self.ai_connection_add_suno),
                                  ('btn_suno_login', self.ai_connection_suno_login),
                                  ('btn_suno_remove', self.ai_connection_remove_suno),
                                  ('btn_suno_access', open_link('suno_access'))])
        # Which AI CLI the buttons of a section act on (one menu per section, above its buttons).
        self._ai_conn_target = {}
        self._ai_conn_target_labels = []  # one "Einrichten für:" label per section (same text key)
        for section, box in (('mpw', mpw_box), ('suno', suno_box)):
            row = QHBoxLayout()
            target_label = QLabel()
            self._ai_conn_target_labels.append(target_label)
            row.addWidget(target_label)
            combo = QComboBox()
            for client in MCP_CLIENTS:
                combo.addItem(MCP_CLIENT_NAMES[client], client)
            row.addWidget(combo)
            row.addStretch()
            box.layout().insertLayout(box.layout().count() - 1, row)
            self._ai_conn_target[section] = combo
        net = group('grp_net', [f'tls_{host}' for host in AI_CONNECTION_TLS_HOSTS])
        self._ai_conn_tls_hint = label(key='tls_hint')
        net.layout().addWidget(self._ai_conn_tls_hint)
        self._ai_conn_tls_hint.hide()
        layout.addStretch()
        bottom = QHBoxLayout()
        bottom.addStretch()
        bottom.addWidget(button('btn_recheck', self.refresh_ai_connections))
        bottom.addWidget(button('btn_close', dialog.close))
        outer.addLayout(bottom)
        self._ai_conn_result = None
        self._retranslate_ai_connections_dialog()

    def _retranslate_ai_connections_dialog(self):
        t = self.ai_connection_text
        self.ai_connections_dialog.setWindowTitle(t('title'))
        for key, widget in self._ai_conn_widgets.items():
            if isinstance(widget, QGroupBox):
                widget.setTitle(t(key))
            else:
                widget.setText(t(key))
        for target_label in self._ai_conn_target_labels:
            target_label.setText(t('target_label'))
        if self._ai_conn_result is not None:
            self._apply_ai_connection_status(self._ai_conn_result)

    def refresh_ai_connections(self):
        if self.ai_connections_dialog is None or getattr(self, '_ai_conn_running', False):
            return
        self._ai_conn_running = True
        for widget in self._ai_conn_status.values():
            widget.setText(self.ai_connection_text('checking'))
        self._ai_conn_tls_hint.hide()
        self._ai_conn_widgets['btn_recheck'].setEnabled(False)
        job = AiConnectionCheckJob()
        self._ai_conn_job = job
        job.signals.finished.connect(self._ai_connection_check_finished)
        self.threadpool.start(job)

    def _ai_connection_check_finished(self, result):
        self._ai_conn_running = False
        self._ai_conn_result = result
        if self.ai_connections_dialog is not None:
            self._ai_conn_widgets['btn_recheck'].setEnabled(True)
            self._apply_ai_connection_status(result)

    def _apply_ai_connection_status(self, result):
        t = self.ai_connection_text
        status = self._ai_conn_status
        if result.get('error'):
            for widget in status.values():
                widget.setText(t('check_failed', error=result['error']))
            return
        installed = lambda path: t('found', path=path) if path else t('not_installed')
        status['claude_path'].setText(installed(result.get('claude')))
        login = result.get('claude_logged_in')
        status['claude_login'].setText(t('logged_in') if login is True else t('not_logged_in') if login is False
                                       else t('needs_claude') if not result.get('claude') else t('login_unknown'))
        status['gemini_path'].setText(t('cli_line', name='Gemini CLI', status=installed(result.get('gemini'))))
        status['codex_path'].setText(t('cli_line', name='Codex CLI', status=installed(result.get('codex'))))
        status['node'].setText(t('cli_line', name='Node.js', status=installed(result.get('node')))
                               if result.get('node') else t('node_missing'))
        for provider, env in API_KEY_ENV.items():
            status[f'key_{provider}'].setText(t('key_set' if result.get('keys', {}).get(provider) else 'key_missing', env=env))
        for client in MCP_CLIENTS:
            states = result.get('mcp', {}).get(client) or {}
            for name in ('mpw', 'suno'):
                key = {'connected': 'mcp_connected', 'needs_auth': 'mcp_needs_auth', 'failed': 'mcp_failed',
                       'registered': 'mcp_registered', 'missing': 'mcp_missing'}.get(states.get(name), 'mcp_unknown')
                text = t(key) if result.get(client) else t('not_installed')
                status[f'mcp_{name}_{client}'].setText(t('cli_line', name=MCP_CLIENT_NAMES[client], status=text))
        intercepted = False
        for host in AI_CONNECTION_TLS_HOSTS:
            info = result.get('tls', {}).get(host) or {}
            if info.get('error'):
                text = t('tls_error', host=host, error=info['error'])
            elif info.get('intercepted'):
                intercepted = True
                text = t('tls_intercepted', host=host, issuer=issuer_display_name(info['intercepted']))
            else:
                text = t('tls_ok', host=host)
            status[f'tls_{host}'].setText(text)
        self._ai_conn_tls_hint.setVisible(intercepted)

    # --- actions (each asks first where it changes the user's AI set-up) ---
    def _ai_connection_claude(self):
        exe = find_cli('claude')
        if not exe:
            QMessageBox.warning(self.ai_connections_dialog, self.ai_connection_text('title'),
                                self.ai_connection_text('need_claude'))
        return exe

    def _ai_connection_target(self, section):
        """(client, executable) chosen in a section's 'Einrichten für' menu, or (client, None)."""
        client = self._ai_conn_target[section].currentData()
        exe = find_cli(client)
        if not exe:
            QMessageBox.warning(self.ai_connections_dialog, self.ai_connection_text('title'),
                                self.ai_connection_text('need_cli', name=MCP_CLIENT_NAMES[client]))
        return client, exe

    def _ai_connection_run(self, args):
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        try:
            code, text = run_helper_tool(args, timeout=120, cwd=str(Path.home()))
        finally:
            QApplication.restoreOverrideCursor()
        if code == 0:
            QMessageBox.information(self.ai_connections_dialog, self.ai_connection_text('title'),
                                    self.ai_connection_text('done'))
        else:
            LOGGER.error('KI-Verbindung: Befehl fehlgeschlagen (%s): %s', code, text)
            QMessageBox.warning(self.ai_connections_dialog, self.ai_connection_text('title'),
                                self.ai_connection_text('failed', detail=(text or str(code))[-600:]))
        self.refresh_ai_connections()

    def _ai_connection_new_console(self, args):
        """Interactive steps (sign-in) run in their own console window."""
        try:
            subprocess.Popen(args, cwd=str(Path.home()),
                             creationflags=getattr(subprocess, 'CREATE_NEW_CONSOLE', 0))
            return True
        except OSError as exc:
            QMessageBox.warning(self.ai_connections_dialog, self.ai_connection_text('title'),
                                self.ai_connection_text('failed', detail=str(exc)))
            return False

    def ai_connection_login(self):
        exe = self._ai_connection_claude()
        if exe and self._ai_connection_new_console([exe, 'auth', 'login']):
            QMessageBox.information(self.ai_connections_dialog, self.ai_connection_text('title'),
                                    self.ai_connection_text('login_started'))

    def _ai_connection_confirm_for(self, key, client):
        text = self.ai_connection_text(key, name=MCP_CLIENT_NAMES[client])
        return QMessageBox.question(
            self.ai_connections_dialog, self.ai_connection_text('title'), text,
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No) == QMessageBox.StandardButton.Yes

    def ai_connection_add_mpw(self):
        client, exe = self._ai_connection_target('mpw')
        if not exe:
            return
        command = mpw_mcp_server_command()
        if not Path(command[-1]).is_file():
            return QMessageBox.warning(self.ai_connections_dialog, self.ai_connection_text('title'),
                                       self.ai_connection_text('mcp_exe_missing', path=command[-1]))
        if self._ai_connection_confirm_for('confirm_connect', client):
            self._ai_connection_run(mcp_setup_command(client, 'add', 'mpw', exe, command))

    def ai_connection_remove_mpw(self):
        client, exe = self._ai_connection_target('mpw')
        if exe and self._ai_connection_confirm_for('confirm_disconnect', client):
            self._ai_connection_run(mcp_setup_command(client, 'remove', 'mpw', exe))

    def ai_connection_copy_desktop_config(self):
        QApplication.clipboard().setText(claude_desktop_config_snippet(mpw_mcp_server_command()))
        QMessageBox.information(self.ai_connections_dialog, self.ai_connection_text('title'),
                                self.ai_connection_text('desktop_copied'))

    def ai_connection_add_suno(self):
        client, exe = self._ai_connection_target('suno')
        if exe and self._ai_connection_confirm_for('confirm_suno', client):
            self._ai_connection_run(mcp_setup_command(client, 'add', 'suno', exe))

    def ai_connection_remove_suno(self):
        client, exe = self._ai_connection_target('suno')
        if exe and self._ai_connection_confirm_for('confirm_suno_remove', client):
            self._ai_connection_run(mcp_setup_command(client, 'remove', 'suno', exe))

