    def suno_send_text(self, key, **values):
        texts = self.SUNO_SEND_TEXTS.get(self.effective_language(), self.SUNO_SEND_TEXTS['en'])
        return texts[key].format(**values) if values else texts[key]

    def refresh_suno_send_text(self):
        if not hasattr(self, 'suno_send_button'):
            return
        self.suno_send_button.setText(self.suno_send_text('button'))
        self.suno_send_button.setToolTip(self.suno_send_text('tooltip'))

    def suno_prompt_choices(self, sid):
        """[(label, (style, lyrics))]: the saved active prompt first, then saved versions (newest first)."""
        row = self.con.execute('SELECT style,lyrics FROM songs WHERE id=?', (sid,)).fetchone()
        choices = [(self.suno_send_text('active'), (row[0] or '', row[1] or ''))] if row else []
        for vid, provider, created, style, lyrics in self.con.execute(
                'SELECT id,provider,created_at,style,lyrics FROM prompt_versions WHERE song_id=? ORDER BY id DESC', (sid,)):
            choices.append((self.suno_send_text('version', id=vid, provider=provider, created=created),
                            (style or '', lyrics or '')))
        return choices

    def open_suno_send_dialog(self):
        sid = self.song_select.currentData()
        song = self.con.execute('SELECT title,style,lyrics FROM songs WHERE id=?', (sid,)).fetchone() if sid is not None else None
        if not song:
            return self.error(self.suno_send_text('no_song'))
        t = self.suno_send_text
        dialog = QDialog(self)
        dialog.setWindowTitle(t('title', song=song[0]))
        dialog.resize(880, 760)
        layout = QVBoxLayout(dialog)
        form = QFormLayout()
        choice = QComboBox()
        for label, prompt in self.suno_prompt_choices(sid):
            choice.addItem(label, prompt)
        form.addRow(t('prompt_label'), choice)
        title_edit = QLineEdit(song[0] or '')
        title_edit.setMaxLength(SUNO_LIMITS['title'])
        form.addRow(t('title_label'), title_edit)
        layout.addLayout(form)
        unsaved = QLabel(t('unsaved'))
        unsaved.setWordWrap(True)
        unsaved.setVisible((self.style.toPlainText().strip(), self.lyrics.toPlainText().strip())
                           != ((song[1] or '').strip(), (song[2] or '').strip()))
        layout.addWidget(unsaved)
        style_box = QGroupBox(); style_view = QTextEdit(); style_view.setReadOnly(True)
        QVBoxLayout(style_box).addWidget(style_view)
        lyrics_box = QGroupBox(); lyrics_view = QTextEdit(); lyrics_view.setReadOnly(True)
        QVBoxLayout(lyrics_box).addWidget(lyrics_view)
        split = QSplitter(Qt.Orientation.Horizontal)
        split.addWidget(style_box); split.addWidget(lyrics_box); split.setSizes([320, 540])
        layout.addWidget(split, 1)
        info = QLabel(t('info')); info.setWordWrap(True)
        layout.addWidget(info)
        status = QLabel(); status.setWordWrap(True)
        layout.addWidget(status)
        results = QTextBrowser(); results.setOpenExternalLinks(True); results.setMaximumHeight(170); results.hide()
        layout.addWidget(results)
        buttons = QHBoxLayout()
        send = QPushButton(t('btn_send')); save_links = QPushButton(t('btn_save_links')); save_links.hide()
        close = QPushButton(t('btn_close')); close.clicked.connect(dialog.close)
        buttons.addWidget(send); buttons.addWidget(save_links); buttons.addStretch(); buttons.addWidget(close)
        layout.addLayout(buttons)

        def show_choice(*_):
            style, lyrics = choice.currentData() or ('', '')
            style_view.setPlainText(style); lyrics_view.setPlainText(lyrics)
            style_box.setTitle(t('style_label', count=len(style.strip())))
            lyrics_box.setTitle(t('lyrics_label', count=len(lyrics.strip())))
        choice.currentIndexChanged.connect(show_choice)
        show_choice()
        state = {'clips': []}

        def do_send():
            style, lyrics = choice.currentData() or ('', '')
            arguments = suno_create_arguments(title_edit.text(), style, lyrics)
            if not arguments.get('lyrics'):
                return self.error(t('empty'))
            if any(len(arguments.get(k, '')) > limit for k, limit in SUNO_LIMITS.items()):
                return self.error(t('too_long'))
            if QMessageBox.question(dialog, dialog.windowTitle(),
                                    t('confirm', title=arguments['title'] or '–', style=len(arguments.get('style', '')),
                                      lyrics=len(arguments['lyrics'])),
                                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                                    QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
                return
            send.setEnabled(False); choice.setEnabled(False); title_edit.setEnabled(False)
            results.hide(); save_links.hide()
            status.setText(t('sending'))
            job = SunoSendJob('claude', arguments)
            state['job'] = job  # keep a reference while it runs
            # Bound method of the main window = queued into the GUI thread (a lambda could run
            # in the worker thread). The callback is looked up by the job's token.
            self._suno_send_callbacks[job.token] = lambda result: finished(result, arguments)
            job.signals.finished.connect(self._suno_send_finished)
            self.threadpool.start(job)

        def finished(result, arguments):
            send.setEnabled(True); choice.setEnabled(True); title_edit.setEnabled(True)
            text, clips = self.suno_send_report(result, arguments)
            status.setText(text)
            state['clips'] = clips
            if clips:
                html_lines = []
                for clip in clips:
                    name = html.escape(clip['title'] or arguments['title'] or clip['id'])
                    link = (f' – <a href="{html.escape(clip["url"])}">{html.escape(clip["url"])}</a>'
                            if clip['url'] else '')
                    html_lines.append(f'<li>{name} <i>({html.escape(clip["status"])})</i>{link}</li>')
                results.setHtml('<ul>' + ''.join(html_lines) + '</ul>')
                results.show()
                save_links.setVisible(any(c['url'] for c in clips))

        def do_save_links():
            count = self.save_suno_links(sid, title_edit.text() or song[0], state['clips'])
            self.message(dialog.windowTitle(), t('links_saved', count=count))
            save_links.setEnabled(False)

        send.clicked.connect(do_send)
        save_links.clicked.connect(do_save_links)
        self.suno_send_dialog = dialog
        dialog.show()

    def _suno_send_finished(self, result):
        callback = self._suno_send_callbacks.pop(result.get('token'), None)
        if callback is not None:
            callback(result)

    def suno_send_report(self, result, arguments):
        """(text for the status line, clips) for a finished SunoSendJob."""
        t = self.suno_send_text
        if result.get('provider_error'):
            kind, code, detail = result['provider_error']
            if kind == 'cli_timeout':
                return t('timeout', minutes=SUNO_SEND_TIMEOUT_SECONDS // 60), []
            return t('error', detail=self.ai_api_error_text(kind, 'Claude', code, detail)[0]), []
        if result.get('mcp_status') not in (None, 'connected'):
            return t('not_connected', status=result['mcp_status']), []
        sent = result.get('create_inputs') or []
        if not sent:
            detail = '\n'.join(result.get('errors') or []) or result.get('final_error') or result.get('stderr') or ''
            return (t('error', detail=detail) if detail else t('not_sent')), []
        notes = []
        if not all(suno_send_matches(item, arguments) for item in sent):
            notes.append(t('mismatch'))
        if len(sent) > 1:
            notes.append(t('multiple'))
        clips = suno_clips(result)
        if result.get('errors') and not clips:
            return t('error', detail='\n'.join(result['errors'])), []
        head = t('done', count=len(clips)) if clips else t('no_clips')
        return '\n'.join([head, *notes]), clips

    def save_suno_links(self, sid, title, clips):
        """Store the Suno song links with the song (Medien & Player); existing links are kept."""
        with_url = [clip for clip in clips if clip.get('url')]
        added = 0
        with self.con:
            for index, clip in enumerate(with_url, 1):
                label = self.suno_send_text('link_label', title=clip.get('title') or title, index=index, count=len(with_url))
                cursor = self.con.execute('INSERT OR IGNORE INTO media_links(song_id,platform,url,label) VALUES(?,?,?,?)',
                                          (sid, 'Suno', clip['url'], label))
                added += cursor.rowcount
        if hasattr(self, 'refresh_media'):
            self.refresh_media()
        return added

