    def custom_theme_presets(self):
        """Load only complete, valid user-defined palettes."""
        raw = self.app_configuration().get('custom_theme_presets', {})
        if not isinstance(raw, dict):
            return {}
        valid = {}
        for name, palette in raw.items():
            if (not isinstance(name, str) or not name.strip()
                    or name in self.THEME_PRESETS or not isinstance(palette, dict)):
                continue
            if all(isinstance(palette.get(k), str) and
                   QColor(palette[k]).isValid() for k in self.THEME_DEFAULTS):
                valid[name] = {k: QColor(palette[k]).name() for k in self.THEME_DEFAULTS}
        return valid

    def refresh_theme_presets(self, select=None):
        current = select or self.theme_preset_choice.currentText()
        self.theme_preset_choice.blockSignals(True)
        self.theme_preset_choice.clear()
        self.theme_preset_choice.addItems(self.THEME_PRESETS.keys())
        self.theme_preset_choice.addItems(sorted(self.custom_theme_presets(), key=str.casefold))
        index = self.theme_preset_choice.findText(current)
        self.theme_preset_choice.setCurrentIndex(max(0, index))
        self.theme_preset_choice.blockSignals(False)
        if getattr(self, '_preview_theme_name', None) is not None:
            self.stop_theme_preview()

