    def save_custom_theme_preset(self):
        name, ok = QInputDialog.getText(self, self.theme_dialog_text_p22('save_title'),
                                        self.theme_dialog_text_p22('name_prompt'))
        if not ok:
            return
        name = name.strip()
        if not name or len(name) > 80:
            QMessageBox.warning(self, self.localized_dialog_title('Ungültiger Name'),
                                self.theme_dialog_text_p22('invalid_name'))
            return
        if name in self.THEME_PRESETS:
            QMessageBox.warning(self, self.theme_dialog_text_p22('reserved_title'),
                                self.theme_dialog_text_p22('reserved_body'))
            return
        presets = self.custom_theme_presets()
        if any(old.casefold() == name.casefold() and old != name for old in presets):
            QMessageBox.warning(self, self.theme_dialog_text_p22('duplicate_title'),
                                self.theme_dialog_text_p22('duplicate_body'))
            return
        if name in presets and QMessageBox.question(
                self, self.localized_dialog_title('Vorlage überschreiben'),
                self.theme_dialog_text_p22('overwrite', name=name),
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
            return
        presets[name] = self.current_color_theme()
        self.save_app_configuration(custom_theme_presets=presets)
        self.refresh_theme_presets(select=name)

    def delete_custom_theme_preset(self):
        name = self.theme_preset_choice.currentText()
        presets = self.custom_theme_presets()
        if name not in presets:
            QMessageBox.information(self, self.theme_dialog_text_p22('builtin_title'),
                                    self.theme_dialog_text_p22('builtin_body'))
            return
        if QMessageBox.question(
                self, self.localized_dialog_title('Farbvorlage löschen'),
                self.theme_dialog_text_p22('delete', name=name),
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
            return
        del presets[name]
        self.save_app_configuration(custom_theme_presets=presets)
        self.refresh_theme_presets()

