    def theme_transfer_text(self, key, **values):
        language = self.effective_language()
        translations = self.THEME_TRANSFER_TEXT_ALPHA21
        template = translations.get(language, translations['de']).get(key, translations['de'][key])
        return template.format(**values)

    def export_theme_preset(self):
        """Export the selected preset as a portable, data-only JSON document."""
        name = self.theme_preset_choice.currentText()
        palette = self.THEME_PRESETS.get(name) or self.custom_theme_presets().get(name)
        if not palette:
            QMessageBox.warning(self, self.localized_dialog_title('Export nicht möglich'), self.localized_message_text('Bitte eine gültige Vorlage wählen.'))
            return
        destination, _ = QFileDialog.getSaveFileName(
            self, self.theme_transfer_text('export_title'), 'MPW_Farbvorlage.json', self.theme_transfer_text('json_filter'))
        if not destination:
            return
        try:
            payload = {'format': 'MPW-color-theme', 'version': 1,
                       'name': name, 'colors': dict(palette)}
            target = Path(destination)
            with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8',
                    dir=str(target.parent), prefix='.mpw_theme_', suffix='.tmp',
                    delete=False) as handle:
                temp_name = handle.name
                json.dump(payload, handle, ensure_ascii=False, indent=2)
            try:
                os.replace(temp_name, target)
            finally:
                if os.path.exists(temp_name):
                    os.unlink(temp_name)
        except OSError as exc:
            QMessageBox.critical(self, self.theme_transfer_text('export_error'), str(exc))
            return
        QMessageBox.information(self, self.localized_dialog_title('Export abgeschlossen'),
                                self.theme_transfer_text('export_done', path=destination))

    def import_theme_preset(self):
        """Validate a portable palette before adding it to user presets."""
        source, _ = QFileDialog.getOpenFileName(
            self, self.theme_transfer_text('import_title'), '', self.theme_transfer_text('json_filter'))
        if not source:
            return
        try:
            if Path(source).stat().st_size > 65536:
                raise ValueError(self.theme_transfer_text('too_large'))
            with open(source, 'r', encoding='utf-8-sig') as handle:
                payload = json.load(handle)
            if not isinstance(payload, dict) or payload.get('format') != 'MPW-color-theme' or payload.get('version') != 1:
                raise ValueError(self.theme_transfer_text('unsupported'))
            name, colors = payload.get('name'), payload.get('colors')
            if not isinstance(name, str) or not 1 <= len(name.strip()) <= 80:
                raise ValueError(self.theme_transfer_text('invalid_name'))
            name = name.strip()
            if not isinstance(colors, dict) or set(colors) != set(self.THEME_DEFAULTS):
                raise ValueError(self.theme_transfer_text('eight_colors'))
            if not all(isinstance(colors[k], str) and
                       re.fullmatch(r'#[0-9a-fA-F]{6}', colors[k]) for k in self.THEME_DEFAULTS):
                raise ValueError(self.theme_transfer_text('invalid_colors'))
        except (OSError, UnicodeError, ValueError, json.JSONDecodeError) as exc:
            QMessageBox.warning(self, self.localized_dialog_title('Import fehlgeschlagen'), str(exc))
            return
        presets = self.custom_theme_presets()
        if name in self.THEME_PRESETS or any(existing.casefold() == name.casefold() for existing in presets):
            name, ok = QInputDialog.getText(
                self, self.theme_transfer_text('duplicate_title'),
                self.theme_transfer_text('duplicate_prompt'),
                text=name + self.theme_transfer_text('import_suffix'))
            if not ok:
                return
            name = name.strip()
            if (not 1 <= len(name) <= 80 or
                    any(existing.casefold() == name.casefold() for existing in
                        list(self.THEME_PRESETS) + list(presets))):
                QMessageBox.warning(self, self.localized_dialog_title('Ungültiger Name'),
                                    self.theme_transfer_text('duplicate_error'))
                return
        presets[name] = {key: colors[key].lower() for key in self.THEME_DEFAULTS}
        self.save_app_configuration(custom_theme_presets=presets)
        self.refresh_theme_presets(select=name)
        QMessageBox.information(self, self.localized_dialog_title('Import abgeschlossen'),
                                self.theme_transfer_text('import_done', name=name))

    def preview_theme_preset(self):
        """Preview a selected preset without writing to the settings file."""
        name = self.theme_preset_choice.currentText()
        preset = self.THEME_PRESETS.get(name) or self.custom_theme_presets().get(name)
        if not preset:
            return
        self._preview_theme_name = name
        self.apply_color_theme(palette=preset)
        self.theme_preview_status.setText(
            f'Vorschau aktiv: {name} – noch nicht gespeichert. '
            'Mit „Übernehmen“ speichern oder „Vorschau beenden“ zurückkehren.')
        self.theme_preview_stop.setEnabled(True)

    def stop_theme_preview(self):
        """Restore the last saved theme, leaving stored settings untouched."""
        if getattr(self, '_preview_theme_name', None) is None:
            return
        self._preview_theme_name = None
        self.apply_color_theme()
        if hasattr(self, 'theme_preview_status'):
            self.theme_preview_status.setText('Keine Vorschau aktiv – gespeicherte Farben werden angezeigt.')
            self.theme_preview_stop.setEnabled(False)

    def on_theme_preview_tab_changed(self, index):
        """Never leave a temporary preview active when leaving configuration."""
        if (index >= 0 and self.tab_key(index) != 'Konfiguration'
                and getattr(self, '_preview_theme_name', None) is not None):
            self.stop_theme_preview()

    def apply_theme_preset(self):
        name = self.theme_preset_choice.currentText()
        preset = self.THEME_PRESETS.get(name) or self.custom_theme_presets().get(name)
        if not preset:
            return
        if QMessageBox.question(
                self, self.localized_dialog_title('Farbschema übernehmen'),
                self.confirmation_text('apply_theme', name=name),
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
            return
        self._preview_theme_name = None
        self.save_app_configuration(color_theme=dict(preset))
        self.apply_color_theme()
        if hasattr(self, 'theme_preview_status'):
            self.theme_preview_status.setText('Farbschema gespeichert: ' + name)
            self.theme_preview_stop.setEnabled(False)

    def current_color_theme(self):
        stored = self.app_configuration().get('color_theme', {})
        if not isinstance(stored, dict):
            stored = {}
        result = dict(self.THEME_DEFAULTS)
        for key in result:
            value = stored.get(key)
            if isinstance(value, str) and QColor(value).isValid():
                result[key] = QColor(value).name()
        return result

    @staticmethod
    def readable_button_text(background):
        """Choose black/white text using WCAG relative luminance contrast."""
        color = QColor(background)
        if not color.isValid():
            return '#ffffff'
        def linear(channel):
            value = channel / 255.0
            return value / 12.92 if value <= 0.04045 else ((value + 0.055) / 1.055) ** 2.4
        luminance = (0.2126 * linear(color.red()) +
                     0.7152 * linear(color.green()) +
                     0.0722 * linear(color.blue()))
        return '#171717' if (luminance + 0.05) / 0.05 >= 1.05 / (luminance + 0.05) else '#ffffff'

    @staticmethod
    def theme_contrast_ratio(first, second):
        """WCAG 2.x contrast ratio of two opaque RGB colors."""
        def luminance(value):
            color = QColor(value)
            if not color.isValid():
                raise ValueError('Ungültiger Farbwert: ' + str(value))
            def linear(channel):
                channel = channel / 255.0
                return channel / 12.92 if channel <= 0.04045 else ((channel + 0.055) / 1.055) ** 2.4
            return (0.2126 * linear(color.red()) + 0.7152 * linear(color.green())
                    + 0.0722 * linear(color.blue()))
        a, b = sorted((luminance(first), luminance(second)), reverse=True)
        return (a + 0.05) / (b + 0.05)

