    def theme_contrast_texts(self):
        return self.THEME_CONTRAST_I18N.get(self.effective_language(), self.THEME_CONTRAST_I18N['de'])

    def theme_contrast_checks(self, palette=None):
        """Single source of truth for TXT, CSV and on-screen checks."""
        name = getattr(self, '_preview_theme_name', None)
        preset = ((self.THEME_PRESETS.get(name) or self.custom_theme_presets().get(name))
                  if name else None)
        colors = dict(palette) if palette is not None else (dict(preset) if preset else self.current_color_theme())
        button = colors['button']
        hover = QColor(button).lighter(120).name()
        labels = self.THEME_CHECK_LABELS.get(self.effective_language(), self.THEME_CHECK_LABELS['de'])
        checks = [
            (labels[0], self.readable_button_text(button), button),
            (labels[1], self.readable_button_text(hover), hover),
            (labels[2], colors['foreground'], colors['surface']),
            (labels[3], colors['foreground'], colors['background']),
            (labels[4], colors['foreground'], colors['tab']),
            (labels[5], colors['foreground'], colors['accent']),
            (labels[6], colors['foreground'], colors['selection']),
        ]
        t = self.theme_contrast_texts()
        rows = []
        for label, foreground, background in checks:
            ratio = self.theme_contrast_ratio(foreground, background)
            status = 'OK' if ratio >= 4.5 else (t[30] if ratio >= 3 else t[31])
            rows.append((label, foreground, background, ratio, status))
        return (str(name) + ' (' + t[29] + ')' if name else t[28]), rows

    def build_theme_contrast_report(self):
        """Build a read-only report for the current or preview color theme."""
        theme_name, checks = self.theme_contrast_checks()
        t = self.theme_contrast_texts()
        lines = ['MPW – ' + t[0], t[1] + ': ' + theme_name, t[2], '']
        for label, foreground, background, ratio, status in checks:
            lines.append(f'{label}: {ratio:.2f}:1 – {status}  ({t[26]} {foreground}, {t[27]} {background})')
        warnings = sum(ratio < 4.5 for _, _, _, ratio, _ in checks)
        lines.extend(['', f'{t[3]}: {warnings}', t[4], t[5]])
        return '\n'.join(lines)

    def show_theme_contrast_report(self):
        t = self.theme_contrast_texts()
        QMessageBox.information(self.appearance_dialog, t[6], self.build_theme_contrast_report())

    def export_theme_contrast_report(self):
        """Export the same report shown in the dialog, without changing settings."""
        from datetime import datetime
        t = self.theme_contrast_texts()
        filename = 'MPW_Farbschema_Kontrast_' + datetime.now().strftime('%Y%m%d_%H%M%S') + '.txt'
        path, _ = QFileDialog.getSaveFileName(self.appearance_dialog, t[7], filename, t[8])
        if not path:
            return
        try:
            Path(path).write_text(self.build_theme_contrast_report() + '\n', encoding='utf-8')
        except OSError as exc:
            QMessageBox.warning(self.appearance_dialog, t[9], str(exc))
            return
        QMessageBox.information(self.appearance_dialog, t[10], t[11] + '\n' + str(path))

    def export_theme_contrast_csv(self):
        """Export every contrast check for spreadsheet analysis; no theme mutation."""
        t = self.theme_contrast_texts()
        filename = 'MPW_Farbschema_Kontrast_' + datetime.now().strftime('%Y%m%d_%H%M%S') + '.csv'
        path, _ = QFileDialog.getSaveFileName(self.appearance_dialog, t[12], filename, t[13])
        if not path:
            return
        try:
            theme_name, checks = self.theme_contrast_checks()
            with Path(path).open('w', encoding='utf-8-sig', newline='') as stream:
                writer = csv.writer(stream, delimiter=';')
                writer.writerow([t[1], t[17], t[18], t[19], t[20], t[21], t[22], t[23]])
                for label, foreground, background, ratio, status in checks:
                    writer.writerow([theme_name, label, foreground, background,
                                     f'{ratio:.2f}'.replace('.', ','), status,
                                     t[24] if ratio >= 4.5 else t[25],
                                     t[24] if ratio >= 3 else t[25]])
        except (OSError, ValueError) as exc:
            QMessageBox.warning(self.appearance_dialog, t[14], str(exc))
            return
        QMessageBox.information(self.appearance_dialog, t[15], t[16] + '\n' + str(path))

    # Alpha 21 Preview 25: localized read-only theme comparison.
    THEME_COMPARE_I18N = {'de': ('Aktuell gespeichert', 'Standard', 'Eigene Vorlage', 'Farbschemata vergleichen – Kontrast', 'Lesende Gegenüberstellung aller Standardvorlagen, eigenen Vorlagen und der gespeicherten Farben. 4,5:1 ist der Orientierungswert für normalen Text. Es werden keine Farben geändert.', 'Farbschema', 'Prüfungen ≥ 4,5:1', 'Niedrigster Kontrast', 'Ungültige Farben', 'Schließen'), 'en': ('Currently saved', 'Built-in', 'Custom preset', 'Compare color schemes – contrast', 'Read-only comparison of built-in presets, custom presets and saved colors. 4.5:1 is the reference value for normal text. No colors will be changed.', 'Color scheme', 'Checks ≥ 4.5:1', 'Lowest contrast', 'Invalid colors', 'Close'), 'fr': ('Actuellement enregistré', 'Standard', 'Modèle personnalisé', 'Comparer les thèmes – contraste', 'Comparaison en lecture seule des thèmes standard, personnalisés et des couleurs enregistrées. 4,5:1 est la valeur de référence pour le texte normal. Aucune couleur ne sera modifiée.', 'Thème', 'Contrôles ≥ 4,5:1', 'Contraste minimal', 'Couleurs invalides', 'Fermer'), 'es': ('Guardado actualmente', 'Predeterminado', 'Tema personalizado', 'Comparar temas – contraste', 'Comparación de solo lectura de temas predeterminados, personalizados y colores guardados. 4,5:1 es el valor de referencia para texto normal. No se cambiará ningún color.', 'Tema', 'Pruebas ≥ 4,5:1', 'Contraste mínimo', 'Colores no válidos', 'Cerrar'), 'it': ('Attualmente salvato', 'Predefinito', 'Tema personalizzato', 'Confronta temi – contrasto', 'Confronto in sola lettura dei temi predefiniti, personalizzati e dei colori salvati. 4,5:1 è il valore di riferimento per il testo normale. Nessun colore verrà modificato.', 'Tema', 'Verifiche ≥ 4,5:1', 'Contrasto minimo', 'Colori non validi', 'Chiudi')}

    def compare_theme_contrast(self):
        """Read-only overview of all built-in and user presets plus saved colors."""
        t = self.THEME_COMPARE_I18N.get(self.effective_language(), self.THEME_COMPARE_I18N['de'])
        palettes = [(t[0], self.current_color_theme())]
        palettes.extend((name + ' (' + t[1] + ')', dict(palette))
                        for name, palette in self.THEME_PRESETS.items())
        palettes.extend((name + ' (' + t[2] + ')', dict(palette))
                        for name, palette in self.custom_theme_presets().items())
        results = []
        for label, palette in palettes:
            try:
                _, checks = self.theme_contrast_checks(palette=palette)
                good = sum(ratio >= 4.5 for _, _, _, ratio, _ in checks)
                minimum = min(ratio for _, _, _, ratio, _ in checks)
                results.append((label, good, len(checks), minimum))
            except (ValueError, KeyError, TypeError):
                results.append((label, None, 0, None))
        dialog = QDialog(getattr(self, 'appearance_dialog', self))
        dialog.setWindowTitle(t[3])
        dialog.resize(760, 460)
        layout = QVBoxLayout(dialog)
        hint = QLabel(t[4])
        hint.setWordWrap(True)
        layout.addWidget(hint)
        table = QTableWidget(len(results), 3, dialog)
        table.setHorizontalHeaderLabels([t[5], t[6], t[7]])
        table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        table.setSelectionBehavior(QAbstractItemView.SelectRows)
        table.verticalHeader().setVisible(False)
        for row, (label, good, total, minimum) in enumerate(results):
            values = [label, f'{good}/{total}' if good is not None else t[8],
                      f'{minimum:.2f}:1' if minimum is not None else '–']
            for column, value in enumerate(values):
                table.setItem(row, column, QTableWidgetItem(value))
        table.horizontalHeader().setSectionResizeMode(0, QHeaderView.Stretch)
        table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeToContents)
        table.horizontalHeader().setSectionResizeMode(2, QHeaderView.ResizeToContents)
        layout.addWidget(table)
        close = QPushButton(t[9])
        close.clicked.connect(dialog.accept)
        layout.addWidget(close)
        dialog.exec()

    def apply_color_theme(self, palette=None):
        # A preview changes the widgets only; never persist it automatically.
        c = dict(palette) if palette is not None else self.current_color_theme()
        hover = QColor(c['button']).lighter(120).name()
        button_text = self.readable_button_text(c['button'])
        hover_text = self.readable_button_text(hover)
        # Tooltips are native top-level windows on some Windows/Qt styles and
        # may ignore QMainWindow's local QSS. Apply the current input-field
        # palette to the application-level tooltip and its Qt palette.
        tooltip_css = (f"QToolTip {{ background-color: {c['surface']}; "
                       f"color: {c['foreground']}; border: 1px solid {c['border']}; "
                       "padding: 5px; border-radius: 6px; }}")
        app = QApplication.instance()
        if app is not None:
            app.setStyleSheet(tooltip_css)
        tip_palette = QPalette()
        tip_palette.setColor(QPalette.ColorRole.ToolTipBase, QColor(c['surface']))
        tip_palette.setColor(QPalette.ColorRole.ToolTipText, QColor(c['foreground']))
        QToolTip.setPalette(tip_palette)
        self.setStyleSheet(f"""
            QMainWindow, QWidget {{ background-color: {c['background']}; color: {c['foreground']}; font: 10pt 'Segoe UI'; }}
            QLineEdit, QTextEdit, QComboBox, QListWidget, QTreeView, QTableView,
            QTableWidget, QTreeWidget, QPlainTextEdit, QSpinBox, QDoubleSpinBox {{
                background-color: {c['surface']}; color: {c['foreground']};
                border: 1px solid {c['border']}; border-radius: 6px; padding: 5px;
                selection-background-color: {c['selection']}; selection-color: {c['foreground']};
            }}
            QPushButton {{ background-color: {c['button']}; color: {button_text};
                border: 1px solid {c['border']}; border-radius: 6px; padding: 8px 12px; font-weight: 600; }}
            QPushButton:hover {{ background-color: {hover}; color: {hover_text}; }}
            QPushButton:disabled {{ color: {button_text}; }}
            QTabWidget::pane {{ border: 1px solid {c['border']}; }}
            QTabBar::tab {{ background-color: {c['tab']}; color: {c['foreground']};
                padding: 10px 17px; margin-right: 3px; }}
            QTabBar::tab:selected {{ background-color: {c['accent']}; }}
            QGroupBox {{ border: 1px solid {c['border']}; border-radius: 8px;
                margin-top: 12px; padding: 12px; }}
            QGroupBox::title {{ subcontrol-origin: margin; left: 12px; padding: 0 4px; }}
            QHeaderView::section {{ background-color: {c['tab']}; color: {c['foreground']};
                border: 1px solid {c['border']}; padding: 5px; }}
            QMenu {{ background-color: {c['surface']}; color: {c['foreground']};
                border: 1px solid {c['border']}; }}
            QMenu::item:selected {{ background-color: {c['accent']}; }}
            QScrollArea, QScrollArea > QWidget > QWidget {{ background-color: {c['background']}; }}
            QToolTip {{ background-color: {c['surface']}; color: {c['foreground']}; border: 1px solid {c['border']}; padding: 5px; }}
        """)
        self.style_tab_help_buttons(c)
        # QFileSystemModel's QTreeView viewport can otherwise remain white on
        # Windows despite the global QWidget stylesheet.  Style this view
        # explicitly, including alternating rows and selected entries.
        if hasattr(self, 'explorer_tree'):
            surface = QColor(c['surface'])
            alternate = surface.lighter(112) if surface.lightness() < 128 else surface.darker(106)
            alternate_hex = alternate.name()
            self.explorer_tree.setStyleSheet(f"""
                QTreeView {{
                    background-color: {c['surface']};
                    alternate-background-color: {alternate_hex};
                    color: {c['foreground']};
                    border: 1px solid {c['border']};
                    selection-background-color: {c['selection']};
                    selection-color: {c['foreground']};
                }}
                QTreeView::item {{
                    color: {c['foreground']};
                    background-color: transparent;
                    padding: 3px;
                }}
                QTreeView::item:alternate {{ background-color: {alternate_hex}; }}
                QTreeView::item:selected {{
                    background-color: {c['selection']};
                    color: {c['foreground']};
                }}
                QTreeView::item:selected:!active {{
                    background-color: {c['selection']};
                    color: {c['foreground']};
                }}
                QHeaderView::section {{
                    background-color: {c['tab']};
                    color: {c['foreground']};
                    border: 1px solid {c['border']};
                    padding: 5px;
                }}
            """)
        if hasattr(self, 'background_preview'):
            self.background_preview.setStyleSheet(
                f"background-color: {c['surface']}; border: 1px solid {c['border']}; border-radius: 5px;")
        if hasattr(self, 'theme_color_buttons'):
            self.refresh_theme_color_buttons(c)
        if hasattr(self, 'tabs'):
            for i in range(self.tabs.count()):
                widget = self.tabs.widget(i)
                if widget:
                    widget.update()

    def refresh_theme_color_buttons(self, colors=None):
        colors = colors if colors is not None else self.current_color_theme()
        for key, button in self.theme_color_buttons.items():
            color = QColor(colors[key])
            text = self.readable_button_text('#30343b')  # Kontrast zum tatsächlichen Button-Hintergrund
            button.setText(colors[key].upper() + '  ·  Ändern …')
            button.setStyleSheet(
                f'QPushButton {{ background-color: #30343b; color: {text}; '
                f'border: 4px solid {colors[key]}; min-width: 145px; }}')

    def choose_theme_color(self, key):
        self.stop_theme_preview()
        current = self.current_color_theme()
        color = QColorDialog.getColor(QColor(current[key]), self,
                                      'Farbe auswählen – ' + self.THEME_LABELS[key])
        if not color.isValid():
            return
        current[key] = color.name()
        self.save_app_configuration(color_theme=current)
        self.apply_color_theme()

    def reset_color_theme(self):
        self.stop_theme_preview()
        if QMessageBox.question(self, self.localized_dialog_title('Standardfarben wiederherstellen'),
                                'Das gesamte Farbschema auf die MPW-Standardfarben zurücksetzen?',
                                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                                QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
            return
        self.save_app_configuration(color_theme=dict(self.THEME_DEFAULTS))
        self.apply_color_theme()

