    def refresh_appearance_text_p35(self):
        if not hasattr(self, 'appearance_text_p35'):
            return
        words = self.APPEARANCE_TEXT_P35.get(self.effective_language(), self.APPEARANCE_TEXT_P35['de'])
        for key, widget in self.appearance_text_p35.items():
            if isinstance(widget, QGroupBox):
                widget.setTitle(words[key])
            elif isinstance(widget, QDialog):
                widget.setWindowTitle(words[key])
            else:
                widget.setText(words[key])
        if hasattr(self, 'background_gallery'):
            self.refresh_background_gallery()
        self.update_background_preview()
        if hasattr(self, 'background_scaling_choice'):
            combo = self.background_scaling_choice
            combo.blockSignals(True)
            try:
                for data, key in (('cover', 'scale_cover'), ('contain', 'scale_contain'), ('stretch', 'scale_stretch')):
                    index = combo.findData(data)
                    if index >= 0:
                        combo.setItemText(index, words[key])
            finally:
                combo.blockSignals(False)

    def open_appearance_settings(self):
        """Öffnet die bereits aufgebaute Farb- und Hintergrundverwaltung."""
        dialog = self.appearance_dialog
        dialog.show()
        dialog.raise_()
        dialog.activateWindow()

    def load_background_preference(self):
        path = str(self.app_configuration().get('background_png') or '').strip()
        pixmap = QPixmap(path) if path and Path(path).is_file() else QPixmap()
        BackgroundPage.background_pixmap = pixmap
        try:
            opacity = float(self.app_configuration().get('background_opacity', 0.65))
        except (TypeError, ValueError):
            opacity = 0.65
        BackgroundPage.background_opacity = max(0.0, min(1.0, opacity))
        scaling = self.app_configuration().get('background_scaling', 'cover')
        BackgroundPage.background_scaling = scaling if scaling in ('cover', 'contain', 'stretch') else 'cover'

