    def export_error_log(self):
        path = self.selected_error_log()
        if path is None or not path.is_file():
            return self.message('Fehlerprotokoll', 'Noch keine Fehler protokolliert.')
        target, _ = QFileDialog.getSaveFileName(self, 'Fehlerprotokoll exportieren',
                                               path.name, 'Logdatei (*.log);;Textdatei (*.txt);;Alle Dateien (*)')
        if not target:
            return
        try:
            if Path(target).resolve() == path.resolve():
                return self.message('Fehlerprotokoll', 'Quelldatei und Exportziel sind identisch.')
            shutil.copyfile(path, target)
            self.message('Export abgeschlossen', f'Fehlerprotokoll gespeichert:\n{target}')
        except OSError as exc:
            self.error(exc)

    def run_diagnostics(self):
        """Checks environment, database and paths without writing test files."""
        checks = []
        def add(level, name, details):
            checks.append((level, name, str(details)))
        add('OK', 'Python', f'{platform.python_version()} ({sys.executable})')
        if sys.version_info >= (3, 15):
            add('HINWEIS', 'Python-Kompatibilität',
                'Python 3.15: Bitte prüfen, ob alle installierten Pakete diese Version unterstützen.')
        for package in ('PySide6', 'mutagen'):
            try:
                importlib.import_module(package)
                try:
                    version = importlib.metadata.version(package)
                    detail = f'Import erfolgreich (Version {version})'
                except importlib.metadata.PackageNotFoundError:
                    detail = 'Import erfolgreich (Paketmetadaten im EXE-Build nicht vorhanden)'
                add('OK', package, detail)
            except Exception as exc:
                add('FEHLER', package, f'Import fehlgeschlagen: {exc}')
        if mutagen_file is None:
            add('FEHLER', 'Mutagen-Import', 'Mutagen kann nicht importiert werden.')
        else:
            add('OK', 'Mutagen-Import', 'Audio-Metadatenmodul ist verfügbar.')
        try:
            result = self.con.execute('PRAGMA quick_check').fetchone()
            if result and result[0] == 'ok':
                add('OK', 'SQLite-Datenbank', f'Integrität OK: {DB}')
            else:
                add('FEHLER', 'SQLite-Datenbank', f'Integritätsprüfung: {result}')
        except sqlite3.Error as exc:
            add('FEHLER', 'SQLite-Datenbank', str(exc))
        # Additional non-destructive checks: never repair or rewrite the live DB.
        try:
            violations = self.con.execute('PRAGMA foreign_key_check').fetchmany(11)
            if violations:
                sample = '; '.join(f'{row[0]} / Zeile {row[1]}' for row in violations[:10])
                add('FEHLER', 'SQLite-Fremdschlüssel',
                    f'Mindestens {len(violations)} Verstoß/Verstöße gefunden: {sample}. '
                    'Keine automatische Änderung durchgeführt.')
            else:
                add('OK', 'SQLite-Fremdschlüssel', 'Keine Verstöße gefunden.')
        except sqlite3.Error as exc:
            add('FEHLER', 'SQLite-Fremdschlüssel', f'Prüfung fehlgeschlagen: {exc}')
        try:
            if DB.is_file():
                size = DB.stat().st_size
                add('OK' if size else 'FEHLER', 'Datenbankdatei',
                    f'{DB} – {size:,} Bytes')
            else:
                add('FEHLER', 'Datenbankdatei', f'Nicht gefunden: {DB}')
        except OSError as exc:
            add('FEHLER', 'Datenbankdatei', str(exc))
        try:
            backup_dir = self.backup_directory()
            if backup_dir.is_dir():
                archives = sorted((f for f in backup_dir.glob('*.zip') if f.is_file()),
                                  key=lambda f: f.stat().st_mtime, reverse=True)
                if archives:
                    latest = archives[0]
                    add('OK', 'Backup-Bestand',
                        f'{len(archives)} ZIP-Archiv(e); neuestes: {latest.name}. '
                        'Archivinhalt hier nicht geprüft – dafür „Alle Backups prüfen“ verwenden.')
                else:
                    add('HINWEIS', 'Backup-Bestand', 'Keine ZIP-Backups im gewählten Ordner.')
        except OSError as exc:
            add('HINWEIS', 'Backup-Bestand', f'Archivliste nicht lesbar: {exc}')
        for name, path in [('Datenverzeichnis', ROOT), ('Medienverzeichnis', ROOT / 'media'),
                           ('Backup-Verzeichnis', self.backup_directory())]:
            try:
                if not path.exists():
                    add('FEHLER', name, f'Nicht erreichbar: {path}')
                elif not path.is_dir():
                    add('FEHLER', name, f'Kein Verzeichnis: {path}')
                else:
                    # os.access is only an indication; do not create test files.
                    writable = os.access(path, os.W_OK)
                    add('OK' if writable else 'HINWEIS', name,
                        f'{path} – ' + ('Schreibberechtigung gemeldet' if writable else 'Keine Schreibberechtigung erkennbar'))
            except OSError as exc:
                add('FEHLER', name, f'{path}: {exc}')
        # Read-only disk-space checks; never create files on the selected drive.
        backup_path = self.backup_directory()
        if backup_path.is_dir():
            try:
                free = shutil.disk_usage(backup_path).free
                free_gib = free / (1024 ** 3)
                try:
                    # Estimated uncompressed source size (DB + local media).
                    source_bytes = DB.stat().st_size if DB.is_file() else 0
                    media_root = ROOT / 'media'
                    if media_root.is_dir():
                        for root_dir, _, filenames in os.walk(media_root):
                            for filename in filenames:
                                try:
                                    source_bytes += (Path(root_dir) / filename).stat().st_size
                                except OSError:
                                    pass
                    # Conservative estimate: backup may not compress audio much.
                    needed = source_bytes + 100 * 1024 * 1024
                    source_gib = source_bytes / (1024 ** 3)
                    if free < needed:
                        add('FEHLER', 'Backup-Speicherplatz',
                            f'Nur {free_gib:.2f} GiB frei; Quelldaten ca. {source_gib:.2f} GiB. '
                            'Für ein vollständiges Backup wahrscheinlich zu wenig Platz.')
                    elif free < needed * 2:
                        add('HINWEIS', 'Backup-Speicherplatz',
                            f'{free_gib:.2f} GiB frei; Quelldaten ca. {source_gib:.2f} GiB. '
                            'Speicherreserve ist gering.')
                    else:
                        add('OK', 'Backup-Speicherplatz',
                            f'{free_gib:.2f} GiB frei; Quelldaten ca. {source_gib:.2f} GiB.')
                except OSError as exc:
                    add('HINWEIS', 'Backup-Speicherplatz',
                        f'{free_gib:.2f} GiB frei; Quelldatengröße nicht vollständig ermittelbar: {exc}')
            except OSError as exc:
                add('HINWEIS', 'Backup-Speicherplatz', f'Freier Speicher nicht ermittelbar: {exc}')
        errors = sum(level == 'FEHLER' for level, _, _ in checks)
        warnings = sum(level == 'HINWEIS' for level, _, _ in checks)
        summary = f'{len(checks)} Prüfungen · {errors} Fehler · {warnings} Hinweise'
        self.diagnostic_summary.setText(summary)
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        lines = [f'MPW v{APP_VERSION} – Diagnosebericht – {timestamp}', summary, '']
        lines.extend(f'[{level}] {name}: {detail}' for level, name, detail in checks)
        lines.extend(['', 'Hinweis: Eine erfolgreiche Prüfung ersetzt keinen vollständigen Windows-Funktionstest.'])
        self._diagnostic_report = '\n'.join(lines) + '\n'
        self.diagnostic_output.setPlainText(self._diagnostic_report)

    def export_diagnostics(self):
        if not self._diagnostic_report:
            self.run_diagnostics()
        suggested = str(Path.home() / f'MPW_Diagnose_{datetime.now():%Y%m%d_%H%M%S}.txt')
        target, _ = QFileDialog.getSaveFileName(self, 'Diagnosebericht speichern', suggested, 'Textdateien (*.txt)')
        if not target:
            return
        try:
            Path(target).write_text(self._diagnostic_report, encoding='utf-8-sig')
        except OSError as exc:
            self.error(f'Diagnosebericht konnte nicht gespeichert werden: {exc}')
            return
        self.message('Diagnosebericht gespeichert', target)

    def refresh_all(self):
        bands = self.con.execute('SELECT id,name,genre,second_genre FROM bands ORDER BY name').fetchall()
        # Gemeinsame Auswahlliste aus allen bisher gespeicherten Haupt- und Zweitgenres.
        # Freie Neueingaben bleiben möglich und werden beim Anlegen übernommen.
        # Vorhandene Bandgenres einmalig in den dauerhaften Genre-Katalog übernehmen.
        with self.con:
            self.con.executemany(
                'INSERT OR IGNORE INTO genre_catalog(name) VALUES(?)',
                [(value.strip(),) for _,_,g1,g2 in bands for value in (g1,g2) if value and value.strip()]
            )
        genres = [row[0] for row in self.con.execute('SELECT name FROM genre_catalog ORDER BY name COLLATE NOCASE')]
        self.refresh_genre_index()
        for genre_combo in (self.genre, self.second):
            typed = genre_combo.currentText()
            genre_combo.blockSignals(True)
            genre_combo.clear()
            genre_combo.addItem('')
            genre_combo.addItems(genres)
            genre_combo.setCurrentText(typed)
            genre_combo.blockSignals(False)
        selected_band = self.band_list.currentItem().data(Qt.ItemDataRole.UserRole) if self.band_list.currentItem() else None
        self.band_list.blockSignals(True)
        self.band_list.clear()
        for bid,name,g1,g2 in bands:
            from PySide6.QtWidgets import QListWidgetItem
            item = QListWidgetItem(f'{name}  ·  {g1 or "–"} / {g2 or "–"}')
            item.setData(Qt.ItemDataRole.UserRole,bid)
            self.band_list.addItem(item)
            if bid == selected_band: self.band_list.setCurrentItem(item)
        self.band_list.blockSignals(False)
        self.set_combo(self.project_band,[(r[1],r[0]) for r in bands])
        self.set_combo(self.inst_band,[(r[1],r[0]) for r in bands])
        self.set_combo(self.preset_target_band,[(r[1],r[0]) for r in bands])
        if self.preset_target_band.currentData() is None:
            self.sync_preset_target_band()
        projects = self.con.execute('SELECT p.id,b.name || " / " || p.name FROM projects p JOIN bands b ON b.id=p.band_id ORDER BY b.name,p.name').fetchall()
        selected_filter_band = self.project_filter_band.currentData()
        self.project_filter_band.blockSignals(True)
        self.project_filter_band.clear()
        self.project_filter_band.addItem(self.PROJECT_DISPLAY_HF5[self.effective_language()][1], None)
        for bid, band_name, _, _ in bands:
            self.project_filter_band.addItem(band_name, bid)
        filter_idx = self.project_filter_band.findData(selected_filter_band)
        self.project_filter_band.setCurrentIndex(max(0, filter_idx))
        self.project_filter_band.blockSignals(False)
        self.refresh_project_index()
        self.set_combo(self.song_project,[(name,idx) for idx,name in projects])
        songs = self.con.execute(
            'SELECT s.id, b.name, p.name, s.title FROM songs s '
            'JOIN projects p ON p.id=s.project_id '
            'JOIN bands b ON b.id=p.band_id ORDER BY s.id DESC'
        ).fetchall()
        song_choices = [
            (self.song_choice_label(band, project, title), song_id)
            for song_id, band, project, title in songs
        ]
        # Songs & Suno besitzt eine eigene zweistufige Auswahl.
        selected_song = self.song_select.currentData()
        selected_band = self.song_band_filter.currentData()
        self._song_band_choices = {}
        for song_id, band, project, title in songs:
            bid = next((row[0] for row in bands if row[1] == band), None)
            if bid is not None:
                self._song_band_choices.setdefault(bid, []).append(
                    (self.song_choice_label(band, project, title), song_id, project, title))
        self.song_band_filter.blockSignals(True)
        self.song_band_filter.clear()
        self.song_band_filter.addItem(self.SUNO_TEXT_HF7[self.effective_language()]['all_bands'], None)
        for bid, name, _, _ in bands:
            self.song_band_filter.addItem(name, bid)
        band_idx = self.song_band_filter.findData(selected_band)
        self.song_band_filter.setCurrentIndex(max(0, band_idx))
        self.song_band_filter.blockSignals(False)
        self.refresh_song_band_choices(preferred_song_id=selected_song)
        for combo in [self.media_song, self.release_song]:
            self.set_combo(combo, song_choices)
        self.set_combo(self.ai_band, [(name, bid) for bid, name, _, _ in bands])
        self.refresh_ai_project_choices()
        selected_preset = self.ai_hardware_preset.currentData()
        self.ai_hardware_preset.blockSignals(True)
        self.ai_hardware_preset.clear()
        self.ai_hardware_preset.addItem('Bandprofil-Hardware verwenden', None)
        for preset_id, name in self.con.execute('SELECT id,name FROM hardware_presets ORDER BY name COLLATE NOCASE'):
            self.ai_hardware_preset.addItem(name, preset_id)
        for index in range(self.ai_hardware_preset.count()):
            if self.ai_hardware_preset.itemData(index) == selected_preset:
                self.ai_hardware_preset.setCurrentIndex(index)
                break
        self.ai_hardware_preset.blockSignals(False)
        self.refresh_instruments(); self.refresh_media(); self.refresh_releases(); self.refresh_ai_versions(); self.refresh_albums()

    def refresh_song_band_choices(self, *args, preferred_song_id=None):
        """Filtert ausschließlich die sichtbare Songauswahl; keine Datenbankänderung."""
        if not hasattr(self, '_song_band_choices'):
            return
        previous = self.song_select.currentData() if preferred_song_id is None else preferred_song_id
        band_id = self.song_band_filter.currentData()
        query = self.song_quick_search.text().strip().casefold()
        choices = []
        for bid, entries in self._song_band_choices.items():
            if band_id is None or bid == band_id:
                for label, sid, project, title in entries:
                    # Bei ausgewählter Band nur Songtitel zeigen; Projekt bei Abweichung ergänzen.
                    display = (title if project.strip().casefold() == title.strip().casefold()
                               else f'{project} / {title}') if band_id is not None else label
                    if not query or query in title.casefold() or query in project.casefold() or query in label.casefold():
                        choices.append((display, sid))
        choices.sort(key=lambda item: (item[0].casefold(), item[1]))
        self.song_result_count.setText(self.SUNO_TEXT_HF7[self.effective_language()]['count'].format(n=len(choices), suffix='' if len(choices) == 1 else 's'))
        self.song_result_count.setToolTip('Keine Treffer: Band oder Suchbegriff ändern.' if not choices else
                                          f'{len(choices)} passende Songs gefunden.')
        self.song_select.blockSignals(True)
        self.song_select.clear()
        self.song_select.addItem(self.SUNO_TEXT_HF7[self.effective_language()]['select'], None)
        for label, sid in choices:
            self.song_select.addItem(label, sid)
        # Innerhalb der Filterroutine niemals automatisch den Bandfilter ändern.
        idx = self.song_select.findData(previous) if previous is not None else -1
        self.song_select.setCurrentIndex(max(0, idx))
        self.song_select.blockSignals(False)
        self.load_song()

    def reset_song_filters(self):
        """Setzt nur die sichtbaren Suchfilter zurück, niemals Songdaten."""
        self.song_band_filter.blockSignals(True)
        self.song_band_filter.setCurrentIndex(0)
        self.song_band_filter.blockSignals(False)
        self.song_quick_search.blockSignals(True)
        self.song_quick_search.clear()
        self.song_quick_search.blockSignals(False)
        self.refresh_song_band_choices()

    def find_song_in_suno(self, song_id):
        """Erlaubt Navigation aus anderen Reitern trotz aktivem Bandfilter."""
        idx = self.song_select.findData(song_id)
        if idx < 0 and song_id is not None:
            # Externe Navigation darf bestehende Suchfilter aufheben.
            if self.song_quick_search.text():
                self.song_quick_search.clear()
                idx = self.song_select.findData(song_id)
            if idx < 0:
                self.song_band_filter.setCurrentIndex(0)  # Alle Bands für externe Navigation
                idx = self.song_select.findData(song_id)
        return idx

    def set_combo(self, cb, entries):
        old = cb.currentData(); cb.blockSignals(True); cb.clear()
        for label,idx in entries: cb.addItem(label,idx)
        index = cb.findData(old)
        if index >= 0: cb.setCurrentIndex(index)
        cb.blockSignals(False)

    def add_genre(self):
        value = self.genre_new.text().strip()
        if not value:
            return self.error(self.genre_dialog_text('add_empty'))
        with self.con:
            self.con.execute('INSERT OR IGNORE INTO genre_catalog(name) VALUES(?)', (value,))
        self.genre_new.clear()
        self.refresh_all()
        self.message('Genre-Katalog', self.genre_dialog_text('added', name=value))

    def load_band(self, current, previous=None):
        if current is None: return
        bid = current.data(Qt.ItemDataRole.UserRole)
        row = self.con.execute('SELECT name,genre,second_genre,persona FROM bands WHERE id=?',(bid,)).fetchone()
        if not row: return
        name,g1,g2,persona = row
        self.band_name.setText(name)
        self.genre.setCurrentText(g1 or '')
        self.second.setCurrentText(g2 or '')
        index = self.persona.findText(persona or '')
        if index >= 0: self.persona.setCurrentIndex(index)

    def update_band(self):
        item = self.band_list.currentItem()
        if item is None: return self.error('Bitte zuerst ein Bandprofil aus der Liste auswählen.')
        bid = item.data(Qt.ItemDataRole.UserRole)
        name = self.band_name.text().strip()
        if not name: return self.error('Bandname darf nicht leer sein.')
        try:
            with self.con:
                self.con.execute('UPDATE bands SET name=?,genre=?,second_genre=?,persona=? WHERE id=?',
                    (name,self.genre.currentText().strip(),self.second.currentText().strip(),self.persona.currentText(),bid))
            self.refresh_all()
            self.message('Bandprofil gespeichert','Das vorhandene Bandprofil wurde aktualisiert.')
        except sqlite3.IntegrityError:
            self.error('Dieser Bandname wird bereits verwendet.')

    def refresh_project_index(self, *_):
        """Sort project index without modifying any database records."""
        order = [
            'b.name COLLATE NOCASE, p.name COLLATE NOCASE',
            'p.name COLLATE NOCASE, b.name COLLATE NOCASE',
            'p.name COLLATE NOCASE DESC, b.name COLLATE NOCASE',
            'p.id DESC',
        ][self.project_sort.currentIndex() if self.project_sort.currentIndex() >= 0 else 0]
        rows = self.con.execute(
            'SELECT p.id, p.band_id, b.name, p.name, p.status FROM projects p '
            'JOIN bands b ON b.id=p.band_id ORDER BY ' + order
        ).fetchall()
        selected = (self.project_list.currentItem().data(Qt.ItemDataRole.UserRole)
                    if self.project_list.currentItem() else None)
        self.project_list.blockSignals(True)
        try:
            self.project_list.clear()
            for pid, bid, band_name, project_name, status in rows:
                status_labels = self.PROJECT_DISPLAY_HF5[self.effective_language()][4]
                display_status = (status_labels[self.PROJECT_STATUS_KEYS.index(status)]
                                  if status in self.PROJECT_STATUS_KEYS else status)
                item = QListWidgetItem(f'{band_name} / {project_name}  ·  [{display_status}]')
                item.setData(Qt.ItemDataRole.UserRole, pid)
                item.setData(Qt.ItemDataRole.UserRole + 1, bid)
                item.setData(Qt.ItemDataRole.UserRole + 2, status)
                self.project_list.addItem(item)
                if pid == selected:
                    self.project_list.setCurrentItem(item)
        finally:
            self.project_list.blockSignals(False)
        self.filter_projects()

    def filter_projects(self, *_):
        query = self.project_search.text().strip().casefold()
        band_id = self.project_filter_band.currentData()
        status_index = self.project_filter_status.currentIndex()
        status_filter = (None if status_index <= 0 else self.PROJECT_STATUS_KEYS[status_index - 1])
        visible = 0
        for i in range(self.project_list.count()):
            item = self.project_list.item(i)
            match = (query in item.text().casefold() and
                     (band_id is None or item.data(Qt.ItemDataRole.UserRole + 1) == band_id) and
                     (status_filter is None or item.data(Qt.ItemDataRole.UserRole + 2) == status_filter))
            item.setHidden(not match)
            visible += bool(match)
        total = self.project_list.count()
        words = self.PROJECT_DISPLAY_HF5[self.effective_language()]
        self.project_count.setText(words[6].format(visible=visible, total=total) if visible != total
                                   else f'{total} {words[5]}')

    def load_project(self, current, previous=None):
        if current is None: return
        pid = current.data(Qt.ItemDataRole.UserRole)
        row = self.con.execute('SELECT band_id,name FROM projects WHERE id=?',(pid,)).fetchone()
        if not row: return
        bid,name = row
        idx = self.project_band.findData(bid)
        if idx >= 0: self.project_band.setCurrentIndex(idx)
        self.project_name.setText(name)

    def update_project(self):
        """Keep database and project directory in sync on rename/band change."""
        item = self.project_list.currentItem()
        if item is None:
            return self.error('Bitte zuerst ein Projekt aus der Liste auswählen.')
        pid = item.data(Qt.ItemDataRole.UserRole)
        name = self.project_name.text().strip()
        bid = self.project_band.currentData()
        if not name or bid is None:
            return self.error('Band und Projektname erforderlich.')
        try:
            self.validate_folder_name(name)
        except ValueError as exc:
            return self.error(str(exc))
        old = self.con.execute('SELECT p.band_id,p.name,b.name FROM projects p '
                               'JOIN bands b ON b.id=p.band_id WHERE p.id=?', (pid,)).fetchone()
        target_band = self.con.execute('SELECT name FROM bands WHERE id=?', (bid,)).fetchone()
        if old is None or target_band is None:
            return self.error('Projekt oder Zielband existiert nicht mehr.')
        old_bid, old_name, old_band_name = old
        if self.con.execute('SELECT 1 FROM projects WHERE band_id=? AND name=? COLLATE NOCASE '
                            'AND id<>?', (bid, name, pid)).fetchone():
            return self.error('Dieses Projekt existiert bereits für die ausgewählte Band.')
        if old_bid == bid and old_name == name:
            return self.message('Keine Änderungen', 'Das Projekt ist bereits aktuell.')
        try:
            root = self.band_root_directory()
            old_band_folder = self.existing_named_folder(root, old_band_name)
            new_band_folder = self.existing_named_folder(root, target_band[0])
            if old_band_folder is None or new_band_folder is None:
                return self.error('Quell- oder Ziel-Bandordner fehlt. Keine Änderung vorgenommen.')
            source = self.existing_named_folder(old_band_folder, old_name)
            if source is None or source.is_symlink():
                return self.error('Projektordner fehlt oder ist eine Verknüpfung. Keine Änderung vorgenommen.')
            destination = new_band_folder / name
            # Case-only rename on Windows is supported via the same existing directory.
            existing = self.existing_named_folder(new_band_folder, name)
            if existing is not None and existing != source:
                return self.error('Im Zielordner ist bereits ein Projekt mit diesem Namen vorhanden. '
                                  'Es wird nichts überschrieben.')
            if destination.exists() and destination != source and existing is None:
                return self.error('Der Zielpfad ist bereits belegt. Keine Änderung vorgenommen.')
        except (OSError, ValueError) as exc:
            return self.error(f'Projektpfad konnte nicht geprüft werden: {exc}')
        answer = QMessageBox.question(
            self, self.localized_dialog_title('Projektänderung bestätigen'),
            f'Projekt „{old_name}“ ändern zu „{name}“?\n\n'
            f'Bisher: {source}\nNeu: {destination}\n\n'
            'Der Projektordner wird entsprechend umbenannt bzw. verschoben. '
            'Vorhandene Dateien bleiben erhalten. Fortfahren?',
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if answer != QMessageBox.StandardButton.Yes:
            return
        moved = False
        try:
            if source != destination:
                # Path.rename does not copy/merge folders. Destination was checked above.
                source.rename(destination)
                moved = True
            with self.con:
                self.con.execute('UPDATE projects SET band_id=?,name=? WHERE id=?', (bid, name, pid))
        except (OSError, sqlite3.Error) as exc:
            rollback_error = ''
            if moved:
                try:
                    destination.rename(source)
                except OSError as rollback_exc:
                    rollback_error = f'\nACHTUNG: Rückverschiebung fehlgeschlagen: {rollback_exc}'
            return self.error(f'Projektänderung fehlgeschlagen: {exc}{rollback_error}')
        self.refresh_all()
        self.message('Projekt gespeichert', 'Datenbank und Projektordner wurden aktualisiert.')

    def show_band_context_menu(self, position):
        """Offer Explorer access for the band under the configured storage root."""
        item = self.band_list.itemAt(position)
        if item is None:
            return
        menu = QMenu(self.band_list)
        band_id = item.data(Qt.ItemDataRole.UserRole)
        open_action = menu.addAction(self.translated_context_label('Im Explorer öffnen'))
        menu.addSeparator()
        delete_action = menu.addAction(self.translated_context_label('Band löschen …'))
        chosen = menu.exec(self.band_list.viewport().mapToGlobal(position))
        if chosen == open_action:
            self.open_band_in_explorer(band_id)
        elif chosen == delete_action:
            self.delete_band(band_id)

    def show_project_context_menu(self, position):
        item = self.project_list.itemAt(position)
        if item is None:
            return
        menu = QMenu(self.project_list)
        open_action = menu.addAction(self.translated_context_label('Im Explorer öffnen'))
        copy_path_action = menu.addAction(self.translated_context_label('Projektpfad kopieren'))
        menu.addSeparator()
        rename_action = menu.addAction(self.translated_context_label('Projekt umbenennen …'))
        status_menu = menu.addMenu(self.translated_project_context_status('Projektstatus setzen'))
        status_actions = {status_menu.addAction(self.translated_project_context_status(status)): status for status in
                          ('Geplant', 'In Arbeit', 'Fertiggestellt', 'Veröffentlicht', 'Pausiert')}
        menu.addSeparator()
        repair_action = menu.addAction(self.translated_context_label('Fehlende Projekt-Unterordner ergänzen'))
        menu.addSeparator()
        db_delete_action = menu.addAction(self.translated_context_label('Projekt nur aus Datenbank löschen …'))
        full_delete_action = menu.addAction(self.translated_context_label('Projekt mit Ordner und Dateien löschen …'))
        selected = menu.exec(self.project_list.viewport().mapToGlobal(position))
        project_id = item.data(Qt.ItemDataRole.UserRole)
        if selected == open_action:
            self.open_project_in_explorer(project_id)
        elif selected == copy_path_action:
            self.copy_project_path(project_id)
        elif selected == rename_action:
            self.rename_project_from_context(project_id)
        elif selected in status_actions:
            self.set_project_status(project_id, status_actions[selected])
        elif selected == repair_action:
            self.repair_project_subfolders(project_id)
        elif selected == db_delete_action:
            self.delete_project(project_id, delete_files=False)
        elif selected == full_delete_action:
            self.delete_project(project_id, delete_files=True)

    def set_project_status(self, project_id, status):
        """Update a project's workflow status without touching files or song statuses."""
        valid = ('Geplant', 'In Arbeit', 'Fertiggestellt', 'Veröffentlicht', 'Pausiert')
        if status not in valid:
            return self.error('Ungültiger Projektstatus.')
        row = self.con.execute('SELECT status FROM projects WHERE id=?', (project_id,)).fetchone()
        if not row:
            return self.error('Projekt nicht gefunden.')
        if row[0] == status:
            return
        with self.con:
            self.con.execute('UPDATE projects SET status=? WHERE id=?', (status, project_id))
        self.refresh_project_index()

    def rename_project_from_context(self, project_id):
        """Rename an existing project and its directory using the safe update workflow."""
        row = self.con.execute(
            'SELECT p.name,p.band_id,b.name FROM projects p '
            'JOIN bands b ON b.id=p.band_id WHERE p.id=?', (project_id,)
        ).fetchone()
        if row is None:
            return self.error('Das ausgewählte Projekt existiert nicht mehr.')
        old_name, band_id, band_name = row
        new_name, accepted = QInputDialog.getText(
            self, self.project_band_dialog_text('rename_title'),
            self.project_band_dialog_text('rename_prompt', project=old_name, band=band_name),
            QLineEdit.EchoMode.Normal, old_name)
        if not accepted:
            return
        new_name = new_name.strip()
        if new_name == old_name:
            return
        try:
            self.validate_folder_name(new_name)
        except ValueError as exc:
            return self.error(str(exc))
        # The update method uses the current list item and form fields.
        # Explicitly select the right-clicked project and retain its band.
        for index in range(self.project_list.count()):
            candidate = self.project_list.item(index)
            if candidate.data(Qt.ItemDataRole.UserRole) == project_id:
                self.project_list.setCurrentItem(candidate)
                break
        else:
            return self.error('Projekt ist in der Übersicht nicht mehr vorhanden.')
        band_index = self.project_band.findData(band_id)
        if band_index < 0:
            return self.error('Die zugehörige Band ist nicht mehr auswählbar.')
        self.project_band.setCurrentIndex(band_index)
        self.project_name.setText(new_name)
        self.update_project()  # Includes collision check, confirmation and rollback.
        # A rejected/failed rename must not leave an unsaved name in the form.
        current = self.con.execute('SELECT name FROM projects WHERE id=?', (project_id,)).fetchone()
        if current is not None:
            self.project_name.setText(current[0])

    def delete_project(self, project_id, delete_files=False):
        """Delete project dependencies transactionally; optionally delete its disk tree."""
        row = self.con.execute(
            'SELECT p.name,b.name FROM projects p JOIN bands b ON b.id=p.band_id '
            'WHERE p.id=?', (project_id,)).fetchone()
        if row is None:
            return self.error('Dieses Projekt existiert nicht mehr in der Datenbank.')
        project_name, band_name = row
        song_count = self.con.execute(
            'SELECT COUNT(*) FROM songs WHERE project_id=?', (project_id,)).fetchone()[0]
        folder = None
        if delete_files:
            try:
                base = self.band_root_directory()
                band_folder = self.existing_named_folder(base, band_name)
                if band_folder is None or band_folder.is_symlink():
                    return self.error('Bandordner fehlt oder ist eine Verknüpfung. Abbruch.')
                folder = self.existing_named_folder(band_folder, project_name)
                if folder is None or not folder.is_dir() or folder.is_symlink():
                    return self.error('Projektordner fehlt oder ist eine Verknüpfung. Abbruch.')
                if folder.parent.resolve() != band_folder.resolve():
                    return self.error('Projektordner liegt außerhalb des Bandordners. Abbruch.')
            except (OSError, ValueError) as exc:
                return self.error(f'Projektordner konnte nicht geprüft werden: {exc}')
        warning = self.deletion_warning_text(
            'project', band=band_name, project=project_name, songs=song_count)
        if delete_files:
            warning += self.deletion_warning_text('project_files', folder=folder)
        else:
            warning += self.deletion_warning_text('project_db')
        warning += self.deletion_warning_text('continue')
        answer = QMessageBox.warning(
            self, self.localized_dialog_title('Projekt löschen – Sicherheitsabfrage'), warning,
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if answer != QMessageBox.StandardButton.Yes:
            return
        typed, ok = QInputDialog.getText(
            self, self.project_band_dialog_text('delete_project_title'),
            self.project_band_dialog_text('delete_project_prompt', project=project_name))
        if not ok:
            return
        if typed != project_name:
            return self.error('Projektname stimmt nicht überein. Nichts gelöscht.')
        # Move to a unique sibling first, so database failures can restore the original.
        staged = None
        if delete_files:
            import uuid
            staged = folder.parent / ('.mpw_delete_' + uuid.uuid4().hex)
            try:
                folder.rename(staged)
            except OSError as exc:
                return self.error(f'Projektordner konnte nicht gesichert werden: {exc}')
        try:
            with self.con:
                self.con.execute(
                    'DELETE FROM album_tracks WHERE song_id IN '
                    '(SELECT id FROM songs WHERE project_id=?)', (project_id,))
                self.con.execute(
                    'DELETE FROM release_platforms WHERE release_id IN '
                    '(SELECT r.id FROM releases r JOIN songs s ON s.id=r.song_id '
                    'WHERE s.project_id=?)', (project_id,))
                for table in ('releases', 'media_links', 'media_assets', 'prompt_versions'):
                    self.con.execute(
                        f'DELETE FROM {table} WHERE song_id IN '
                        '(SELECT id FROM songs WHERE project_id=?)', (project_id,))
                self.con.execute('DELETE FROM songs WHERE project_id=?', (project_id,))
                self.con.execute('DELETE FROM projects WHERE id=?', (project_id,))
        except sqlite3.Error as exc:
            rollback = ''
            if staged is not None:
                try:
                    staged.rename(folder)
                except OSError as restore_exc:
                    rollback = f'\nOrdner-Rückverschiebung fehlgeschlagen: {restore_exc}\nOrt: {staged}'
            return self.error(f'Datenbanklöschung fehlgeschlagen: {exc}{rollback}')
        self.project_name.clear()
        self.refresh_all()
        if staged is not None:
            try:
                shutil.rmtree(staged)
            except OSError as exc:
                return self.error(
                    'Projekt aus der Datenbank gelöscht, aber die endgültige '
                    f'Dateilöschung ist fehlgeschlagen: {exc}\n'
                    f'Verbleibender Ordner: {staged}\n'
                    'Bitte diesen Ordner manuell überprüfen.')
            self.message('Projekt vollständig gelöscht',
                         f'„{project_name}“ wurde aus der Datenbank entfernt. '
                         'Der Projektordner einschließlich seiner Dateien wurde gelöscht.')
        else:
            self.message('Projekt aus Datenbank gelöscht',
                         f'„{project_name}“ wurde aus der Datenbank entfernt. '
                         'Der Projektordner und alle Dateien bleiben erhalten.')

    def copy_project_path(self, project_id):
        """Copy the existing project's absolute folder path without changing files."""
        row = self.con.execute('SELECT p.name,b.name FROM projects p '
                               'JOIN bands b ON b.id=p.band_id WHERE p.id=?',
                               (project_id,)).fetchone()
        if row is None:
            return self.error('Das ausgewählte Projekt ist nicht mehr vorhanden.')
        project_name, band_name = row
        try:
            band_folder = self.existing_named_folder(self.band_root_directory(), band_name)
            if band_folder is None:
                return self.error('Bandordner nicht gefunden. Es wurde nichts kopiert.')
            project_folder = self.existing_named_folder(band_folder, project_name)
            if project_folder is None:
                return self.error('Projektordner nicht gefunden. Es wurde nichts kopiert.')
            QApplication.clipboard().setText(str(project_folder.resolve()))
            QMessageBox.information(self, 'Projektpfad kopiert',
                                    f'Der Projektpfad wurde in die Zwischenablage kopiert:\n{project_folder.resolve()}')
        except (OSError, ValueError) as exc:
            self.error(f'Projektpfad konnte nicht kopiert werden:\n{exc}')

    def open_project_in_explorer(self, project_id):
        """Open only an existing project directory; never create or alter it."""
        row = self.con.execute('SELECT p.name,b.name FROM projects p '
                               'JOIN bands b ON b.id=p.band_id WHERE p.id=?',
                               (project_id,)).fetchone()
        if row is None:
            return self.error('Das ausgewählte Projekt ist nicht mehr vorhanden.')
        project_name, band_name = row
        try:
            band_folder = self.existing_named_folder(self.band_root_directory(), band_name)
            if band_folder is None:
                return self.error('Bandordner nicht gefunden. Es wurde nichts angelegt.')
            project_folder = self.existing_named_folder(band_folder, project_name)
            if project_folder is None:
                return self.error('Projektordner nicht gefunden. Es wurde nichts angelegt.')
            if sys.platform == 'win32':
                os.startfile(str(project_folder))
            elif not QDesktopServices.openUrl(QUrl.fromLocalFile(str(project_folder))):
                self.error(f'Der Dateimanager konnte nicht geöffnet werden:\n{project_folder}')
        except (OSError, ValueError) as exc:
            self.error(f'Projektordner konnte nicht geöffnet werden:\n{exc}')

    def repair_project_subfolders(self, project_id):
        """Add only missing song folders; never touch existing media."""
        song_ids = [r[0] for r in self.con.execute('SELECT id FROM songs WHERE project_id=?', (project_id,))]
        try:
            for sid in song_ids:
                self.ensure_song_media_folders(sid)
            self.message('Projektordner geprüft', f'{len(song_ids)} Song(s) geprüft; fehlende Ordner ergänzt. Keine Dateien gelöscht.')
        except (OSError, ValueError) as exc:
            self.error(f'Projektordner konnten nicht ergänzt werden: {exc}')

    def repair_all_project_subfolders(self):
        """Fill missing standard folders for every registered project, without overwriting files."""
        rows = self.con.execute(
            'SELECT p.id,p.name,b.name FROM projects p '
            'JOIN bands b ON b.id=p.band_id ORDER BY b.name COLLATE NOCASE,p.name COLLATE NOCASE'
        ).fetchall()
        if not rows:
            return self.message('Projekt-Unterordner', 'Keine Song/Projekte in der Datenbank vorhanden.')
        answer = QMessageBox.question(
            self, self.localized_dialog_title('Projekt-Unterordner ergänzen'),
            self.dynamic_confirmation_text('repair_project_folders', count=len(rows)),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if answer != QMessageBox.StandardButton.Yes:
            return
        created = 0
        complete = 0
        skipped = []
        errors = []
        root = self.band_root_directory()
        for _pid, project_name, band_name in rows:
            label = f'{band_name} / {project_name}'
            try:
                band_folder = self.existing_named_folder(root, band_name)
                if band_folder is None or band_folder.is_symlink():
                    skipped.append(label + ' (Bandordner fehlt oder ist ein Link)')
                    continue
                project_folder = self.existing_named_folder(band_folder, project_name)
                if project_folder is None or project_folder.is_symlink():
                    skipped.append(label + ' (Projektordner fehlt oder ist ein Link)')
                    continue
                before = {entry.name.casefold(): entry for entry in project_folder.iterdir()}
                # Check all conflicts before creating anything in this project.
                blocked = [name for name in self.configured_project_folders()
                           if name.casefold() in before and not before[name.casefold()].is_dir()]
                if blocked:
                    errors.append(label + ': Name durch Datei belegt: ' + ', '.join(blocked))
                    continue
                missing = [name for name in self.configured_project_folders()
                           if name.casefold() not in before]
                for folder_name in missing:
                    (project_folder / folder_name).mkdir(exist_ok=True)
                created += len(missing)
                if not missing:
                    complete += 1
            except (OSError, ValueError) as exc:
                errors.append(f'{label}: {exc}')
        report = (f'Geprüfte Datenbankprojekte: {len(rows)}\n'
                  f'Neu angelegte Unterordner: {created}\n'
                  f'Bereits vollständig: {complete}\n'
                  f'Übersprungene Song/Projekte: {len(skipped)}\n'
                  f'Fehler: {len(errors)}')
        if skipped or errors:
            details = '\n'.join((skipped + errors)[:12])
            report += '\n\nDetails:\n' + details
            if len(skipped) + len(errors) > 12:
                report += f'\n… und {len(skipped) + len(errors) - 12} weitere.'
        self.message('Projekt-Unterordner – Ergebnis', report)

    def delete_band(self, band_id):
        """Delete a band and its linked database records, never its disk folders."""
        row = self.con.execute('SELECT name FROM bands WHERE id=?', (band_id,)).fetchone()
        if row is None:
            return self.error('Das ausgewählte Bandprofil ist nicht mehr vorhanden.')
        name = row[0]
        project_ids = [r[0] for r in self.con.execute(
            'SELECT id FROM projects WHERE band_id=?', (band_id,))]
        song_ids = [r[0] for r in self.con.execute(
            'SELECT s.id FROM songs s JOIN projects p ON p.id=s.project_id WHERE p.band_id=?',
            (band_id,))]
        answer = QMessageBox.warning(
            self, self.localized_dialog_title('Band löschen – Sicherheitsabfrage'),
            self.deletion_warning_text('band', band=name,
                                       projects=len(project_ids), songs=len(song_ids)),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if answer != QMessageBox.StandardButton.Yes:
            return
        typed, ok = QInputDialog.getText(
            self, self.project_band_dialog_text('delete_band_title'),
            self.project_band_dialog_text('delete_band_prompt', band=name))
        if not ok or typed != name:
            if ok:
                self.error('Bandname stimmt nicht überein. Die Band wurde nicht gelöscht.')
            return
        try:
            with self.con:
                # Explicitly remove dependent records because older MPW tables
                # do not have ON DELETE CASCADE on projects and songs.
                self.con.execute('DELETE FROM album_tracks WHERE song_id IN '
                                 '(SELECT s.id FROM songs s JOIN projects p ON p.id=s.project_id '
                                 'WHERE p.band_id=?)', (band_id,))
                for table in ('release_platforms',):
                    self.con.execute(f'DELETE FROM {table} WHERE release_id IN '
                                     '(SELECT r.id FROM releases r JOIN songs s ON s.id=r.song_id '
                                     'JOIN projects p ON p.id=s.project_id WHERE p.band_id=?)',
                                     (band_id,))
                for table in ('releases', 'media_links', 'media_assets', 'prompt_versions'):
                    self.con.execute(f'DELETE FROM {table} WHERE song_id IN '
                                     '(SELECT s.id FROM songs s JOIN projects p ON p.id=s.project_id '
                                     'WHERE p.band_id=?)', (band_id,))
                self.con.execute('DELETE FROM songs WHERE project_id IN '
                                 '(SELECT id FROM projects WHERE band_id=?)', (band_id,))
                self.con.execute('DELETE FROM projects WHERE band_id=?', (band_id,))
                self.con.execute('DELETE FROM instruments WHERE band_id=?', (band_id,))
                self.con.execute('DELETE FROM bands WHERE id=?', (band_id,))
            self.band_name.clear()
            self.refresh_all()
            self.message('Band gelöscht',
                         f'Die Band „{name}“ wurde aus der Datenbank gelöscht.\n'
                         'Alle Verzeichnisse und Dateien auf dem Datenträger bleiben erhalten.')
        except sqlite3.Error as exc:
            self.error(f'Band konnte nicht gelöscht werden. Keine Teil-Löschung vorgenommen:\n{exc}')

    def open_band_in_explorer(self, band_id):
        """Open an existing band directory without creating or modifying it."""
        row = self.con.execute('SELECT name FROM bands WHERE id=?', (band_id,)).fetchone()
        if row is None:
            return self.error('Das ausgewählte Bandprofil ist nicht mehr vorhanden.')
        name = row[0]
        base = Path(self.app_configuration().get('band_root_directory') or (ROOT / 'Bands'))
        if not base.is_dir():
            return self.error(f'Der konfigurierte Band-Speicherort ist nicht erreichbar:\n{base}')
        try:
            matches = [entry for entry in base.iterdir()
                       if entry.name.casefold() == name.casefold()]
            target = next((entry for entry in matches if entry.is_dir()), None)
            if target is None:
                return self.error(f'Band-Verzeichnis nicht gefunden:\n{base / name}')
            if sys.platform == 'win32':
                os.startfile(str(target))
            elif not QDesktopServices.openUrl(QUrl.fromLocalFile(str(target))):
                return self.error(f'Der Dateimanager konnte nicht geöffnet werden:\n{target}')
        except OSError as exc:
            self.error(f'Band-Verzeichnis konnte nicht geöffnet werden:\n{exc}')

    STANDARD_PROJECT_FOLDERS = ('Bilder', 'Dokumente', 'Musik', 'OLD', 'Video')

    validate_folder_name = staticmethod(mpw_core.validate_folder_name)

    def band_root_directory(self):
        return Path(self.app_configuration().get('band_root_directory') or (ROOT / 'Bands'))

    existing_named_folder = staticmethod(mpw_core.existing_named_folder)

    # Fester Bandordner, unabhängig von der editierbaren Song/Projekt-Vorlage.
    BAND_PROMPT_FOLDER = mpw_core.BAND_PROMPT_FOLDER

    def band_prompt_directory(self, band_name):
        """Find the existing band safely and add only the fixed prompt folder."""
        return mpw_core.band_prompt_directory(band_name, self.band_root_directory())

    def open_ai_prompt_archive(self):
        """Open the selected band's existing prompt archive without changing files."""
        bid = self.ai_band.currentData()
        if bid is None:
            return self.error('Bitte zuerst eine Band auswählen.')
        row = self.con.execute('SELECT name FROM bands WHERE id=?', (bid,)).fetchone()
        if row is None:
            return self.error('Die ausgewählte Band wurde nicht gefunden.')
        try:
            band_folder = self.existing_named_folder(self.band_root_directory(), row[0])
            if band_folder is None or band_folder.is_symlink():
                return self.error('Bandordner nicht vorhanden. Es wurden keine Ordner angelegt.')
            archive = self.existing_named_folder(band_folder, self.BAND_PROMPT_FOLDER)
            if archive is None or archive.is_symlink():
                return self.error('Noch kein Song-Prompts-Archiv vorhanden. Es wird beim nächsten Speichern einer Prompt-Version angelegt.')
            if not QDesktopServices.openUrl(QUrl.fromLocalFile(str(archive.resolve()))):
                return self.error(f'Der Ordner konnte nicht geöffnet werden: {archive}')
        except OSError as exc:
            return self.error(f'Prompt-Archiv konnte nicht geöffnet werden: {exc}')

    def save_ai_prompt_text_file(self, sid, version_id, style, lyrics):
        """Archive a saved AI version without replacing existing files."""
        return mpw_core.save_prompt_text_file(self.con, sid, version_id, style, lyrics, self.band_root_directory())

    DEFAULT_PROJECT_FOLDERS = ('Cover', 'Audio', 'Dokumente', 'Video', 'OLD')

    def configured_project_folders(self):
        """Read the template for future project folders; never alter existing folders."""
        configured = self.app_configuration().get('project_folder_template')
        if not isinstance(configured, list) or not 1 <= len(configured) <= 10:
            return self.DEFAULT_PROJECT_FOLDERS
        try:
            names = [str(name).strip() for name in configured]
            for name in names:
                self.validate_folder_name(name)
            if len({name.casefold() for name in names}) != len(names):
                raise ValueError('Doppelte Namen')
        except (ValueError, TypeError):
            return self.DEFAULT_PROJECT_FOLDERS
        # The first four folders are fixed; legacy names become optional extras.
        extras = [n for n in names if n.casefold() not in {v.casefold() for v in SONG_MEDIA_FOLDERS}]
        return tuple(SONG_MEDIA_FOLDERS) + tuple(extras[:6])

    def create_project_cover_icons(self):
        """Bulk-install missing Explorer icons without touching existing customizations."""
        if os.name != 'nt':
            return self.message('Ordnersymbole', 'Diese Funktion ist nur unter Windows verfügbar.')
        if QMessageBox.question(self, self.localized_dialog_title('Projekt-Cover als Ordnersymbol'),
            'Für alle Projektordner mit Cover ein Windows-Ordnersymbol erstellen?\n'
            'Vorhandene desktop.ini-Dateien und Symbole werden nicht verändert.\n'
            'Es werden keine Mediendateien gelöscht oder verschoben.',
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
            return
        created, skipped, failures = 0, 0, []
        rows = self.con.execute('SELECT p.name,b.name FROM projects p '
                                'JOIN bands b ON b.id=p.band_id ORDER BY b.name,p.name').fetchall()
        root = self.band_root_directory()
        for project_name, band_name in rows:
            try:
                parent = root
                for name in (band_name, project_name):
                    if not parent.is_dir(): raise OSError('Band-/Projektordner fehlt')
                    matches = [p for p in parent.iterdir() if p.name.casefold() == name.casefold()]
                    if len(matches) != 1 or matches[0].is_symlink() or not matches[0].is_dir():
                        raise OSError('Ordner fehlt oder ist nicht eindeutig/sicher')
                    parent = matches[0]
                changed, _ = install_project_cover_icon(parent)
                if changed: created += 1
                else: skipped += 1
            except (OSError, ValueError) as exc:
                failures.append(f'{band_name} / {project_name}: {exc}')
        details = (f'{created} Projektordner-Symbole erstellt.\n'
                   f'{skipped} übersprungen (kein Cover oder bereits angepasst).\n'
                   f'{len(failures)} Fehler.')
        if failures:
            details += '\n\n' + '\n'.join(failures[:15])
        self.message('Projekt-Cover als Ordnersymbol', details)

    def open_project_folder_settings(self):
        """Configure up to ten future subfolders; no filesystem changes here."""
        dialog = QDialog(self)
        dialog.setWindowTitle('MPW – Song/Projekt-Unterordner konfigurieren')
        dialog.resize(630, 620)
        outer = QVBoxLayout(dialog)
        hint = QLabel('Diese Vorlage gilt für gemeinsame Projektordner aller Songs eines Projekts.\n'
                      'Vorhandene Ordner werden NICHT umbenannt, verschoben oder gelöscht.\n'
                      'Bestehende Songordner bleiben unverändert erhalten.')
        hint.setWordWrap(True)
        outer.addWidget(hint)
        count_row = QHBoxLayout()
        count_row.addWidget(QLabel('Anzahl der Unterordner (4–10):'))
        count = QComboBox()
        for n in range(4, 11):
            count.addItem(str(n), n)
        count_row.addWidget(count)
        outer.addLayout(count_row)
        form = QFormLayout()
        fields = []
        current = self.configured_project_folders()
        for i in range(10):
            field = QLineEdit(current[i] if i < len(current) else '')
            field.setPlaceholderText(f'Ordner {i + 1}')
            if i < 4:
                field.setText(SONG_MEDIA_FOLDERS[i]); field.setReadOnly(True)
            fields.append(field)
            label = (('Cover – Bilddateien', 'Audio – Audio und Stems', 'Dokumente – Text/PDF', 'Video – Videodateien')[i] if i < 4 else f'Ordner {i + 1}')
            form.addRow(label + ':', field)
        outer.addLayout(form)
        def update_count(_index=None):
            selected = count.currentData()
            for index, field in enumerate(fields):
                field.setEnabled(index < selected)
        count.setCurrentIndex(max(0, len(current) - 4))
        count.currentIndexChanged.connect(update_count)
        update_count()
        actions = QHBoxLayout()
        save = QPushButton('Vorlage speichern')
        cancel = QPushButton('Abbrechen')
        actions.addWidget(save)
        actions.addWidget(cancel)
        outer.addLayout(actions)
        cancel.clicked.connect(dialog.reject)
        def save_template():
            names = [field.text().strip() for field in fields[:count.currentData()]]
            try:
                for name in names:
                    self.validate_folder_name(name)
                if len(set(name.casefold() for name in names)) != len(names):
                    raise ValueError('Ordnernamen dürfen nicht doppelt vorkommen.')
            except ValueError as exc:
                QMessageBox.warning(dialog, 'Ungültige Ordnernamen', str(exc))
                return
            self.save_app_configuration(project_folder_template=names)
            dialog.accept()
            self.message('Ordner-Vorlage gespeichert',
                         'Die neue Vorlage gilt für gemeinsame Projektordner.\n'
                         'Bestehende Ordner und Dateien wurden nicht verändert.')
        save.clicked.connect(save_template)
        dialog.exec()

