    def legacy_migration_text(self, key, **values):
        lang = self.effective_language()
        translations = self.LEGACY_MIGRATION_I18N
        return translations.get(lang, translations['de'])[key].format(**values)

    def open_legacy_audio_migration(self):
        """Preview and bulk transfer from legacy project/Musik to song/Audio."""
        tr = self.legacy_migration_text
        dialog = QDialog(self)
        dialog.setWindowTitle(tr('title'))
        dialog.resize(980, 680)
        layout = QVBoxLayout(dialog)
        explanation = QLabel(tr('explanation'))
        explanation.setWordWrap(True)
        layout.addWidget(explanation)
        preview = QTextEdit(); preview.setReadOnly(True)
        preview.setStyleSheet('QTextEdit {background-color: #ffffff; color: #161616;}')
        layout.addWidget(preview, 1)
        mode = QComboBox()
        mode.addItem(tr('copy_mode'), False)
        mode.addItem(tr('move_mode'), True)
        layout.addWidget(mode)
        buttons = QHBoxLayout()
        refresh = QPushButton(tr('refresh'))
        execute = QPushButton(tr('execute'))
        close = QPushButton(tr('close'))
        for button in (refresh, execute, close): buttons.addWidget(button)
        layout.addLayout(buttons)
        state = {'plan': [], 'skipped': []}
        def update():
            try:
                plan, skipped = plan_legacy_audio_migration(self.con, self.band_root_directory())
                state['plan'], state['skipped'] = plan, skipped
                lines = [tr('found', count=len(plan)), tr('skipped', count=len(skipped)), '']
                for source, sids, band, project in plan[:1000]:
                    lines.append(f"OK  {band} / {project} / {source}  →  {tr('destination')}")
                if len(plan) > 1000: lines.append(tr('more', count=len(plan)-1000))
                if skipped:
                    lines.extend(['', tr('unassigned')])
                    for source, reason in skipped[:500]: lines.append(f'– {source}: {reason}')
                preview.setPlainText('\n'.join(lines))
                execute.setEnabled(bool(plan))
            except Exception as exc:
                execute.setEnabled(False)
                preview.setPlainText(tr('preview_error', error=exc))
        def run():
            if not state['plan']: return
            moving = bool(mode.currentData())
            message = (tr('confirm_move' if moving else 'confirm_copy', count=len(state['plan']))
                       + '\n' + tr('backup_warning'))
            if QMessageBox.question(dialog, tr('confirm_title'), message,
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes: return
            copied, errors = migrate_legacy_audio_files(self.con, ROOT, self.band_root_directory(), state['plan'], moving)
            log_path = ROOT / ('audio_migration_' + datetime.now().strftime('%Y%m%d_%H%M%S') + '.txt')
            try:
                log_path.write_text('\n'.join([f'{status}: {source} => {target}' for source,target,status in copied]
                    + [f"{tr('log_error')}: {source}: {reason}" for source,reason in errors]
                    + [f"{tr('log_skipped')}: {source}: {reason}" for source,reason in state['skipped']]), encoding='utf-8')
            except OSError as exc:
                errors.append((tr('log_label'), str(exc)))
            self.refresh_media()
            QMessageBox.information(dialog, tr('done_title'),
                tr('done', copied=len(copied), errors=len(errors), skipped=len(state['skipped']), log=log_path))
            update()
        refresh.clicked.connect(update)
        execute.clicked.connect(run)
        close.clicked.connect(dialog.accept)
        update()
        dialog.exec()

    def ensure_band_subfolders(self, project_folder):
        """Legacy compatibility: project-level folders are not created anymore."""
        return

    def _legacy_ensure_band_subfolders(self, project_folder):
        for folder_name in self.configured_project_folders():
            matches = [entry for entry in project_folder.iterdir()
                       if entry.name.casefold() == folder_name.casefold()]
            if matches:
                if not matches[0].is_dir():
                    raise OSError(f'„{matches[0]}“ ist keine Ordnerstruktur.')
                continue
            (project_folder / folder_name).mkdir(exist_ok=True)

