    def project_import_text(self, key, **values):
        lang = self.effective_language()
        return self.PROJECT_IMPORT_I18N.get(lang, self.PROJECT_IMPORT_I18N["de"])[key].format(**values)

    def import_existing_projects(self):
        """Register direct project folders of the selected band without touching disk content."""
        bid = self.project_band.currentData()
        if bid is None:
            return self.error(self.project_import_text('no_band'))
        row = self.con.execute('SELECT name FROM bands WHERE id=?', (bid,)).fetchone()
        if row is None:
            return self.error(self.project_import_text('band_gone'))
        try:
            band_folder = self.existing_named_folder(self.band_root_directory(), row[0])
            if band_folder is None:
                return self.error(self.project_import_text('folder_missing'))
            existing = {name.casefold() for (name,) in self.con.execute(
                'SELECT name FROM projects WHERE band_id=?', (bid,)).fetchall()}
            candidates = []
            skipped = []
            for folder in sorted(band_folder.iterdir(), key=lambda p: p.name.casefold()):
                if not folder.is_dir() or folder.is_symlink():
                    continue
                try:
                    self.validate_folder_name(folder.name)
                except ValueError:
                    skipped.append(folder.name)
                    continue
                if folder.name.casefold() in existing:
                    skipped.append(folder.name)
                else:
                    candidates.append(folder.name)
        except (OSError, ValueError) as exc:
            return self.error(self.project_import_text('folder_read', error=exc))
        if not candidates:
            return self.message('Projektimport',
                                self.project_import_text('none', band=row[0], skipped=len(skipped)))
        preview = '\n'.join(f'• {name}' for name in candidates[:15])
        if len(candidates) > 15:
            preview += self.project_import_text('more', count=len(candidates)-15)
        answer = QMessageBox.question(
            self, self.localized_dialog_title('Vorhandene Song/Projekte übernehmen'),
            self.project_import_text('confirm', band=row[0], count=len(candidates), preview=preview),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if answer != QMessageBox.StandardButton.Yes:
            return
        imported = 0
        try:
            with self.con:
                for name in candidates:
                    cur = self.con.execute('INSERT OR IGNORE INTO projects(band_id,name) VALUES(?,?)',
                                           (bid, name))
                    imported += cur.rowcount
        except sqlite3.Error as exc:
            return self.error(self.project_import_text('import_failed', error=exc))
        self.refresh_all()
        self.message('Projektimport abgeschlossen',
                     self.project_import_text('success', imported=imported, skipped=len(skipped) + len(candidates) - imported))

