    def project_hardware_text(self, key, **values):
        language = self.effective_language()
        template = self.PROJECT_HARDWARE_I18N.get(language, self.PROJECT_HARDWARE_I18N['en'])[key]
        return template.format(**values)

    def add_project(self):
        bid = self.project_band.currentData()
        name = self.project_name.text().strip()
        if bid is None or not name:
            return self.error(self.project_hardware_text('missing_project'))
        try:
            self.validate_folder_name(name)
        except ValueError as exc:
            return self.error(str(exc))
        band_row = self.con.execute('SELECT name FROM bands WHERE id=?', (bid,)).fetchone()
        if not band_row:
            return self.error(self.project_hardware_text('missing_band'))
        if self.con.execute('SELECT 1 FROM projects WHERE band_id=? AND name=? COLLATE NOCASE',
                            (bid, name)).fetchone():
            return self.message(self.project_hardware_text('duplicate'), self.project_hardware_text('duplicate'))
        try:
            band_folder = self.existing_named_folder(self.band_root_directory(), band_row[0])
            if band_folder is None:
                return self.error(self.project_hardware_text('missing_folder'))
            project_folder = self.existing_named_folder(band_folder, name)
            if project_folder is None:
                project_folder = band_folder / name
                project_folder.mkdir(exist_ok=False)
            self.ensure_band_subfolders(project_folder)
        except (OSError, ValueError) as exc:
            return self.error(self.project_hardware_text('folder_error', error=exc))
        try:
            with self.con:
                self.con.execute('INSERT INTO projects(band_id,name) VALUES(?,?)', (bid,name))
            self.refresh_all()
            self.message(self.localized_dialog_title('Projekt angelegt'), self.project_hardware_text('project_created', name=name, folder=project_folder, subfolders=', '.join(self.configured_project_folders())))
        except sqlite3.IntegrityError:
            self.message(self.project_hardware_text('duplicate'), self.project_hardware_text('duplicate'))

    def add_instrument(self):
        bid = self.inst_band.currentData()
        cat, details = self.inst_cat.currentText().strip(), self.inst_detail.currentText().strip()
        if bid is None or not cat or not details: return self.error(self.project_hardware_text('hardware_missing'))
        with self.con: self.con.execute('INSERT INTO instruments(band_id,category,details) VALUES(?,?,?)',(bid,cat,details))
        self.refresh_instruments()

    def load_instrument(self, current, previous=None):
        if current is None: return
        iid = current.data(Qt.ItemDataRole.UserRole)
        row = self.con.execute('SELECT category,details FROM instruments WHERE id=?',(iid,)).fetchone()
        if row:
            # Group first: changing it refills the detail menu, then the detail is set.
            self.inst_cat.setCurrentText(row[0] or '')
            self.inst_detail.setCurrentText(row[1] or '')

    def update_instrument(self):
        item = self.inst_list.currentItem()
        if item is None: return self.error(self.project_hardware_text('hardware_select'))
        iid = item.data(Qt.ItemDataRole.UserRole)
        cat, details = self.inst_cat.currentText().strip(), self.inst_detail.currentText().strip()
        if not cat or not details: return self.error(self.project_hardware_text('hardware_empty'))
        with self.con:
            self.con.execute('UPDATE instruments SET category=?,details=? WHERE id=?',(cat,details,iid))
        self.refresh_instruments()
        self.message(self.localized_dialog_title('Gespeichert'), self.project_hardware_text('hardware_updated'))

    def delete_instrument(self):
        item = self.inst_list.currentItem()
        if item is None: return self.error(self.project_hardware_text('hardware_select'))
        iid = item.data(Qt.ItemDataRole.UserRole)
        if QMessageBox.question(self,self.localized_dialog_title('Hardware löschen'),
            self.project_hardware_text('hardware_delete'),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes: return
        with self.con:
            self.con.execute('DELETE FROM instruments WHERE id=?',(iid,))
        # clearEditText keeps the menu entries; clear() would remove them.
        self.inst_cat.clearEditText(); self.inst_detail.clearEditText()
        self.refresh_instruments()

    def refresh_instruments(self, *args):
        self.inst_list.clear(); bid = self.inst_band.currentData()
        # Menus list saved entries of all bands, so they are refreshed even without a band.
        self.refresh_instrument_choices()
        if bid is None: return
        for iid,cat,details in self.con.execute('SELECT id,category,details FROM instruments WHERE band_id=? ORDER BY id',(bid,)):
            from PySide6.QtWidgets import QListWidgetItem
            item = QListWidgetItem(f'{cat}: {details}')
            item.setData(Qt.ItemDataRole.UserRole,iid)
            self.inst_list.addItem(item)

    @staticmethod
    def _fill_editable_combo(combo, values):
        """Replace the menu entries but keep what the user is typing."""
        text = combo.currentText()
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItems(values)
            combo.setCurrentIndex(-1)
            combo.setEditText(text)
        finally:
            combo.blockSignals(False)

    def refresh_instrument_choices(self):
        groups, _details = saved_hardware_choices(self.con)
        self._fill_editable_combo(self.inst_cat, groups)
        self.refresh_instrument_detail_choices()

    def refresh_instrument_detail_choices(self, *args):
        _groups, details = saved_hardware_choices(self.con, self.inst_cat.currentText())
        self._fill_editable_combo(self.inst_detail, details)

    def ensure_song_media_folders(self, song_id):
        folder = safe_song_directory(self.con, ROOT, song_id, self.band_root_directory(), create=True)
        for name in self.configured_project_folders()[4:]:
            target = folder / name
            if target.is_symlink() or (target.exists() and not target.is_dir()):
                raise OSError(f'Unsicherer Zusatzordner: {target}')
            target.mkdir(exist_ok=True)
        return folder

    def add_song(self):
        pid = self.song_project.currentData(); title = self.new_title.text().strip()
        if pid is None or not title: return self.error('Projekt und Songtitel fehlen.')
        with self.con: cur = self.con.execute('INSERT INTO songs(project_id,title,lyrics) VALUES(?,?,?)',(pid,title,LYRICS))
        try:
            self.ensure_song_media_folders(cur.lastrowid)
        except (OSError, ValueError) as exc:
            self.error(f'Song gespeichert, aber Medienordner konnten nicht angelegt werden: {exc}')
        self.refresh_all(); self.song_select.setCurrentIndex(self.find_song_in_suno(cur.lastrowid)); self.load_song()

    def load_song(self, *args):
        sid = self.song_select.currentData()
        if sid is None: return
        row = self.con.execute('SELECT status,distributor,platforms,style,lyrics FROM songs WHERE id=?',(sid,)).fetchone()
        if row:
            self.status.setCurrentIndex(max(0, self.status.findData(row[0] or 'In Bearbeitung'))); self.song_dist.setText(row[1] or '')
            self.song_platforms.setText(row[2] or ''); self.style.setPlainText(row[3] or ''); self.lyrics.setPlainText(row[4] or '')
            self.count()

    def open_song_infos(self):
        sid = self.song_select.currentData()
        if sid is None:
            return self.error('Bitte zuerst einen Song auswählen.')
        song = self.con.execute('SELECT title FROM songs WHERE id=?', (sid,)).fetchone()
        if not song:
            return self.error('Der ausgewählte Song existiert nicht mehr.')

        dialog = QDialog(self)
        dialog.setWindowTitle(f'INFOS – {song[0]}')
        dialog.resize(900, 650)
        layout = QVBoxLayout(dialog)
        layout.addWidget(QLabel(f'Zusatzinformationen zum Song: {song[0]}'))
        toolbar = QHBoxLayout()
        editor = QTextEdit(dialog)
        editor.setAcceptRichText(True)
        editor.setPlaceholderText('Songbeschreibung, Hintergrund, Produktionsnotizen, Quellen …')
        row = self.con.execute('SELECT html FROM song_infos WHERE song_id=?', (sid,)).fetchone()
        if row:
            editor.setHtml(row[0] or '')

        def format_button(label, callback):
            button = QPushButton(label, dialog)
            button.clicked.connect(callback)
            toolbar.addWidget(button)
            return button

        format_button('Fett', lambda: editor.setFontWeight(
            QFont.Weight.Normal if editor.fontWeight() >= QFont.Weight.Bold else QFont.Weight.Bold))
        format_button('Kursiv', lambda: editor.setFontItalic(not editor.fontItalic()))
        format_button('Unterstrichen', lambda: editor.setFontUnderline(not editor.fontUnderline()))
        format_button('Textfarbe', lambda: self.set_song_info_color(editor, dialog))
        format_button('Schriftgröße', lambda: self.set_song_info_font_size(editor, dialog))
        format_button('Linksbündig', lambda: editor.setAlignment(Qt.AlignmentFlag.AlignLeft))
        format_button('Zentriert', lambda: editor.setAlignment(Qt.AlignmentFlag.AlignHCenter))
        format_button('Aufzählung', lambda: editor.textCursor().insertList(
            __import__('PySide6.QtGui', fromlist=['QTextListFormat']).QTextListFormat.Style.ListDisc))
        layout.addLayout(toolbar)
        layout.addWidget(editor, 1)
        buttons = QHBoxLayout()
        cancel = QPushButton('Abbrechen', dialog)
        cancel.clicked.connect(dialog.reject)
        buttons.addWidget(cancel)
        save = QPushButton('INFOS speichern', dialog)
        def save_infos():
            try:
                with self.con:
                    self.con.execute(
                        """INSERT INTO song_infos(song_id,html,updated_at) VALUES(?,?,CURRENT_TIMESTAMP)
                        ON CONFLICT(song_id) DO UPDATE SET html=excluded.html, updated_at=CURRENT_TIMESTAMP""",
                        (sid, editor.toHtml()))
            except sqlite3.Error as exc:
                self.error(f'Song-Infos konnten nicht gespeichert werden: {exc}')
                return
            dialog.accept()
        save.clicked.connect(save_infos)
        buttons.addWidget(save)
        layout.addLayout(buttons)
        dialog.exec()

    def set_song_info_color(self, editor, parent):
        color = QColorDialog.getColor(editor.textColor(), parent, 'Textfarbe auswählen')
        if color.isValid():
            editor.setTextColor(color)

    def set_song_info_font_size(self, editor, parent):
        size, ok = QInputDialog.getInt(parent, 'Schriftgröße', 'Punktgröße:',
                                       max(6, int(editor.fontPointSize() or 11)), 6, 72)
        if ok:
            editor.setFontPointSize(size)

    def count(self):
        a = len(self.style.toPlainText()); b = len(self.lyrics.toPlainText())
        self.counter.setText(f'Style: {a}/1000    ·    Lyrics: {b}/5000' + ('    ⚠ Zeichenlimit überschritten' if a>1000 or b>5000 else ''))

    def save_song(self):
        sid = self.song_select.currentData()
        if sid is None: return self.error('Bitte zuerst einen Song-Eintrag zum ausgewählten Projekt anlegen.')
        a = self.style.toPlainText(); b = self.lyrics.toPlainText()
        if len(a)>1000 or len(b)>5000: return self.error('Style maximal 1.000, Lyrics maximal 5.000 Zeichen.')
        # Shared with the browser GUI (mpw_web.py): same history rule, same transaction.
        archived = save_song_record(self.con, sid, self.status.currentData(), self.song_dist.text(),
                                    self.song_platforms.text(), a, b)
        if archived is None:
            return self.error('Der ausgewählte Song existiert nicht mehr.')
        self.refresh_ai_versions()
        self.message('Gespeichert', 'Song gespeichert.' + (' Der vorherige Prompt wurde in der Versionshistorie gesichert.' if archived else ''))

    def show_production_dashboard(self):
        '''Read-only cross-song production status with filters and song navigation.'''
        rows = self.con.execute('''
            SELECT s.id, b.name, p.name, s.title, COALESCE(s.status,''),
                   CASE WHEN TRIM(COALESCE(s.style,'') || COALESCE(s.lyrics,'')) != '' THEN 1 ELSE 0 END,
                   (SELECT COUNT(*) FROM media_assets m WHERE m.song_id=s.id),
                   (SELECT COUNT(*) FROM releases r WHERE r.song_id=s.id),
                   (SELECT COUNT(*) FROM release_platforms rp JOIN releases r2 ON rp.release_id=r2.id WHERE r2.song_id=s.id)
            FROM songs s JOIN projects p ON s.project_id=p.id JOIN bands b ON p.band_id=b.id
            ORDER BY b.name COLLATE NOCASE, p.name COLLATE NOCASE, s.title COLLATE NOCASE
        ''').fetchall()
        dialog = QDialog(self)
        dialog.setWindowTitle('Zentrale Produktionsübersicht – MPW v2.0.23')
        dialog.resize(1120, 680)
        outer = QVBoxLayout(dialog)
        heading = QLabel('Produktionsstatus aller Songs – nur lesende Auswertung')
        outer.addWidget(heading)
        filters = QHBoxLayout()
        search = QLineEdit(); search.setPlaceholderText('Band, Projekt oder Song suchen …')
        status_filter = QComboBox(); status_filter.addItems(['Alle Songs', 'Mit offenen Schritten', 'Ohne Prompt', 'Ohne lokale Medien', 'Ohne Release', 'Ohne Plattform', 'Alle Phasen erfasst'])
        sort_filter = QComboBox()
        sort_filter.addItems(['Band / Projekt / Song', 'Fortschritt: niedrig zuerst', 'Fortschritt: hoch zuerst', 'Offene Schritte: viele zuerst'])
        sort_filter.setToolTip('Sortiert nur die aktuelle Übersicht; gespeicherte Songdaten bleiben unverändert.')
        filters.addWidget(search, 2); filters.addWidget(status_filter, 1)
        filters.addWidget(sort_filter, 1)
        outer.addLayout(filters)
        advanced_filters = QHBoxLayout()
        band_filter = QComboBox()
        band_filter.addItem('Alle Bands', None)
        for band_name in sorted({str(record[1]) for record in rows}, key=str.casefold):
            band_filter.addItem(band_name, band_name)
        song_status_filter = QComboBox()
        song_status_filter.addItems(['Alle Songstatus', 'In Bearbeitung', 'Fertig', 'Veröffentlicht', 'Ohne Status'])
        readiness_filter = QComboBox()
        readiness_filter.addItems(['Alle Veröffentlichungsstände', 'Noch kein Release', 'Release ohne Plattform', 'Release mit Plattform', 'Vier Phasen erfasst'])
        advanced_filters.addWidget(QLabel('Band:'))
        advanced_filters.addWidget(band_filter, 2)
        advanced_filters.addWidget(QLabel('Songstatus:'))
        advanced_filters.addWidget(song_status_filter, 1)
        advanced_filters.addWidget(QLabel('Veröffentlichungsstand:'))
        advanced_filters.addWidget(readiness_filter, 2)
        outer.addLayout(advanced_filters)
        table = QTableWidget(0, 9, dialog)
        table.setHorizontalHeaderLabels(['Band', 'Projekt', 'Song', 'Songstatus', 'Prompt', 'Medien', 'Release', 'Fortschritt', 'Nächster Schritt'])
        table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        table.setAlternatingRowColors(True)
        table.setToolTip('Auf einen Eintrag in „Nächster Schritt“ klicken, um den fehlenden Arbeitsschritt zu öffnen.')
        # QTableWidget in a top-level QDialog may use the native Windows white
        # viewport/alternate-row palette instead of the main window's QSS.
        # Set both palette roles and a local stylesheet to match MPW themes.
        theme = self.current_color_theme()
        surface = QColor(theme['surface'])
        alternate = surface.lighter(112) if surface.lightness() < 128 else surface.darker(106)
        table_palette = table.palette()
        table_palette.setColor(QPalette.ColorRole.Base, surface)
        table_palette.setColor(QPalette.ColorRole.AlternateBase, alternate)
        table_palette.setColor(QPalette.ColorRole.Text, QColor(theme['foreground']))
        table_palette.setColor(QPalette.ColorRole.Highlight, QColor(theme['selection']))
        table_palette.setColor(QPalette.ColorRole.HighlightedText, QColor(theme['foreground']))
        table.setPalette(table_palette)
        table.setStyleSheet(f"""
            QTableWidget {{
                background-color: {theme['surface']};
                alternate-background-color: {alternate.name()};
                color: {theme['foreground']};
                border: 1px solid {theme['border']};
                selection-background-color: {theme['selection']};
                selection-color: {theme['foreground']};
            }}
            QTableWidget::item {{ color: {theme['foreground']}; }}
            QTableWidget::item:selected {{
                background-color: {theme['selection']};
                color: {theme['foreground']};
            }}
            QHeaderView::section {{
                background-color: {theme['tab']};
                color: {theme['foreground']};
                border: 1px solid {theme['border']};
                padding: 5px;
            }}
        """)
        table.horizontalHeader().setStretchLastSection(True)
        table.setColumnWidth(0, 125); table.setColumnWidth(1, 135)
        table.setColumnWidth(2, 175); table.setColumnWidth(3, 110)
        table.setColumnWidth(7, 145)
        outer.addWidget(table, 1)
        summary = QLabel(); outer.addWidget(summary)
        visible_rows = []  # Current filtered and sorted dashboard snapshot for CSV export.

        def missing_parts(record):
            _, _, _, _, _, prompt, media, releases, platforms = record
            missing = []
            if not prompt: missing.append('Prompt')
            if not media: missing.append('Medien')
            if not releases: missing.append('Release')
            elif not platforms: missing.append('Plattform')
            return missing

        def refresh():
            phrase = search.text().strip().casefold()
            selected = status_filter.currentText()
            visible = []
            for record in rows:
                sid, band, project, title, state, prompt, media, releases, platforms = record
                missing = missing_parts(record)
                if phrase and phrase not in ' '.join(str(v) for v in (band, project, title)).casefold(): continue
                selected_band = band_filter.currentData()
                if selected_band is not None and band != selected_band: continue
                chosen_status = song_status_filter.currentText()
                if chosen_status == 'Ohne Status':
                    if str(state or '').strip(): continue
                elif chosen_status != 'Alle Songstatus' and (str(state or '').strip() or 'In Bearbeitung') != chosen_status:
                    continue
                readiness = readiness_filter.currentText()
                if readiness == 'Noch kein Release' and releases: continue
                if readiness == 'Release ohne Plattform' and (not releases or platforms): continue
                if readiness == 'Release mit Plattform' and (not releases or not platforms): continue
                if readiness == 'Vier Phasen erfasst' and missing: continue
                if selected == 'Mit offenen Schritten' and not missing: continue
                if selected == 'Ohne Prompt' and prompt: continue
                if selected == 'Ohne lokale Medien' and media: continue
                if selected == 'Ohne Release' and releases: continue
                if selected == 'Ohne Plattform' and (not releases or platforms): continue
                if selected == 'Alle Phasen erfasst' and missing: continue
                visible.append(record)
            def completion(record):
                return sum(bool(value) for value in (record[5], record[6], record[7], record[8]))
            order = sort_filter.currentIndex()
            if order == 1:
                visible.sort(key=lambda r: (completion(r), str(r[1]).casefold(), str(r[3]).casefold()))
            elif order == 2:
                visible.sort(key=lambda r: (-completion(r), str(r[1]).casefold(), str(r[3]).casefold()))
            elif order == 3:
                visible.sort(key=lambda r: (-len(missing_parts(r)), str(r[1]).casefold(), str(r[3]).casefold()))
            visible_rows[:] = visible
            table.setRowCount(len(visible))
            for i, record in enumerate(visible):
                sid, band, project, title, state, prompt, media, releases, platforms = record
                missing = missing_parts(record)
                values = [band, project, title, state or 'In Bearbeitung', 'Ja' if prompt else 'Fehlt',
                          str(media), str(releases), '', (missing[0] + (f' (+{len(missing)-1} weitere)' if len(missing)>1 else '')) if missing else 'Manuelle Abschlussprüfung']
                for col, value in enumerate(values):
                    cell = QTableWidgetItem(str(value))
                    if col == 2: cell.setData(Qt.ItemDataRole.UserRole, sid)
                    if col == 8:
                        cell.setToolTip(('Klicken: offenen Arbeitsschritt auswählen.\nNoch offen: ' + ', '.join(missing)) if missing else 'Alle erfassten Phasen vorhanden; Abschlussprüfung manuell durchführen.')
                        if missing:
                            cell.setForeground(QColor(theme['foreground']))
                            font = cell.font(); font.setUnderline(True); cell.setFont(font)
                    table.setItem(i, col, cell)
                # Four recorded phases: prompt, local media, release and platform.
                # This is a data-completeness indicator, not a quality certificate.
                from PySide6.QtWidgets import QProgressBar
                completed = int(bool(prompt)) + int(bool(media)) + int(bool(releases)) + int(bool(platforms))
                percent = completed * 25
                progress = QProgressBar(table)
                progress.setRange(0, 100)
                progress.setValue(percent)
                progress.setFormat(f'{percent}%  ({completed}/4)')
                progress.setTextVisible(True)
                progress.setToolTip('Erfasste Phasen: Prompt, lokale Medien, Release und Plattform. Keine Prüfung von Audioqualität, Cover, Rechten oder tatsächlicher Veröffentlichung.')
                progress.setStyleSheet(f"""
                    QProgressBar {{
                        background-color: {theme['surface']};
                        color: {theme['foreground']};
                        border: 1px solid {theme['border']};
                        border-radius: 4px;
                        text-align: center;
                        min-height: 18px;
                    }}
                    QProgressBar::chunk {{
                        background-color: {theme['selection']};
                        border-radius: 3px;
                    }}
                """)
                table.setCellWidget(i, 7, progress)
            incomplete = sum(bool(missing_parts(r)) for r in visible)
            summary.setText(f'{len(visible)} von {len(rows)} Songs angezeigt · {incomplete} mit offenen Schritten · {len(visible)-incomplete} mit vier erfassten Phasen. Datenstand beim Öffnen; je Phase 25 %. Klick auf „Nächster Schritt“: offenen Punkt öffnen.')

        def export_visible_csv():
            if not visible_rows:
                return self.message('CSV-Export', 'Keine Songs in der aktuellen Filterauswahl vorhanden.')
            suggested = str(Path.home() / ('MPW_Produktionsuebersicht_' + date.today().isoformat() + '.csv'))
            filename, _ = QFileDialog.getSaveFileName(dialog, 'Gefilterte Produktionsübersicht exportieren', suggested, 'CSV-Dateien (*.csv)')
            if not filename:
                return
            try:
                with open(filename, 'w', encoding='utf-8-sig', newline='') as stream:
                    writer = csv.writer(stream, delimiter=';', quoting=csv.QUOTE_MINIMAL)
                    writer.writerow(['Band', 'Projekt', 'Song', 'Songstatus', 'Prompt', 'Medienanzahl', 'Releaseanzahl', 'Plattformanzahl', 'Fortschritt (%)', 'Nächster Schritt'])
                    for record in visible_rows:
                        sid, band, project, title, state, prompt, media, releases, platforms = record
                        missing = missing_parts(record)
                        completed = sum(bool(value) for value in (prompt, media, releases, platforms))
                        next_step = ', '.join(missing) if missing else 'Manuelle Abschlussprüfung'
                        writer.writerow([band, project, title, state or 'In Bearbeitung',
                                         'Ja' if prompt else 'Fehlt', media, releases, platforms,
                                         completed * 25, next_step])
                self.message('CSV-Export', f'{len(visible_rows)} Songs wurden exportiert:\n{filename}')
            except (OSError, UnicodeError, csv.Error) as exc:
                self.error(f'CSV-Export fehlgeschlagen: {exc}')

        def show_production_statistics():
            # The statistics use the SAME filtered snapshot as the table/CSV export.
            # No database changes and no assumptions about publication quality.
            snapshot = list(visible_rows)
            if not snapshot:
                return self.message('Produktionsstatistik', 'Keine Songs in der aktuellen Filterauswahl vorhanden.')
            stats = QDialog(dialog)
            stats.setWindowTitle('Produktionsstatistik – aktuelle Filterauswahl')
            stats.resize(1060, 810)
            layout = QVBoxLayout(stats)
            total = len(snapshot)
            complete = sum(not missing_parts(r) for r in snapshot)
            open_steps = sum(len(missing_parts(r)) for r in snapshot)
            avg = sum(25 * sum(bool(x) for x in r[5:9]) for r in snapshot) / total
            layout.addWidget(QLabel(
                f'{total} Songs · Durchschnitt {avg:.1f} % · {open_steps} offene Arbeitsschritte · '
                f'{complete} Songs mit vier erfassten Phasen'))
            layout.addWidget(QLabel('Je Phase 25 %: Prompt, lokale Medien, Release, Plattform. '
                                    'Keine Qualitäts- oder Veröffentlichungsbestätigung.'))
            by_band = {}
            for r in snapshot:
                name = str(r[1])
                entry = by_band.setdefault(name, [0, 0, 0, 0])
                entry[0] += 1
                entry[1] += 25 * sum(bool(x) for x in r[5:9])
                entry[2] += len(missing_parts(r))
                entry[3] += int(not missing_parts(r))
            report = QTableWidget(len(by_band), 6, stats)
            report.setHorizontalHeaderLabels(['Band', 'Songs', 'Ø Fortschritt', 'Offene Schritte', '4 Phasen erfasst', 'Fortschrittsgrafik'])
            report.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
            report.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
            report.setAlternatingRowColors(True)
            # Match the already themed production overview table. Without this,
            # Qt/Windows may render the statistics viewport and alternate rows white.
            report.setPalette(table.palette())
            report.setStyleSheet(table.styleSheet())
            report.horizontalHeader().setStretchLastSection(True)
            report.setColumnWidth(0, 210)
            report.setColumnWidth(1, 90)
            report.setColumnWidth(2, 145)
            report.setColumnWidth(3, 145)
            report.setColumnWidth(5, 150)
            for row_no, (band_name, (count, progress_sum, pending, finished)) in enumerate(
                    sorted(by_band.items(), key=lambda item: item[0].casefold())):
                for column, value in enumerate((band_name, str(count), f'{progress_sum / count:.1f} %',
                                                str(pending), str(finished))):
                    report.setItem(row_no, column, QTableWidgetItem(value))
                from PySide6.QtWidgets import QProgressBar
                band_progress = QProgressBar(report)
                band_progress.setRange(0, 100)
                band_progress.setValue(round(progress_sum / count))
                band_progress.setFormat(f'{progress_sum / count:.1f} %')
                band_progress.setTextVisible(True)
                band_progress.setToolTip('Durchschnitt der vier erfassten Produktionsphasen dieser Band; keine Qualitätsprüfung.')
                band_progress.setStyleSheet(f"""
                    QProgressBar {{ background-color: {theme['surface']}; color: {theme['foreground']};
                        border: 1px solid {theme['border']}; border-radius: 4px; text-align: center; min-height: 18px; }}
                    QProgressBar::chunk {{ background-color: {theme['selection']}; border-radius: 3px; }}
                """)
                report.setCellWidget(row_no, 5, band_progress)
            layout.addWidget(report, 1)
            # Project identity includes band and project: same-named projects from
            # different bands must never be merged in the statistics.
            by_project = {}
            for record in snapshot:
                project_key = (str(record[1]), str(record[2]))
                entry = by_project.setdefault(project_key, [0, 0, 0, 0])
                entry[0] += 1
                entry[1] += 25 * sum(bool(x) for x in record[5:9])
                entry[2] += len(missing_parts(record))
                entry[3] += int(not missing_parts(record))
            layout.addWidget(QLabel('Song/Projekte – Auswertung der aktuell gefilterten Songs'))
            project_report = QTableWidget(len(by_project), 7, stats)
            project_report.setHorizontalHeaderLabels([
                'Band', 'Song/Projekt', 'Songs', 'Ø Fortschritt',
                'Offene Schritte', '4 Phasen erfasst', 'Fortschrittsgrafik'])
            project_report.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
            project_report.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
            project_report.setAlternatingRowColors(True)
            project_report.setPalette(table.palette())
            project_report.setStyleSheet(table.styleSheet())
            project_report.horizontalHeader().setStretchLastSection(True)
            project_report.setColumnWidth(0, 155)
            project_report.setColumnWidth(1, 180)
            project_report.setColumnWidth(2, 65)
            project_report.setColumnWidth(3, 120)
            project_report.setColumnWidth(4, 120)
            project_report.setColumnWidth(5, 125)
            for row_no, ((band_name, project_name), (count, progress_sum, pending, finished)) in enumerate(
                    sorted(by_project.items(), key=lambda item: (item[0][0].casefold(), item[0][1].casefold()))):
                for column, value in enumerate((band_name, project_name, str(count),
                                                f'{progress_sum / count:.1f} %', str(pending), str(finished))):
                    project_report.setItem(row_no, column, QTableWidgetItem(value))
                progress_bar = QProgressBar(project_report)
                progress_bar.setRange(0, 100)
                progress_bar.setValue(round(progress_sum / count))
                progress_bar.setFormat(f'{progress_sum / count:.1f} %')
                progress_bar.setTextVisible(True)
                progress_bar.setToolTip('Durchschnitt der vier erfassten Produktionsphasen dieses Song/Projekts.')
                progress_bar.setStyleSheet(f"""
                    QProgressBar {{ background-color: {theme['surface']}; color: {theme['foreground']};
                        border: 1px solid {theme['border']}; border-radius: 4px; text-align: center; min-height: 18px; }}
                    QProgressBar::chunk {{ background-color: {theme['selection']}; border-radius: 3px; }}
                """)
                project_report.setCellWidget(row_no, 6, progress_bar)
            layout.addWidget(project_report, 1)
            project_report.setToolTip('Doppelklick auf ein Song/Projekt: zugehörige Songs, Fortschritt und offene Schritte anzeigen.')

            def show_project_song_details(row_index, _column_index=0):
                band_cell = project_report.item(row_index, 0)
                project_cell = project_report.item(row_index, 1)
                if band_cell is None or project_cell is None:
                    return
                band_name, project_name = band_cell.text(), project_cell.text()
                selected_songs = [record for record in snapshot
                                  if str(record[1]) == band_name and str(record[2]) == project_name]
                detail = QDialog(stats)
                detail.setWindowTitle(f'Song/Projekt-Details – {band_name} / {project_name}')
                detail.resize(940, 480)
                detail_layout = QVBoxLayout(detail)
                detail_layout.addWidget(QLabel(
                    f'{band_name} / {project_name} · {len(selected_songs)} Song(s) · '
                    'nur aktuell gefilterte Songs, keine Datenänderung'))
                song_table = QTableWidget(len(selected_songs), 5, detail)
                song_table.setHorizontalHeaderLabels([
                    'Song', 'Songstatus', 'Fortschritt', 'Offene Schritte', 'Nächster Schritt'])
                song_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
                song_table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
                song_table.setAlternatingRowColors(True)
                song_table.setPalette(table.palette())
                song_table.setStyleSheet(table.styleSheet())
                song_table.horizontalHeader().setStretchLastSection(True)
                song_table.setColumnWidth(0, 220)
                song_table.setColumnWidth(1, 130)
                song_table.setColumnWidth(2, 110)
                song_table.setColumnWidth(3, 250)
                for index, record in enumerate(selected_songs):
                    song_id, _band, _project, title, state, prompt, media, releases, platforms = record
                    missing = missing_parts(record)
                    progress = 25 * sum(bool(value) for value in (prompt, media, releases, platforms))
                    values = [title, state or 'In Bearbeitung', f'{progress} %',
                              ', '.join(missing) if missing else 'Keine',
                              missing[0] if missing else 'Manuelle Abschlussprüfung']
                    for column, value in enumerate(values):
                        item = QTableWidgetItem(str(value))
                        if column == 0:
                            item.setData(Qt.ItemDataRole.UserRole, song_id)
                        song_table.setItem(index, column, item)
                # Filter only the visible detail rows; keep original row indexes and song IDs.
                phase_filter_row = QHBoxLayout()
                phase_filter_row.addWidget(QLabel('Offene Produktionsphase:'))
                phase_filter = QComboBox(detail)
                phase_filter.addItems([
                    'Alle Songs', 'Mindestens ein offener Schritt',
                    'Prompt fehlt', 'Lokale Medien fehlen', 'Release fehlt',
                    'Plattform fehlt', 'Keine offenen Schritte'])
                phase_filter_row.addWidget(phase_filter, 1)
                visible_count = QLabel('', detail)
                phase_filter_row.addWidget(visible_count)
                detail_layout.addLayout(phase_filter_row)

                def apply_detail_phase_filter(_index=None):
                    option = phase_filter.currentText()
                    shown = 0
                    for row_number, song_record in enumerate(selected_songs):
                        pending = missing_parts(song_record)
                        if option == 'Alle Songs':
                            show = True
                        elif option == 'Mindestens ein offener Schritt':
                            show = bool(pending)
                        elif option == 'Keine offenen Schritte':
                            show = not pending
                        else:
                            phase_name = {
                                'Prompt fehlt': 'Prompt',
                                'Lokale Medien fehlen': 'Medien',
                                'Release fehlt': 'Release',
                                'Plattform fehlt': 'Plattform',
                            }[option]
                            show = (not bool(song_record[8])) if phase_name == 'Plattform' else phase_name in pending
                        song_table.setRowHidden(row_number, not show)
                        shown += int(show)
                    visible_count.setText(f'{shown} von {len(selected_songs)} Songs')
                    if song_table.currentRow() >= 0 and song_table.isRowHidden(song_table.currentRow()):
                        song_table.clearSelection()
                        song_table.setCurrentCell(-1, -1)

                phase_filter.currentIndexChanged.connect(apply_detail_phase_filter)
                apply_detail_phase_filter()
                detail_layout.addWidget(song_table, 1)
                detail_layout.addWidget(QLabel(
                    'Fortschritt = vier erfasste Phasen zu je 25 %. Keine Bestätigung von Qualität oder Veröffentlichung.'))

                def open_detail_song():
                    selected_row = song_table.currentRow()
                    if selected_row < 0 or song_table.isRowHidden(selected_row):
                        return self.error('Bitte zuerst einen sichtbaren Song auswählen.')
                    item = song_table.item(selected_row, 0)
                    if item is None:
                        return
                    song_id = item.data(Qt.ItemDataRole.UserRole)
                    combo_index = self.find_song_in_suno(song_id)
                    if combo_index < 0:
                        return self.error('Song ist in Songs & Suno nicht verfügbar. Bitte die Songliste aktualisieren.')
                    tab_index = next((i for i in range(self.tabs.count())
                                      if self.tab_key(i) == 'Songs & Suno'), -1)
                    if tab_index < 0:
                        return self.error('Reiter Songs & Suno nicht gefunden.')
                    self.song_select.setCurrentIndex(combo_index)
                    self.tabs.setCurrentIndex(tab_index)
                    detail.accept()
                    stats.accept()
                    dialog.accept()

                def show_song_checklist():
                    selected_row = song_table.currentRow()
                    if selected_row < 0 or song_table.isRowHidden(selected_row):
                        return self.error('Bitte zuerst einen sichtbaren Song auswählen.')
                    song_item = song_table.item(selected_row, 0)
                    if song_item is None:
                        return
                    selected_id = song_item.data(Qt.ItemDataRole.UserRole)
                    record = next((r for r in selected_songs if r[0] == selected_id), None)
                    if record is None:
                        return self.error('Song nicht in der aktuellen Auswahl gefunden.')
                    _id, _band, _project, song_title, _state, prompt, media, releases, platforms = record
                    checks = [('Suno-Prompt vorhanden', bool(prompt)),
                              ('Lokale Mediendateien vorhanden', bool(media)),
                              ('Release angelegt', bool(releases)),
                              ('Streamingplattform zugeordnet', bool(platforms))]
                    checklist = QDialog(detail)
                    checklist.setWindowTitle(f'Produktionscheckliste – {song_title}')
                    checklist.resize(610, 400)
                    checklist_layout = QVBoxLayout(checklist)
                    checklist_layout.addWidget(QLabel(f'Song: {song_title}  |  Band: {_band}  |  Song/Projekt: {_project}'))
                    checklist_layout.addWidget(QLabel('Automatisch geprüfte Produktionsphasen:'))
                    lines = [f'Produktionscheckliste: {song_title}', f'Band: {_band} / Song/Projekt: {_project}', '']
                    for name, present in checks:
                        status = 'Vorhanden' if present else 'Fehlt'
                        checklist_layout.addWidget(QLabel(f'{"✓" if present else "○"}  {name}: {status}'))
                        lines.append(('[' + ('x' if present else ' ') + f'] {name}: {status}'))
                    checklist_layout.addWidget(QLabel('Manuelle Abschlussprüfungen (pro Song gespeichert):'))
                    manual_items = (
                        ('audio', 'Audioqualität und Peaks prüfen'),
                        ('cover', 'Cover und Bildrechte prüfen'),
                        ('rights', 'Musik- und Nutzungsrechte prüfen'),
                        ('metadata', 'Metadaten / ISRC / UPC prüfen'),
                    )
                    saved_checks = dict(self.con.execute(
                        'SELECT check_key, completed FROM song_manual_checks WHERE song_id=?',
                        (selected_id,)).fetchall())
                    checkboxes = []
                    for key, name in manual_items:
                        checkbox = QCheckBox(name)
                        checkbox.setChecked(bool(saved_checks.get(key, 0)))
                        checklist_layout.addWidget(checkbox)
                        checkboxes.append((key, name, checkbox))

                    status_label = QLabel('Änderungen werden sofort für diesen Song gespeichert.')
                    checklist_layout.addWidget(status_label)

                    def save_manual_check(key, checked):
                        try:
                            with self.con:
                                self.con.execute(
                                    'INSERT INTO song_manual_checks(song_id,check_key,completed,updated_at) '
                                    'VALUES (?,?,?,CURRENT_TIMESTAMP) '
                                    'ON CONFLICT(song_id,check_key) DO UPDATE SET '
                                    'completed=excluded.completed, updated_at=CURRENT_TIMESTAMP',
                                    (selected_id, key, int(bool(checked))))
                            status_label.setText('Gespeichert.')
                        except sqlite3.Error as exc:
                            status_label.setText(f'Speichern fehlgeschlagen: {exc}')
                            for saved_key, _name, cb in checkboxes:
                                if saved_key == key:
                                    cb.blockSignals(True)
                                    cb.setChecked(not checked)
                                    cb.blockSignals(False)
                                    break

                    for key, _name, checkbox in checkboxes:
                        checkbox.toggled.connect(lambda checked, k=key: save_manual_check(k, checked))

                    checklist_layout.addStretch(1)
                    checklist_buttons = QHBoxLayout()
                    copy_button = QPushButton('Checkliste kopieren')
                    def copy_checklist():
                        current_lines = list(lines)
                        current_lines.append('Manuelle Abschlussprüfungen:')
                        for _key, name, cb in checkboxes:
                            current_lines.append('[' + ('x' if cb.isChecked() else ' ') + f'] {name}')
                        QApplication.clipboard().setText('\n'.join(current_lines))
                    copy_button.clicked.connect(copy_checklist)
                    checklist_buttons.addWidget(copy_button)
                    checklist_close = QPushButton('Schließen')
                    checklist_close.clicked.connect(checklist.accept)
                    checklist_buttons.addWidget(checklist_close)
                    checklist_layout.addLayout(checklist_buttons)
                    checklist.exec()

                controls = QHBoxLayout()
                checklist_button = QPushButton('Produktionscheckliste anzeigen')
                checklist_button.clicked.connect(show_song_checklist)
                controls.addWidget(checklist_button)
                open_button = QPushButton('Ausgewählten Song in Songs & Suno öffnen')
                open_button.clicked.connect(open_detail_song)
                controls.addWidget(open_button)
                close_detail = QPushButton('Schließen')
                close_detail.clicked.connect(detail.accept)
                controls.addWidget(close_detail)
                detail_layout.addLayout(controls)
                song_table.cellDoubleClicked.connect(lambda _row, _col: open_detail_song())
                detail.exec()

            project_report.cellDoubleClicked.connect(show_project_song_details)
            layout.addWidget(QLabel('Song/Projekt-Tipp: Doppelklick auf eine Projektzeile öffnet die Song-Detailansicht.'))
            layout.addWidget(QLabel('Songstatus – Verteilung der aktuell gefilterten Songs'))
            status_counts = {}
            for record in snapshot:
                state = str(record[4] or '').strip() or 'In Bearbeitung'
                status_counts[state] = status_counts.get(state, 0) + 1
            status_report = QTableWidget(len(status_counts), 3, stats)
            status_report.setHorizontalHeaderLabels(['Songstatus', 'Songs', 'Anteil'])
            status_report.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
            status_report.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
            status_report.setAlternatingRowColors(True)
            status_report.setPalette(table.palette())
            status_report.setStyleSheet(table.styleSheet())
            status_report.horizontalHeader().setStretchLastSection(True)
            status_report.setColumnWidth(0, 230)
            status_report.setColumnWidth(1, 100)
            for index, (state, count) in enumerate(sorted(status_counts.items(), key=lambda item: item[0].casefold())):
                status_report.setItem(index, 0, QTableWidgetItem(state))
                status_report.setItem(index, 1, QTableWidgetItem(str(count)))
                share = QProgressBar(status_report)
                share.setRange(0, 100)
                share.setValue(round(count * 100 / total))
                share.setFormat(f'{count * 100 / total:.1f} %')
                share.setTextVisible(True)
                share.setStyleSheet(f"""
                    QProgressBar {{ background-color: {theme['surface']}; color: {theme['foreground']};
                        border: 1px solid {theme['border']}; border-radius: 4px; text-align: center; min-height: 18px; }}
                    QProgressBar::chunk {{ background-color: {theme['selection']}; border-radius: 3px; }}
                """)
                status_report.setCellWidget(index, 2, share)
            layout.addWidget(status_report, 1)
            # Manual completion is independent from the four automatic phases.
            manual_keys = ('audio', 'cover', 'rights', 'metadata')
            selected_ids = [int(r[0]) for r in snapshot]
            manual_by_song = {song_id: set() for song_id in selected_ids}
            # Parameterized query avoids interpolating song IDs into SQL.
            for start in range(0, len(selected_ids), 400):
                batch = selected_ids[start:start + 400]
                placeholders = ','.join('?' for _ in batch)
                for song_id, key in self.con.execute(
                        f'SELECT song_id, check_key FROM song_manual_checks '
                        f'WHERE completed=1 AND song_id IN ({placeholders})', batch):
                    if key in manual_keys:
                        manual_by_song[int(song_id)].add(key)
            manual_complete = sum(len(keys) == 4 for keys in manual_by_song.values())
            manual_done = sum(len(keys) for keys in manual_by_song.values())
            layout.addWidget(QLabel(
                f'Manuelle Abschlussprüfungen – {manual_done} von {4 * total} erledigt · '
                f'{manual_complete} von {total} Songs vollständig manuell geprüft'))
            manual_report = QTableWidget(total, 7, stats)
            manual_report.setHorizontalHeaderLabels([
                'Band', 'Song/Projekt', 'Song', 'Audio', 'Cover', 'Rechte', 'Metadaten'])
            manual_report.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
            manual_report.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
            manual_report.setAlternatingRowColors(True)
            manual_report.setPalette(table.palette())
            manual_report.setStyleSheet(table.styleSheet())
            manual_report.horizontalHeader().setStretchLastSection(True)
            manual_report.setColumnWidth(0, 125)
            manual_report.setColumnWidth(1, 145)
            manual_report.setColumnWidth(2, 190)
            for row_index, record in enumerate(snapshot):
                done = manual_by_song[int(record[0])]
                values = [str(record[1]), str(record[2]), str(record[3])] + [
                    'Erledigt' if key in done else 'Offen' for key in manual_keys]
                for column, value in enumerate(values):
                    manual_report.setItem(row_index, column, QTableWidgetItem(value))
            layout.addWidget(manual_report, 1)
            # Combined readiness is deliberately TWO independent scores, not a
            # certification or a misleading single percentage.
            readiness_filter_line = QHBoxLayout()
            readiness_filter_line.addWidget(QLabel('Produktionsbereitschaft filtern:'))
            readiness_filter = QComboBox(stats)
            readiness_filter.addItems([
                'Alle Songs', 'Manuelle Prüfungen offen', 'Automatische Phasen offen',
                'Mindestens ein Punkt offen', '8/8 erfasst'])
            readiness_filter_line.addWidget(readiness_filter, 1)
            readiness_filter_count = QLabel(stats)
            readiness_filter_line.addWidget(readiness_filter_count)
            layout.addLayout(readiness_filter_line)
            layout.addWidget(QLabel('Produktionsbereitschaft – automatische Erfassung und manuelle Prüfungen getrennt'))
            readiness_report = QTableWidget(total, 7, stats)
            readiness_report.setHorizontalHeaderLabels([
                'Band', 'Song/Projekt', 'Song', 'Erfasste Phasen',
                'Manuelle Prüfungen', 'Offen gesamt', 'Erfassungsstand'])
            readiness_report.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
            readiness_report.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
            readiness_report.setAlternatingRowColors(True)
            readiness_report.setPalette(table.palette())
            readiness_report.setStyleSheet(table.styleSheet())
            readiness_report.horizontalHeader().setStretchLastSection(True)
            readiness_report.setColumnWidth(0, 120)
            readiness_report.setColumnWidth(1, 145)
            readiness_report.setColumnWidth(2, 190)
            readiness_report.setColumnWidth(3, 120)
            readiness_report.setColumnWidth(4, 135)
            readiness_report.setColumnWidth(5, 100)
            for row_index, record in enumerate(snapshot):
                automatic_done = sum(bool(x) for x in record[5:9])
                manual_count = len(manual_by_song[int(record[0])])
                outstanding = (4 - automatic_done) + (4 - manual_count)
                readiness_text = '8/8 erfasst' if outstanding == 0 else 'Noch unvollständig'
                values = [str(record[1]), str(record[2]), str(record[3]),
                          f'{automatic_done}/4 ({automatic_done * 25} %)',
                          f'{manual_count}/4 ({manual_count * 25} %)',
                          str(outstanding), readiness_text]
                for column, value in enumerate(values):
                    readiness_report.setItem(row_index, column, QTableWidgetItem(value))
            def readiness_matches(record):
                auto_count = sum(bool(x) for x in record[5:9])
                manual_count = len(manual_by_song[int(record[0])])
                mode = readiness_filter.currentIndex()
                return (mode == 0 or
                        (mode == 1 and manual_count < 4) or
                        (mode == 2 and auto_count < 4) or
                        (mode == 3 and auto_count + manual_count < 8) or
                        (mode == 4 and auto_count + manual_count == 8))

            def update_readiness_filter():
                shown = 0
                for row_index, record in enumerate(snapshot):
                    visible = readiness_matches(record)
                    readiness_report.setRowHidden(row_index, not visible)
                    shown += int(visible)
                readiness_filter_count.setText(f'{shown} von {total} Songs')

            readiness_filter.currentIndexChanged.connect(update_readiness_filter)
            update_readiness_filter()
            layout.addWidget(readiness_report, 1)
            fully_recorded = sum(
                all(bool(x) for x in record[5:9]) and len(manual_by_song[int(record[0])]) == 4
                for record in snapshot)
            layout.addWidget(QLabel(
                f'{fully_recorded} von {total} Songs mit 4/4 erfassten Phasen UND 4/4 manuell abgehakten Prüfungen. '
                'Dies ist keine unabhängige Qualitäts- oder Veröffentlichungsbestätigung.'))

            layout.addWidget(QLabel(
                'Manuelle Häkchen sind Selbstauskünfte, keine technische Qualitäts- oder Rechtezertifizierung. '
                'Datenstand beim Öffnen der Statistik.'))
            def export_statistics_csv():
                suggested = str(Path.home() / ('MPW_Produktionsstatistik_' + date.today().isoformat() + '.csv'))
                filename, _ = QFileDialog.getSaveFileName(
                    stats, 'Produktionsstatistik als CSV exportieren', suggested, 'CSV-Dateien (*.csv)')
                if not filename:
                    return
                try:
                    with open(filename, 'w', encoding='utf-8-sig', newline='') as stream:
                        writer = csv.writer(stream, delimiter=';', quoting=csv.QUOTE_MINIMAL)
                        writer.writerow(['MPW Produktionsstatistik', 'Aktuelle Filterauswahl', date.today().isoformat()])
                        writer.writerow(['Kennzahl', 'Wert'])
                        writer.writerow(['Songs gesamt', total])
                        writer.writerow(['Durchschnittlicher Fortschritt (%)', f'{avg:.1f}'.replace('.', ',')])
                        writer.writerow(['Offene Arbeitsschritte', open_steps])
                        writer.writerow(['Songs mit vier erfassten Phasen', complete])
                        writer.writerow([])
                        writer.writerow(['Band', 'Songs', 'Durchschnittlicher Fortschritt (%)',
                                         'Offene Schritte', 'Vier Phasen erfasst'])
                        for band_name, (count, progress_sum, pending, finished) in sorted(
                                by_band.items(), key=lambda item: item[0].casefold()):
                            writer.writerow([band_name, count,
                                             f'{progress_sum / count:.1f}'.replace('.', ','),
                                             pending, finished])
                        writer.writerow([])
                        writer.writerow(['Band', 'Song/Projekt', 'Songs', 'Durchschnittlicher Fortschritt (%)',
                                         'Offene Schritte', 'Vier Phasen erfasst'])
                        for (band_name, project_name), (count, progress_sum, pending, finished) in sorted(
                                by_project.items(), key=lambda item: (item[0][0].casefold(), item[0][1].casefold())):
                            writer.writerow([band_name, project_name, count,
                                             f'{progress_sum / count:.1f}'.replace('.', ','), pending, finished])
                        writer.writerow([])
                        writer.writerow(['Songstatus', 'Songs', 'Anteil (%)'])
                        for state, count in sorted(status_counts.items(), key=lambda item: item[0].casefold()):
                            writer.writerow([state, count, f'{count * 100 / total:.1f}'.replace('.', ',')])
                        writer.writerow([])
                        writer.writerow(['Manuelle Abschlussprüfungen', 'Erledigt', manual_done,
                                         'Möglich', 4 * total, 'Songs vollständig', manual_complete])
                        writer.writerow(['Band', 'Song/Projekt', 'Song', 'Audio', 'Cover', 'Rechte', 'Metadaten'])
                        for record in snapshot:
                            done = manual_by_song[int(record[0])]
                            writer.writerow([record[1], record[2], record[3]] + [
                                'Erledigt' if key in done else 'Offen' for key in manual_keys])
                        writer.writerow([])
                        writer.writerow(['Produktionsbereitschaft – getrennte Bewertungen',
                                         'Filter:', readiness_filter.currentText()])
                        writer.writerow(['Band', 'Song/Projekt', 'Song', 'Automatische Phasen (von 4)',
                                         'Manuelle Prüfungen (von 4)', 'Offen gesamt', 'Erfassungsstand'])
                        for record in snapshot:
                            if not readiness_matches(record):
                                continue
                            auto_count = sum(bool(x) for x in record[5:9])
                            manual_count = len(manual_by_song[int(record[0])])
                            outstanding = 8 - auto_count - manual_count
                            writer.writerow([record[1], record[2], record[3], auto_count,
                                             manual_count, outstanding,
                                             '8/8 erfasst' if outstanding == 0 else 'Noch unvollständig'])
                        writer.writerow(['Songs mit 8/8 erfassten Prüfpunkten (Gesamtauswahl)', fully_recorded])
                        writer.writerow([])
                        writer.writerow(['Hinweis', 'Vier erfasste Phasen bestätigen keine Audioqualität oder Veröffentlichung.'])
                    self.message('Statistik-Export', f'Produktionsstatistik exportiert:\n{filename}')
                except (OSError, UnicodeError, csv.Error) as exc:
                    self.error(f'Statistik-Export fehlgeschlagen: {exc}')

            export_stats_button = QPushButton('Statistik als CSV exportieren')
            export_stats_button.setToolTip('Exportiert alle Statistiken der Dashboard-Filterauswahl. Nur der CSV-Abschnitt Produktionsbereitschaft berücksichtigt zusätzlich den Bereitschaftsfilter.')
            export_stats_button.clicked.connect(export_statistics_csv)
            layout.addWidget(export_stats_button)
            close_button = QPushButton('Schließen')
            close_button.clicked.connect(stats.accept)
            layout.addWidget(close_button)
            stats.exec()

        def show_open_tasks():
            """Read-only cross-project list of missing automatic and manual checks."""
            snapshot = list(visible_rows)
            if not snapshot:
                return self.message('Offene Aufgaben', 'Keine Songs in der aktuellen Filterauswahl vorhanden.')
            song_ids = [int(record[0]) for record in snapshot]
            placeholders = ','.join('?' for _ in song_ids)
            manual_rows = self.con.execute(
                f'SELECT song_id, check_key FROM song_manual_checks WHERE song_id IN ({placeholders}) AND completed=1',
                song_ids).fetchall()
            completed_manual = {}
            for sid, key in manual_rows:
                completed_manual.setdefault(int(sid), set()).add(str(key))
            manual_names = [('audio', 'Audioqualität / Peaks prüfen'),
                            ('cover', 'Cover und Bildrechte prüfen'),
                            ('rights', 'Musik- und Nutzungsrechte prüfen'),
                            ('metadata', 'Metadaten / ISRC / UPC prüfen')]
            tasks = []
            for record in snapshot:
                sid, band, project, title = record[:4]
                for part in missing_parts(record):
                    tasks.append((int(sid), str(band), str(project), str(title), 'Automatisch', part))
                done = completed_manual.get(int(sid), set())
                for key, label in manual_names:
                    if key not in done:
                        tasks.append((int(sid), str(band), str(project), str(title), 'Manuell', label))
            task_dialog = QDialog(dialog)
            task_dialog.setWindowTitle('Projektübergreifende offene Produktionsaufgaben – MPW v2.0.23')
            task_dialog.resize(1050, 650)
            task_layout = QVBoxLayout(task_dialog)
            task_count = QLabel(task_dialog)
            task_layout.addWidget(task_count)
            task_layout.addWidget(QLabel('Manuelle Prüfungen sind gespeicherte Häkchen, keine unabhängige Qualitätsbestätigung.'))
            task_filter = QComboBox(task_dialog)
            task_filter.addItems(['Alle offenen Aufgaben', 'Automatische Phasen', 'Manuelle Prüfungen'])
            task_layout.addWidget(task_filter)
            priority_sort = QComboBox(task_dialog)
            priority_sort.addItems(['Priorität: Hoch zuerst', 'Priorität: Niedrig zuerst', 'Band / Projekt / Song'])
            priority_sort.setToolTip('Prioritäten sind Vorschläge aus der Aufgabenart; keine gespeicherten Fristen oder Dringlichkeitsangaben.')
            task_layout.addWidget(priority_sort)
            task_table = QTableWidget(0, 6, task_dialog)
            task_table.setHorizontalHeaderLabels(['Priorität', 'Band', 'Song/Projekt', 'Song', 'Art', 'Offene Aufgabe'])
            task_table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
            task_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
            task_table.setAlternatingRowColors(True)
            task_table.setPalette(table.palette())
            task_table.setStyleSheet(table.styleSheet())
            task_table.horizontalHeader().setStretchLastSection(True)
            task_table.setColumnWidth(0, 105)
            task_table.setColumnWidth(1, 145)
            task_table.setColumnWidth(2, 160)
            task_table.setColumnWidth(3, 180)
            task_table.setColumnWidth(4, 105)
            task_layout.addWidget(task_table, 1)
            def task_priority(task):
                # Suggested work order, not a claim about real deadlines or release readiness.
                kind, label = task[4], task[5]
                if kind == 'Manuell' and ('Rechte' in label or 'Bildrechte' in label):
                    return 0, 'Hoch'
                if kind == 'Automatisch' and label in ('Prompt', 'Medien', 'Release'):
                    return 1, 'Mittel'
                return 2, 'Normal'
            def refresh_tasks():
                mode = task_filter.currentIndex()
                shown = [t for t in tasks if mode == 0 or (mode == 1 and t[4] == 'Automatisch') or (mode == 2 and t[4] == 'Manuell')]
                order = priority_sort.currentIndex()
                if order == 0:
                    shown.sort(key=lambda t: (task_priority(t)[0], t[1].casefold(), t[2].casefold(), t[3].casefold()))
                elif order == 1:
                    shown.sort(key=lambda t: (-task_priority(t)[0], t[1].casefold(), t[2].casefold(), t[3].casefold()))
                else:
                    shown.sort(key=lambda t: (t[1].casefold(), t[2].casefold(), t[3].casefold(), task_priority(t)[0]))
                task_table.setRowCount(len(shown))
                for i, task in enumerate(shown):
                    values = [task_priority(task)[1], *task[1:]]
                    for col, value in enumerate(values):
                        item = QTableWidgetItem(str(value))
                        if col == 3:
                            item.setData(Qt.ItemDataRole.UserRole, task[0])
                        task_table.setItem(i, col, item)
                task_count.setText(f'{len(shown)} von {len(tasks)} offenen Aufgaben · {len(snapshot)} Songs in aktueller Filterauswahl')
            task_filter.currentIndexChanged.connect(refresh_tasks)
            priority_sort.currentIndexChanged.connect(refresh_tasks)
            refresh_tasks()
            def open_task():
                row = task_table.currentRow()
                if row < 0:
                    return self.error('Bitte eine offene Aufgabe auswählen.')
                sid_item = task_table.item(row, 3)
                sid = sid_item.data(Qt.ItemDataRole.UserRole) if sid_item else None
                task_name = task_table.item(row, 5).text()
                task_kind = task_table.item(row, 4).text()
                if task_kind == 'Automatisch' and task_name == 'Medien':
                    tab_name, combo = 'Medien & Player', self.media_song
                elif task_kind == 'Automatisch' and task_name in ('Release', 'Plattform'):
                    tab_name, combo = 'Releases Distri', self.release_song
                else:
                    tab_name, combo = 'Songs & Suno', self.song_select
                index = combo.findData(sid)
                tab_index = next((i for i in range(self.tabs.count()) if self.tab_key(i) == tab_name), -1)
                if index < 0 or tab_index < 0:
                    return self.error('Song im Zielreiter nicht gefunden. Bitte Songlisten aktualisieren.')
                # Close both modal dialogs before changing the main window's tab.
                # Otherwise the nested event loop can leave the dashboard in front
                # and make the navigation appear to have failed.
                task_dialog.accept()
                dialog.accept()
                def finish_task_navigation():
                    # Recheck the selected song; never silently select another one.
                    current_index = combo.findData(sid)
                    target_index = next((i for i in range(self.tabs.count())
                                         if self.tab_key(i) == tab_name), -1)
                    if current_index < 0 or target_index < 0:
                        self.error('Zielreiter oder Song nicht mehr verfügbar. Bitte Songlisten aktualisieren.')
                        return
                    self.tabs.setCurrentIndex(target_index)
                    combo.setCurrentIndex(current_index)
                    self.tabs.setFocus()
                    self.raise_()
                    self.activateWindow()
                QTimer.singleShot(0, finish_task_navigation)
            open_button = QPushButton('Ausgewählte Aufgabe im passenden Reiter öffnen')
            open_button.clicked.connect(open_task)
            task_table.cellDoubleClicked.connect(lambda _r, _c: open_task())
            task_layout.addWidget(open_button)
            close_tasks = QPushButton('Schließen')
            close_tasks.clicked.connect(task_dialog.accept)
            task_layout.addWidget(close_tasks)
            task_dialog.exec()

        open_tasks_button = QPushButton('Projektübergreifende offene Aufgaben anzeigen')
        open_tasks_button.setToolTip('Listet offene automatische Phasen und gespeicherte manuelle Prüfpunkte der aktuell gefilterten Songs auf.')
        open_tasks_button.clicked.connect(show_open_tasks)
        outer.addWidget(open_tasks_button)

        statistics_button = QPushButton('Produktionsstatistik anzeigen')
        statistics_button.setToolTip('Zeigt Kennzahlen pro Band, Song/Projekt und Songstatus der aktuell gefilterten Songs; rein lesend.')
        statistics_button.clicked.connect(show_production_statistics)
        outer.addWidget(statistics_button)

        export_button = QPushButton('Gefilterte Übersicht als CSV exportieren')
        export_button.setToolTip('Exportiert nur die aktuell angezeigten Songs in der gewählten Sortierung als Excel-kompatible CSV (Semikolon, UTF-8 BOM).')
        export_button.clicked.connect(export_visible_csv)
        outer.addWidget(export_button)

        def open_selected(row, column):
            item = table.item(row, 2)
            if item is None: return
            sid = item.data(Qt.ItemDataRole.UserRole)
            index = self.find_song_in_suno(sid)
            if index < 0:
                self.error('Song ist in der aktuellen Songauswahl nicht verfügbar. Bitte zuerst die Songliste aktualisieren.')
                return
            self.song_select.setCurrentIndex(index)
            dialog.accept()

        # Direct navigation: select the row's song in the destination tab before
        # switching. Never silently jump to a different song when it is missing.
        actions = QHBoxLayout()
        actions.addWidget(QLabel('Ausgewählten Song öffnen:'))
        def navigate_to(tab_name, combo):
            row_index = table.currentRow()
            if row_index < 0:
                return self.error('Bitte zuerst eine Song-Zeile in der Tabelle markieren.')
            item = table.item(row_index, 2)
            if item is None:
                return self.error('Bitte einen gültigen Song auswählen.')
            sid = item.data(Qt.ItemDataRole.UserRole)
            index = combo.findData(sid)
            if index < 0:
                return self.error('Dieser Song ist im Zielreiter noch nicht verfügbar. Bitte die Songlisten aktualisieren.')
            tab_index = next((i for i in range(self.tabs.count()) if self.tab_key(i) == tab_name), -1)
            if tab_index < 0:
                return self.error('Der gewünschte Reiter ist nicht vorhanden.')
            combo.setCurrentIndex(index)
            self.tabs.setCurrentIndex(tab_index)
            dialog.accept()
        for button_text, tab_name, combo in [
            ('Songs & Suno', 'Songs & Suno', self.song_select),
            ('Medien & Player', 'Medien & Player', self.media_song),
            ('Releases Distri', 'Releases Distri', self.release_song),
        ]:
            button = QPushButton(button_text)
            button.setToolTip('Markierten Song im Zielreiter auswählen; keine Datenänderung.')
            button.clicked.connect(lambda checked=False, t=tab_name, c=combo: navigate_to(t, c))
            actions.addWidget(button)
        outer.addLayout(actions)

        def show_detail_check():
            """Read-only evidence checklist; never treats presence as certification."""
            selected_row = table.currentRow()
            if selected_row < 0:
                return self.error('Bitte zuerst einen Song in der Produktionsübersicht markieren.')
            selected_item = table.item(selected_row, 2)
            if selected_item is None:
                return self.error('Bitte eine gültige Songzeile auswählen.')
            song_id = selected_item.data(Qt.ItemDataRole.UserRole)
            song = self.con.execute("SELECT title, COALESCE(style, ''), COALESCE(lyrics, '') FROM songs WHERE id=?", (song_id,)).fetchone()
            if song is None:
                return self.error('Der Song ist nicht mehr vorhanden. Bitte die Übersicht erneut öffnen.')
            assets = self.con.execute('SELECT kind, original_name FROM media_assets WHERE song_id=?', (song_id,)).fetchall()
            releases_detail = self.con.execute('SELECT id, distributor, release_date, isrc, upc FROM releases WHERE song_id=?', (song_id,)).fetchall()
            platforms_detail = self.con.execute("""SELECT rp.platform, rp.status, rp.url FROM release_platforms rp
                JOIN releases r ON r.id=rp.release_id WHERE r.song_id=?""", (song_id,)).fetchall()
            audio = [a for a in assets if a[0] == 'Audio']
            covers = [a for a in assets if a[0] == 'Cover']
            issues = []
            good = []
            if song[1].strip() and song[2].strip():
                good.append('Style und Lyrics sind beide ausgefüllt.')
            else:
                issues.append('Style und/oder Lyrics fehlen.')
            if audio:
                good.append(f'{len(audio)} Audiodatei(en) zugeordnet; Masterqualität nicht automatisch geprüft.')
            else:
                issues.append('Keine Audiodatei in der MPW-Medienverwaltung zugeordnet.')
            if covers:
                good.append(f'{len(covers)} Coverdatei(en) zugeordnet; Maße und Distributorkonformität nicht geprüft.')
            else:
                issues.append('Kein Cover in der MPW-Medienverwaltung zugeordnet.')
            if not releases_detail:
                issues.append('Kein Release angelegt.')
            else:
                for rid, distributor, release_date, isrc, upc in releases_detail:
                    label = f'Release #{rid}'
                    for field, value in [('Distributor', distributor), ('Veröffentlichungsdatum', release_date), ('ISRC', isrc), ('UPC/EAN', upc)]:
                        if not str(value or '').strip():
                            issues.append(f'{label}: {field} fehlt.')
                    if all(str(v or '').strip() for v in (distributor, release_date, isrc, upc)):
                        good.append(f'{label}: Distributor, Datum, ISRC und UPC/EAN erfasst; Registrierung nicht verifiziert.')
            if not platforms_detail:
                issues.append('Keine Streamingplattform zugeordnet.')
            else:
                without_link = [name for name, status, url in platforms_detail if not str(url or '').strip()]
                if without_link:
                    issues.append('Plattformlink fehlt bei: ' + ', '.join(without_link))
                good.append(f'{len(platforms_detail)} Plattformzuordnung(en) vorhanden; Live-Status nicht extern geprüft.')
            detail = QDialog(dialog)
            detail.setWindowTitle('Detaillierte Produktionskontrolle – ' + str(song[0]))
            detail.resize(740, 520)
            layout = QVBoxLayout(detail)
            report = QTextBrowser(detail)
            theme_detail = self.current_color_theme()
            report.setStyleSheet('QTextBrowser { background-color: %s; color: %s; border: 1px solid %s; }' % (
                theme_detail['surface'], theme_detail['foreground'], theme_detail['border']))
            def lines(items):
                return ''.join('<li>' + html.escape(str(item)) + '</li>' for item in items) or '<li>Keine</li>'
            report.setHtml('<h3>' + html.escape(str(song[0])) + '</h3>'
                           '<h4>Offene oder zu prüfende Angaben</h4><ul>' + lines(issues) + '</ul>'
                           '<h4>Bereits erfasste Angaben</h4><ul>' + lines(good) + '</ul>'
                           '<p><b>Wichtig:</b> Die Kontrolle liest nur MPW-Daten. Audioqualität (LUFS/True Peak),'
                           ' Coverabmessungen, Rechte, Credits, ISRC-/UPC-Registrierung und reale Veröffentlichung'
                           ' werden hier nicht verifiziert.</p>')
            layout.addWidget(report)
            # Each open finding can be opened directly, without manually
            # searching for the song in another tab. Keep the checklist read-only.
            if issues:
                layout.addWidget(QLabel('Offenen Punkt auswählen und bearbeiten:'))
                issue_select = QComboBox(detail)
                for issue in issues:
                    issue_select.addItem(issue)
                issue_select.setToolTip('Wählt einen offenen Punkt; die Daten werden nicht automatisch geändert.')
                layout.addWidget(issue_select)
                def edit_selected_issue():
                    issue = issue_select.currentText()
                    if not issue:
                        return
                    if issue.startswith('Style'):
                        target, combo, focus_widget = 'Songs & Suno', self.song_select, self.style
                    elif 'Audiodatei' in issue or 'Cover' in issue:
                        target, combo, focus_widget = 'Medien & Player', self.media_song, self.media_song
                    else:
                        target, combo = 'Releases Distri', self.release_song
                        if 'Distributor' in issue:
                            focus_widget = self.release_dist
                        elif 'Veröffentlichungsdatum' in issue:
                            focus_widget = self.release_date
                        elif 'ISRC' in issue:
                            focus_widget = self.release_isrc
                        elif 'UPC/EAN' in issue:
                            focus_widget = self.release_upc
                        else:
                            focus_widget = self.release_list
                    # Resolve the exact song before closing either dialog.
                    idx = combo.findData(song_id)
                    tab_idx = next((i for i in range(self.tabs.count()) if self.tab_key(i) == target), -1)
                    if idx < 0 or tab_idx < 0:
                        return self.error('Song oder Zielreiter nicht verfügbar. Bitte Songlisten aktualisieren.')
                    combo.setCurrentIndex(idx)
                    self.tabs.setCurrentIndex(tab_idx)
                    detail.accept()
                    dialog.accept()
                    focus_widget.setFocus()
                edit_button = QPushButton('Ausgewählten offenen Punkt bearbeiten')
                edit_button.setToolTip('Öffnet den zugehörigen Reiter mit vorausgewähltem Song und setzt den Fokus auf das passende Feld, soweit vorhanden.')
                edit_button.clicked.connect(edit_selected_issue)
                layout.addWidget(edit_button)
            close_detail = QPushButton('Schließen')
            close_detail.clicked.connect(detail.accept)
            layout.addWidget(close_detail)
            detail.exec()

        detail_button = QPushButton('Detaillierte Produktionskontrolle für markierten Song')
        detail_button.setToolTip('Prüft Audio- und Coverzuordnung sowie Release-Metadaten; rein lesend, ohne Qualitätszertifizierung.')
        detail_button.clicked.connect(show_detail_check)
        outer.addWidget(detail_button)

        search.textChanged.connect(refresh)
        status_filter.currentIndexChanged.connect(refresh)
        sort_filter.currentIndexChanged.connect(refresh)
        band_filter.currentIndexChanged.connect(refresh)
        song_status_filter.currentIndexChanged.connect(refresh)
        readiness_filter.currentIndexChanged.connect(refresh)
        def click_next_step(row, column):
            if column != 8:
                return
            record_item = table.item(row, 2)
            if record_item is None:
                return
            sid = record_item.data(Qt.ItemDataRole.UserRole)
            record = next((entry for entry in rows if entry[0] == sid), None)
            if record is None:
                return self.error('Der Song wurde in der Übersicht nicht gefunden.')
            missing = missing_parts(record)
            if not missing:
                return self.message('Abschlussprüfung', 'Alle erfassten Produktionsphasen sind vorhanden. Bitte Audioqualität, Cover, Rechte und Metadaten manuell prüfen.')
            # When several production phases are incomplete, let the user
            # choose the actual target instead of always opening the first one.
            # With exactly one missing phase, navigate immediately.
            first = missing[0]
            if len(missing) > 1:
                labels = {
                    'Prompt': 'Prompt – Style und Lyrics ergänzen',
                    'Medien': 'Medien – lokale Dateien zuordnen',
                    'Release': 'Release – Veröffentlichung anlegen',
                    'Plattform': 'Plattform – Streamingplattform erfassen',
                }
                choices = [labels[part] for part in missing]
                choice, accepted = QInputDialog.getItem(
                    dialog, 'Offenen Arbeitsschritt auswählen',
                    'Für diesen Song sind mehrere Arbeitsschritte offen.\nWelchen möchtest du bearbeiten?',
                    choices, 0, False)
                if not accepted:
                    return
                first = missing[choices.index(choice)]
            if first == 'Prompt':
                navigate_to('Songs & Suno', self.song_select)
                if self.tab_key(self.tabs.currentIndex()) == 'Songs & Suno':
                    self.style.setFocus()
            elif first == 'Medien':
                navigate_to('Medien & Player', self.media_song)
                if self.tab_key(self.tabs.currentIndex()) == 'Medien & Player':
                    self.media_song.setFocus()
            else:
                navigate_to('Releases Distri', self.release_song)
                if self.tab_key(self.tabs.currentIndex()) == 'Releases Distri':
                    (self.release_dist if first == 'Release' else self.release_list).setFocus()

        table.cellClicked.connect(click_next_step)
        table.cellDoubleClicked.connect(lambda row, column: open_selected(row, column) if column != 8 else None)
        close = QPushButton('Schließen'); close.clicked.connect(dialog.accept)
        outer.addWidget(close)
        refresh()
        dialog.exec()

    def show_song_workflow(self):
        """Read-only song overview; never modifies a project or a release."""
        sid = self.song_select.currentData()
        if sid is None:
            return self.error('Bitte zuerst einen Song unter Songs & Suno auswählen.')
        row = self.con.execute('''
            SELECT s.title, s.status, s.style, s.lyrics, p.name, b.name
            FROM songs s JOIN projects p ON p.id=s.project_id
            JOIN bands b ON b.id=p.band_id WHERE s.id=?
        ''', (sid,)).fetchone()
        if row is None:
            return self.error('Der ausgewählte Song wurde nicht gefunden.')
        title, status, style, lyrics, project, band = row
        versions = self.con.execute('SELECT COUNT(*) FROM prompt_versions WHERE song_id=?', (sid,)).fetchone()[0]
        assets = self.con.execute('SELECT kind,COUNT(*) FROM media_assets WHERE song_id=? GROUP BY kind', (sid,)).fetchall()
        asset_total = sum(count for _, count in assets)
        links = self.con.execute('SELECT COUNT(*) FROM media_links WHERE song_id=?', (sid,)).fetchone()[0]
        releases = self.con.execute('SELECT id,distributor,release_date FROM releases WHERE song_id=? ORDER BY id DESC', (sid,)).fetchall()
        platform_count = 0
        if releases:
            platform_count = self.con.execute(
                'SELECT COUNT(*) FROM release_platforms WHERE release_id IN (SELECT id FROM releases WHERE song_id=?)',
                (sid,)).fetchone()[0]
        has_prompt = bool((style or '').strip() or (lyrics or '').strip())
        stages = [
            ('1. Song & Projekt', True, f'Band: {band} | Projekt: {project} | Status: {status or "In Bearbeitung"}'),
            ('2. Suno-Prompt', has_prompt, f'Aktiver Prompt: {"vorhanden" if has_prompt else "noch leer"} | Archivierte Versionen: {versions}'),
            ('3. Medien', asset_total > 0, f'Importierte Dateien: {asset_total} | Externe Links: {links}'),
            ('4. Veröffentlichung', bool(releases), f'Releases: {len(releases)} | Plattform-Einträge: {platform_count}'),
        ]
        # Vorschläge ausschließlich aus gespeicherten MPW-Daten ableiten. Keine Änderungen.
        next_steps = []
        if not has_prompt:
            next_steps.append(('AI Prompt Launcher', 'Style und Lyrics für diesen Song anlegen oder übernehmen.'))
        if not asset_total:
            next_steps.append(('Medien & Player', 'Mindestens eine lokale Mediendatei importieren und dem Song zuordnen.'))
        if not releases:
            next_steps.append(('Releases Distri', 'Release-Datensatz anlegen, sobald die Veröffentlichung vorbereitet wird.'))
        elif not platform_count:
            next_steps.append(('Releases Distri', 'Für den vorhandenen Release eine Streamingplattform mit Status erfassen.'))
        if not next_steps:
            next_steps.append((None, 'Alle vier Produktionsphasen enthalten Daten. Vor einer Veröffentlichung Audioqualität, Metadaten und Plattformstatus manuell prüfen.'))
        dialog = QDialog(self)
        dialog.setWindowTitle('Produktions-Workflow & nächste Schritte – ' + str(title))
        dialog.resize(790, 600)
        outer = QVBoxLayout(dialog)
        heading = QLabel('Produktionsübersicht: ' + str(title))
        heading.setWordWrap(True)
        outer.addWidget(heading)
        info = QTextBrowser(dialog)
        rows = ['<h3>Songfortschritt</h3>']
        for label, done, detail in stages:
            rows.append('<p><b>' + ('✓ ' if done else '○ ') + html.escape(label) + '</b><br>' + html.escape(detail) + '</p>')
        rows.append('<h3>Nächste empfohlene Arbeitsschritte</h3><ol>')
        for target, instruction in next_steps:
            rows.append('<li>' + html.escape(instruction) +
                        ((' <i>(Bereich: ' + html.escape(target) + ')</i>') if target else '') + '</li>')
        rows.append('</ol>')
        rows.append('<p><i>Die Vorschläge beruhen nur auf gespeicherten Einträgen; ' 
                    'sie sind keine Qualitäts- oder Vollständigkeitsgarantie. ' 
                    'Es werden keine Aufgaben automatisch gespeichert.</i></p>')
        rows.append('<p><i>Diese Übersicht liest nur vorhandene MPW-Daten. '
                    'Sie prüft weder Audioqualität noch die tatsächliche Veröffentlichung auf Streamingplattformen.</i></p>')
        info.setHtml(''.join(rows))
        outer.addWidget(info)
        navigation = QHBoxLayout()
        for label, tab_name in [('Prompt bearbeiten', 'AI Prompt Launcher'),
                                ('Medien öffnen', 'Medien & Player'),
                                ('Releases öffnen', 'Releases Distri')]:
            button = QPushButton(label)
            def go_to_tab(checked=False, name=tab_name):
                for index in range(self.tabs.count()):
                    if self.tab_key(index) == name:
                        self.tabs.setCurrentIndex(index)
                        dialog.accept()
                        return
            button.clicked.connect(go_to_tab)
            navigation.addWidget(button)
        outer.addLayout(navigation)
        close = QPushButton('Schließen')
        close.clicked.connect(dialog.accept)
        outer.addWidget(close)
        dialog.exec()

    def add_media(self):
        sid = self.media_song.currentData()
        if sid is None: return self.error('Bitte zuerst einen Song-Eintrag zum ausgewählten Projekt anlegen.')
        path,_ = QFileDialog.getOpenFileName(self,'Mediendatei importieren')
        if not path: return
        try:
            import_asset(self.con,ROOT,sid,self.media_kind.currentText(),path,self.media_label.text().strip(),self.band_root_directory())
            self.refresh_media()
        except (ValueError,OSError,sqlite3.Error) as exc: self.error(exc)

    def add_media_link(self):
        sid = self.media_song.currentData(); url = self.media_url.text().strip(); parsed = urlparse(url)
        if sid is None: return self.error('Bitte zuerst einen Song-Eintrag zum ausgewählten Projekt anlegen.')
        if parsed.scheme not in ('http','https') or not parsed.netloc or parsed.username or parsed.password:
            return self.error('Bitte gültigen HTTP(S)-Link eingeben.')
        try:
            with self.con:
                self.con.execute('INSERT INTO media_links(song_id,platform,url,label) VALUES(?,?,?,?)',
                    (sid,self.media_platform.currentText(),url,self.media_label.text().strip()))
            self.refresh_media()
        except sqlite3.IntegrityError: self.error('Dieser Link ist bereits gespeichert.')

    def select_media_link(self, current, previous=None):
        if current:
            self.media_url.setText(current.data(Qt.ItemDataRole.UserRole))
            platform = current.data(Qt.ItemDataRole.UserRole + 1)
            index = self.media_platform.findText(platform)
            if index >= 0: self.media_platform.setCurrentIndex(index)
            self.media_label.setText(current.data(Qt.ItemDataRole.UserRole + 2) or '')

    def copy_media_link(self):
        item = self.media_link_list.currentItem()
        if not item: return self.error('Bitte einen gespeicherten Link auswählen.')
        QApplication.clipboard().setText(item.data(Qt.ItemDataRole.UserRole))
        self.message('Link kopiert', 'Der Plattform-Link wurde in die Zwischenablage kopiert.')

    def show_media_link_context_menu(self, position):
        """Show delete action only for a link actually clicked with the right mouse button."""
        item = self.media_link_list.itemAt(position)
        if item is None:
            return
        self.media_link_list.setCurrentItem(item)
        menu = QMenu(self.media_link_list)
        delete_action = menu.addAction(self.translated_context_label('Link löschen'))
        chosen = menu.exec(self.media_link_list.viewport().mapToGlobal(position))
        if chosen == delete_action:
            self.delete_media_link()

