    def delete_media_link(self):
        item = self.media_link_list.currentItem()
        sid = self.media_song.currentData()
        if not item or sid is None: return self.error(self.media_feedback_text(0))
        url = item.data(Qt.ItemDataRole.UserRole)
        if QMessageBox.question(self, self.localized_dialog_title('Link entfernen'),
            self.media_confirmation_text('delete'),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes: return
        with self.con:
            self.con.execute('DELETE FROM media_links WHERE song_id=? AND url=?', (sid, url))
        self.refresh_media()

    def open_media_link(self):
        item = self.media_link_list.currentItem()
        if not item: return self.error(self.media_feedback_text(1))
        from PySide6.QtGui import QDesktopServices
        if not QDesktopServices.openUrl(QUrl(item.data(Qt.ItemDataRole.UserRole))):
            self.error(self.media_feedback_text(2))

    def import_media_url(self):
        sid = self.media_song.currentData(); url = self.media_url.text().strip(); parsed = urlparse(url)
        if sid is None: return self.error(self.media_feedback_text(3))
        if parsed.scheme != 'https' or not parsed.netloc or parsed.username or parsed.password:
            return self.error(self.media_feedback_text(4))
        suffix = Path(parsed.path).suffix.lower(); kind = self.media_kind.currentText()
        if suffix not in KINDS[kind]:
            return self.error(self.media_feedback_text(5))
        if QMessageBox.question(self,self.localized_dialog_title('Import bestätigen'),
            self.media_confirmation_text('import'),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes: return
        try:
            request = urllib.request.Request(url,headers={'User-Agent':'MPW/0.4.9'})
            with urllib.request.urlopen(request,timeout=20) as response:
                if urlparse(response.geturl()).scheme != 'https': raise ValueError('Unsichere Weiterleitung.')
                length = response.headers.get('Content-Length')
                if length and int(length)>200*1024*1024: raise ValueError('Datei zu groß (max. 200 MB).')
                with tempfile.TemporaryDirectory() as tmp:
                    path = Path(tmp)/('download'+suffix); size=0
                    with path.open('wb') as out:
                        while True:
                            block=response.read(1024*1024)
                            if not block: break
                            size+=len(block)
                            if size>200*1024*1024: raise ValueError('Datei zu groß (max. 200 MB).')
                            out.write(block)
                    if not size: raise ValueError('Leere Datei.')
                    import_asset(self.con,ROOT,sid,kind,path,self.media_label.text().strip() or Path(parsed.path).stem,self.band_root_directory())
            self.refresh_media(); self.message(self.media_feedback_text(6), self.media_feedback_text(7))
        except (ValueError,OSError,sqlite3.Error,urllib.error.URLError) as exc: self.error(exc)

