    def audit_media_references(self):
        """Read-only audit of legacy media_assets paths; do not scan or modify files."""
        rows = self.con.execute('''SELECT m.id, b.name, p.name, s.title, m.relative_path
            FROM media_assets m JOIN songs s ON s.id=m.song_id
            JOIN projects p ON p.id=s.project_id JOIN bands b ON b.id=p.band_id
            ORDER BY b.name, p.name, s.title, m.id''').fetchall()
        missing, unsafe, found = [], [], 0
        root = ROOT.resolve()
        for asset_id, band, project, title, relative in rows:
            try:
                candidate = (ROOT / relative).resolve()
                if not candidate.is_relative_to(root):
                    unsafe.append(f'#{asset_id} | {band} / {project} / {title} | {relative}')
                elif not candidate.is_file():
                    missing.append(f'#{asset_id} | {band} / {project} / {title} | {relative}')
                else:
                    found += 1
            except (OSError, ValueError, TypeError) as exc:
                unsafe.append(f'#{asset_id} | {band} / {project} / {title} | {relative} ({exc})')
        lines = [self.media_audit_text(0, total=len(rows)), self.media_audit_text(1, found=found),
                 self.media_audit_text(2, missing=len(missing)), self.media_audit_text(3, unsafe=len(unsafe)),
                 '', self.media_audit_text(4), self.media_audit_text(5), self.media_audit_text(6)]
        for heading, items in [(self.media_audit_text(7), missing), (self.media_audit_text(8), unsafe)]:
            if items: lines.extend(['', heading, *items[:1000]])
        dialog = QDialog(self); dialog.setWindowTitle(self.media_audit_text(9))
        dialog.resize(850, 560); layout = QVBoxLayout(dialog)
        report = QTextEdit(); report.setReadOnly(True); report.setPlainText('\n'.join(lines)); layout.addWidget(report)
        actions = QHBoxLayout(); save = QPushButton(self.media_audit_text(10))
        def export_report():
            path, _ = QFileDialog.getSaveFileName(dialog, self.media_audit_text(11),
                'MPW_Medienverknuepfungen.txt', 'Textdateien (*.txt)')
            if path:
                try: Path(path).write_text(report.toPlainText(), encoding='utf-8')
                except OSError as exc: self.error(exc)
        save.clicked.connect(export_report); actions.addWidget(save)
        close = QPushButton(self.media_audit_text(12)); close.clicked.connect(dialog.accept); actions.addWidget(close)
        layout.addLayout(actions); dialog.exec()

    def refresh_media(self, *args):
        self.media_list.clear(); self.media_link_list.clear(); self.media_rows = []
        sid = self.media_song.currentData()
        if sid is None: return
        from PySide6.QtWidgets import QListWidgetItem
        for platform,url,label in self.con.execute('SELECT platform,url,label FROM media_links WHERE song_id=? ORDER BY id DESC',(sid,)):
            item = QListWidgetItem(f'{platform} · {label or url}')
            item.setData(Qt.ItemDataRole.UserRole,url); item.setData(Qt.ItemDataRole.UserRole + 1,platform); item.setData(Qt.ItemDataRole.UserRole + 2,label); item.setToolTip(url)
            self.media_link_list.addItem(item)
        self.media_rows = filesystem_song_assets(self.con, ROOT, sid, self.band_root_directory())
        # Legacy database entries remain accessible until the user copies their originals.
        for kind, label, name, size, rel in self.con.execute('SELECT kind,label,original_name,bytes,relative_path FROM media_assets WHERE song_id=? ORDER BY id DESC',(sid,)):
            legacy = ROOT / rel
            if legacy.is_file():
                self.media_rows.append((kind, label + ' [Altbestand]', name, size, str(legacy)))
        for kind,label,name,size,_ in self.media_rows:
            self.media_list.addItem(f'{kind} · {name} · {size/1048576:.1f} MB')

    def selected_media(self):
        row = self.media_list.currentRow()
        if row<0 or row>=len(self.media_rows): return None
        candidate = Path(self.media_rows[row][4]).resolve()
        allowed = (ROOT.resolve(), self.band_root_directory().resolve())
        if not any(candidate.is_relative_to(base) for base in allowed): return None
        return candidate

