    def _audio_analysis_finished(self, process, code, status, path):
        if process is not self._audio_analysis_process:
            return
        self._audio_analysis_process = None
        self.audio_analyze_button.setEnabled(True)
        self.audio_qc_button.setEnabled(True)
        output = bytes(process.readAllStandardError()).decode('utf-8', errors='replace')
        process.deleteLater()
        matches = re.findall(r'\{\s*"input_i"\s*:\s*"[^"\n]+".*?\}', output, re.DOTALL)
        error_text = self.AUDIO_FFMPEG_ERRORS.get(self.effective_language(), self.AUDIO_FFMPEG_ERRORS['de'])
        if code != 0 or not matches:
            self._show_audio_result(error_text[2], error_text[3] + output[-2500:])
            return
        try:
            result = json.loads(matches[-1])
            def metric(key):
                value = float(result[key])
                return f'{value:.2f}' if abs(value) < 10000 else error_text[5]
            peak = float(result['input_tp'])
            loudness = float(result['input_i'])
            lra = float(result['input_lra'])
            threshold = float(result['input_thresh'])
            # Streaming reference values are guidance, not universal mastering limits.
            # EBU R128 input_thresh is a measurement gate, not a mastering target.
            def measured(value, unit):
                return f'{value:.2f} {unit}' if math.isfinite(value) and abs(value) < 10000 else error_text[5]
            if not all(math.isfinite(v) and abs(v) < 10000 for v in (loudness, peak, lra, threshold)):
                raise ValueError('Unplausible oder nicht endliche FFmpeg-Messwerte')
            if -16 <= loudness <= -12:
                loudness_rating = 'IM ORIENTIERUNGSBEREICH'
                loudness_note = 'Nahe dem beispielhaften Streaming-Bezugswert von -14 LUFS.'
            elif loudness > -12:
                loudness_rating = 'LAUTER ALS ORIENTIERUNGSWERT'
                loudness_note = ('Der Streamingdienst kann die Wiedergabelautstärke absenken. '
                                 'Das ist allein kein Qualitätsfehler; bei sehr hohen Pegeln Dynamik prüfen.')
            else:
                loudness_rating = 'LEISER ALS ORIENTIERUNGSWERT'
                loudness_note = ('Die Wiedergabe kann leiser bleiben oder, je nach Plattform und '
                                 'Einstellungen, angehoben werden. Dynamik und Genre berücksichtigen.')
            if peak >= 0:
                peak_rating = 'KRITISCH'
                peak_note = 'True Peak erreicht oder überschreitet 0 dBTP: Intersample-Clipping möglich.'
            elif peak > -1:
                peak_rating = 'PRÜFEN'
                peak_note = 'Weniger als 1 dB Abstand zu 0 dBTP; bei verlustbehafteter Kodierung können Überschreitungen entstehen.'
            else:
                peak_rating = 'IM ORIENTIERUNGSBEREICH'
                peak_note = 'Mindestens 1 dB True-Peak-Reserve; für manche Plattformen ist mehr Reserve sinnvoll.'
            if lra < 4:
                lra_rating = 'GERINGE LAUTHEITSSCHWANKUNG'
                lra_note = 'Kann bei dicht produziertem Metal oder Pop beabsichtigt sein; auf Ermüdung achten.'
            elif lra <= 12:
                lra_rating = 'MODERATE LAUTHEITSSCHWANKUNG'
                lra_note = 'Häufig gut handhabbarer Bereich; keine allgemeingültige Qualitätsnorm.'
            else:
                lra_rating = 'HOHE LAUTHEITSSCHWANKUNG'
                lra_note = 'Kann bei Blues, Akustik oder orchestraler Musik gewünscht sein; leise Passagen prüfen.'
            if threshold > loudness:
                threshold_rating = 'UNPLAUSIBEL – PRÜFEN'
                threshold_note = 'Die gemeldete relative Messschwelle liegt oberhalb der integrierten Lautheit.'
            else:
                threshold_rating = 'INFORMATIV – KEIN SOLLWERT'
                threshold_note = ('EBU-R128-Gating-Schwelle zur Berechnung der Lautheit. '
                                  'Sie hat keinen universellen optimalen Mastering-Wert.')
            findings = []
            if peak >= 0:
                findings.append('True Peak kritisch: Master auf mögliche Übersteuerung prüfen.')
            elif peak > -1:
                findings.append('True-Peak-Reserve unter 1 dB: für Streaming-Kodierung überprüfen.')
            if loudness > -9:
                findings.append('Sehr lautes Master: mögliche Überkompression und Verzerrungen prüfen.')
            if lra < 4:
                findings.append('Geringe LRA: musikalische Dynamik bewusst gegenprüfen.')
            if threshold > loudness:
                findings.append('Lautheitsschwelle wirkt unplausibel: FFmpeg-Ausgabe kontrollieren.')
            if not findings:
                findings.append('Keine offensichtliche Warnung aus diesen vier Kennzahlen.')
            findings.append('Die Kennzahlen erkennen keine einzelnen Klicks, Sample-Clips oder Codec-Artefakte zuverlässig.')
            language = self.effective_language()
            translations = self.AUDIO_R128_ASSESSMENT_I18N.get(language, {})
            def tr(value):
                return translations.get(value, value)
            loudness_rating, loudness_note = tr(loudness_rating), tr(loudness_note)
            peak_rating, peak_note = tr(peak_rating), tr(peak_note)
            lra_rating, lra_note = tr(lra_rating), tr(lra_note)
            threshold_rating, threshold_note = tr(threshold_rating), tr(threshold_note)
            findings = [tr(item) for item in findings]
            report = (
                f'Datei: {path.name}\n'
                'AUDIOQUALITÄT – SOLL-IST-VERGLEICH\n'
                'Referenzprofil: Streaming-Orientierung (kein verbindlicher Plattformstandard)\n'
                '------------------------------------------------------------\n'
                f'Integrierte Lautheit: {measured(loudness, "LUFS")}\n'
                'Richtwert: ca. -14 LUFS (Orientierungsbereich -16 bis -12 LUFS)\n'
                f'Bewertung: {loudness_rating}\n{loudness_note}\n\n'
                f'True Peak: {measured(peak, "dBTP")}\n'
                'Richtwert: höchstens -1.00 dBTP; 0 dBTP ist kritisch\n'
                f'Bewertung: {peak_rating}\n{peak_note}\n\n'
                f'Lautheitsdynamik (LRA): {measured(lra, "LU")}\n'
                'Orientierung: 4–12 LU, stark genre- und arrangementabhängig\n'
                f'Bewertung: {lra_rating}\n{lra_note}\n\n'
                f'Lautheitsschwelle: {measured(threshold, "LUFS")}\n'
                'Optimalwert: keiner (Messparameter, kein Mastering-Ziel)\n'
                f'Bewertung: {threshold_rating}\n{threshold_note}\n\n'
                'GESAMTAUSWERTUNG\n'
                + '\n'.join('• ' + item for item in findings)
                + '\n\nWichtig: Plattform-Normalisierung ist keine Aufforderung, '
                  'jedes Master auf -14 LUFS zu begrenzen. Zielwerte hängen von '
                  'Genre, Plattform, Format und gewünschter Dynamik ab.\n'
                  'Messung: FFmpeg loudnorm (EBU R128), Quelldatei unverändert.'
            )
            report_labels = self.AUDIO_R128_REPORT_I18N.get(language)
            if report_labels:
                for original, localized in zip(self.AUDIO_R128_REPORT_DE, report_labels):
                    report = report.replace(original, localized)
            title = report_labels[-1] if report_labels else 'Audioqualität – Soll-Ist-Vergleich'
            self._show_audio_result(title, report)
        except (ValueError, KeyError, TypeError) as exc:
            self._show_audio_result(error_text[2], f'{error_text[4]}{exc}')

    def open_media(self):
        path = self.selected_media()
        if not path or not path.is_file(): return self.error('Keine gültige Mediendatei ausgewählt.')
        from PySide6.QtGui import QDesktopServices
        if not QDesktopServices.openUrl(QUrl.fromLocalFile(str(path))):
            self.error('Datei konnte nicht mit der Standardanwendung geöffnet werden.')

