    def release_edit_text(self, index, **values):
        lang = self.effective_language()
        template = self.RELEASE_EDIT_TEXTS.get(lang, self.RELEASE_EDIT_DE)[index]
        return template.format(**values)

    def add_release(self):
        sid = self.release_song.currentData()
        dist = self.release_dist.currentText().strip()
        if sid is None or not dist:
            return self.error(self.release_edit_text(0))
        raw_isrc = self.release_isrc.text().strip()
        isrc = re.sub(r'[\s-]+', '', raw_isrc).upper()
        if isrc and not re.fullmatch(r'[A-Z]{2}[A-Z0-9]{3}[0-9]{7}', isrc):
            return self.error(self.release_edit_text(1))
        d = self.release_date.date().toString('yyyy-MM-dd') if self.release_date_enabled.isChecked() else None
        upc = self.release_upc.text().strip()
        if isrc:
            matches = self.con.execute('''
                SELECT r.id, r.song_id, s.title, r.distributor, r.release_date, r.upc
                FROM releases r JOIN songs s ON s.id = r.song_id
                WHERE UPPER(REPLACE(REPLACE(TRIM(COALESCE(r.isrc,'')), '-', ''), ' ', '')) = ?
                ORDER BY r.id
            ''', (isrc,)).fetchall()
            if matches:
                # Auch bei mehrfach vorhandener ISRC: Datensatz gezielt auswählen,
                # statt die Aktualisierung mit einem Hinweis abzubrechen.
                match = matches[0]
                if len(matches) > 1:
                    choices = [f'#{r[0]} | {r[2]} | {r[3]} | {r[4] or self.release_edit_text(2)}' for r in matches]
                    selected, ok = QInputDialog.getItem(
                        self, self.release_edit_text(3),
                        self.release_edit_text(4),
                        choices, 0, False)
                    if not ok:
                        return
                    match = matches[choices.index(selected)]
                rid, old_sid, old_title, old_dist, old_date, old_upc = match
                answer = QMessageBox.question(
                    self, self.localized_dialog_title(self.release_edit_text(5)),
                    (self.release_edit_text(6) + '\n\n'
                     + f'ISRC: {isrc}\nDatensatz: #{rid}\nSong: {old_title}\n'
                     + f'Distributor: {old_dist}\n\n'
                     + self.release_edit_text(7) + '\n'
                     + self.release_edit_text(8)),
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                    QMessageBox.StandardButton.No)
                if answer != QMessageBox.StandardButton.Yes:
                    return
                with self.con:
                    self.con.execute('''UPDATE releases
                        SET song_id=?, distributor=?, release_date=?, isrc=?, upc=? WHERE id=?''',
                        (sid, dist, d, isrc, upc, rid))
                self.refresh_releases()
                for i in range(self.release_list.count()):
                    if self.release_list.item(i).data(Qt.ItemDataRole.UserRole) == rid:
                        self.release_list.setCurrentRow(i)
                        break
                self.message(self.release_edit_text(9), self.release_edit_text(10, rid=rid))
                return
        with self.con:
            cur = self.con.execute('''INSERT INTO releases(song_id,distributor,release_date,isrc,upc)
                VALUES(?,?,?,?,?)''', (sid, dist, d, isrc or None, upc))
        self.refresh_releases()
        for i in range(self.release_list.count()):
            if self.release_list.item(i).data(Qt.ItemDataRole.UserRole) == cur.lastrowid:
                self.release_list.setCurrentRow(i)
                break

    def refresh_releases(self, *args):
        self.release_list.clear()
        sid = self.release_song.currentData()
        if sid is None: return
        for rid,dist,d,isrc in self.con.execute('SELECT id,distributor,release_date,isrc FROM releases WHERE song_id=? ORDER BY id DESC',(sid,)):
            from PySide6.QtWidgets import QListWidgetItem
            item = QListWidgetItem(f'#{rid} · {dist} · {d or self.release_edit_text(2)} · ISRC: {isrc or "–"}')
            item.setData(Qt.ItemDataRole.UserRole,rid); self.release_list.addItem(item)
        self.refresh_platforms()

    def selected_release(self):
        item = self.release_list.currentItem()
        return item.data(Qt.ItemDataRole.UserRole) if item else None

    # Alpha 21 Preview 30: localized status labels with canonical persisted state values.
    PLATFORM_STATUS_LABELS = {
        'en': ('Planned', 'Submitted', 'Under review', 'Published', 'Failed'),
        'fr': ('Planifié', 'Soumis', 'En cours de vérification', 'Publié', 'Échec'),
        'es': ('Planificado', 'Enviado', 'En revisión', 'Publicado', 'Fallido'),
        'it': ('Pianificato', 'Inviato', 'In verifica', 'Pubblicato', 'Non riuscito'),
    }

    def refresh_platform_status_choices(self):
        """Refresh visible status labels without changing selected canonical value."""
        combo = getattr(self, 'platform_status', None)
        if combo is None:
            return
        current = combo.currentData()
        combo.blockSignals(True)
        try:
            for index, canonical in enumerate(STATES):
                if index < combo.count():
                    combo.setItemData(index, canonical)
                    combo.setItemText(index, self.localized_platform_status(canonical))
            if current in STATES:
                combo.setCurrentIndex(STATES.index(current))
        finally:
            combo.blockSignals(False)

    def localized_platform_status(self, status):
        try:
            index = STATES.index(status)
        except ValueError:
            return status
        return self.PLATFORM_STATUS_LABELS.get(self.effective_language(), STATES)[index]

    def refresh_platforms(self, *args):
        self.platform_list.clear(); rid = self.selected_release()
        if rid is None: return
        for platform,status,url in self.con.execute('SELECT platform,status,url FROM release_platforms WHERE release_id=? ORDER BY platform',(rid,)):
            self.platform_list.addItem(f'{platform} · {self.localized_platform_status(status)} · {url or self.release_edit_text(11)}')

    def save_platform(self):
        rid = self.selected_release()
        if rid is None: return self.error(self.release_edit_text(12))
        url = self.platform_url.text().strip()
        if url:
            parsed = urlparse(url)
            if parsed.scheme not in ('http','https') or not parsed.netloc: return self.error(self.release_edit_text(13))
        with self.con:
            self.con.execute('''INSERT INTO release_platforms(release_id,platform,status,url) VALUES(?,?,?,?)
                ON CONFLICT(release_id,platform) DO UPDATE SET status=excluded.status,url=excluded.url''',
                (rid,self.platform.currentText(),self.platform_status.currentData(),url))
        self.refresh_platforms()

