    def database_reset_text(self, original, **kwargs):
        translated = self.DATABASE_RESET_TEXTS.get(self.effective_language(), {}).get(original, original)
        return translated.format(**kwargs) if kwargs else translated

    def clear_database(self):
        """Remove application records, retaining schema and imported files; backup first."""
        first = QMessageBox.warning(
            self, self.database_reset_text('1/2 – Datenbank leeren'),
            self.database_reset_text(
                'ACHTUNG: Alle Bandprofile, Song/Projekte, Songs, Prompts, Genres, Hardware-Presets, '
                'Medienzuordnungen und Releases werden aus der Datenbank gelöscht.\n\n'
                'Die importierten Mediendateien bleiben auf der Festplatte, sind danach aber '
                'nicht mehr in MPW zugeordnet.\n\n'
                'Vorher wird zwingend ein vollständiges Backup angelegt.\n\n'
                'Möchtest du fortfahren?'),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if first != QMessageBox.StandardButton.Yes:
            return
        phrase, ok = QInputDialog.getText(
            self, self.database_reset_text('2/2 – Endgültige Bestätigung'),
            self.database_reset_text('Zum endgültigen Löschen exakt DATENBANK LEEREN eingeben:'))
        if not ok or phrase != 'DATENBANK LEEREN':
            return self.error(self.database_reset_text('Abgebrochen: Bestätigungstext stimmt nicht exakt überein.'))
        try:
            safety = self.automatic_backup_path('MPW_vor_Datenbankleerung')
            # Windows hält die Mediendatei bei aktivem Player eventuell gesperrt.
            # Die Wiedergabe vor dem vollständigen Sicherheitsbackup freigeben.
            self.player.stop()
            self.player.setSource(QUrl())
            QApplication.processEvents()
            create_backup(self.con, ROOT, safety)
            # Reihenfolge entspricht den Fremdschlüsselbeziehungen. Alle Löschungen
            # erfolgen atomar: bei einem Fehler wird die Transaktion zurückgerollt.
            with self.con:
                for table in ('album_tracks', 'albums', 'release_platforms', 'releases', 'prompt_versions',
                              'media_links', 'media_assets', 'songs', 'instruments',
                              'hardware_presets', 'projects', 'bands', 'genre_catalog'):
                    self.con.execute(f'DELETE FROM {table}')
                # sqlite_sequence wird von SQLite nur für AUTOINCREMENT-Tabellen erzeugt.
                # INTEGER PRIMARY KEY allein erzeugt diese interne Tabelle nicht.
                if self.con.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' AND name='sqlite_sequence'"
                ).fetchone():
                    self.con.execute("DELETE FROM sqlite_sequence WHERE name IN ('release_platforms','releases','prompt_versions','media_links','media_assets','songs','instruments','hardware_presets','projects','bands')")
            self.refresh_all()
        except Exception as exc:
            return self.error(self.database_reset_text('Datenbank konnte nicht geleert werden: {error}\nSicherheitsbackup: {backup}', error=exc, backup=safety if 'safety' in locals() and safety.exists() else self.database_reset_text('nicht erstellt')))
        self.message(self.database_reset_text('Datenbank geleert'),
                     self.database_reset_text('Alle Anwendungsdatensätze wurden gelöscht.\nImportierte Mediendateien wurden NICHT gelöscht.\nSicherheitsbackup: {safety}', safety=safety))

