    def backup21_text(self, original):
        return self.BACKUP21_TEXTS.get(self.effective_language(), {}).get(original, original)

    def check_current_database_integrity(self):
        """Manual, read-only diagnostic; never initiate a backup or modify records."""
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        try:
            result = check_live_database_integrity(ROOT)
        except (sqlite3.Error, OSError, ValueError) as exc:
            LOGGER.exception('Manuelle Datenbank-Integritätsprüfung fehlgeschlagen')
            QMessageBox.warning(self, self.backup21_text('Datenbank-Integrität: Fehler'),
                                f"{self.backup21_text('Die Datenbankprüfung hat einen Fehler gemeldet:')}\n{exc}\n\n" +
                                self.backup21_text('Bitte keine beschädigte Sicherung als gültig behandeln.'))
        else:
            QMessageBox.information(self, self.backup21_text('Datenbank-Integrität: OK'),
                                    self.backup21_text('Die MPW-Datenbank wurde erfolgreich geprüft.') + '\n' + result +
                                    '\n\n' + self.backup21_text('Es wurden keine Daten verändert.'))
        finally:
            QApplication.restoreOverrideCursor()

    def backup(self):
        if getattr(self, '_manual_backup_running', False):
            return self.error('Ein Vollbackup läuft bereits. Bitte dessen Abschluss abwarten.')
        default = f'MPW_backup_{datetime.now():%Y%m%d_%H%M%S}.zip'
        dest, _ = QFileDialog.getSaveFileName(self, self.backup21_text('Vollbackup speichern'),
                                               str(self.backup_directory() / default), 'ZIP (*.zip)')
        if not dest:
            return
        destination = Path(dest)
        if destination.exists() or destination.with_name(destination.name + '.incomplete').exists():
            return self.error('Zieldatei existiert bereits. Bitte einen neuen Dateinamen wählen.')
        try:
            self.con.commit()
        except sqlite3.Error as exc:
            return self.error(f'Datenbank konnte vor dem Backup nicht synchronisiert werden: {exc}')
        self._manual_backup_running = True
        self._manual_backup_dialog = QDialog(self)
        dialog = self._manual_backup_dialog
        dialog.setWindowTitle(self.backup21_text('Vollbackup läuft – MPW bleibt bedienbar'))
        dialog.setMinimumWidth(460)
        layout = QVBoxLayout(dialog)
        layout.addWidget(QLabel(self.backup21_text('Das vollständige Backup wird im Hintergrund erstellt und geprüft.') + '\n' +
                                self.backup21_text('Medien und Band-/Projektdateien werden ausdrücklich nicht gesichert.') + '\n' +
                                self.backup21_text('Bitte MPW bis zur Fertigmeldung geöffnet lassen.')))
        status = QLabel('Backup läuft …')
        layout.addWidget(status)
        from PySide6.QtWidgets import QProgressBar
        bar = QProgressBar()
        bar.setRange(0, 0)
        layout.addWidget(bar)
        dialog.setWindowFlag(Qt.WindowType.WindowCloseButtonHint, False)
        dialog.show()
        self._manual_backup_thread = QThread(self)
        self._manual_backup_worker = ManualBackupWorker(ROOT, destination)
        self._manual_backup_worker.moveToThread(self._manual_backup_thread)
        self._manual_backup_thread.started.connect(self._manual_backup_worker.run)
        self._manual_backup_worker.completed.connect(self._manual_backup_success)
        self._manual_backup_worker.failed.connect(self._manual_backup_failure)
        self._manual_backup_worker.finished.connect(self._manual_backup_thread.quit)
        self._manual_backup_worker.finished.connect(self._manual_backup_worker.deleteLater)
        self._manual_backup_thread.finished.connect(self._manual_backup_thread.deleteLater)
        self._manual_backup_thread.finished.connect(self._manual_backup_finished)
        self._manual_backup_thread.start()

    def _manual_backup_success(self, path):
        self.refresh_backup_history()
        self.update_backup_statistics()
        self.message('Backup erfolgreich', f'Vollbackup wurde erstellt und geprüft:\n{path}')

    def _manual_backup_failure(self, reason):
        self.update_backup_statistics()
        self.error('Vollbackup fehlgeschlagen:\n' + reason)

    def _manual_backup_finished(self):
        self._manual_backup_running = False
        dialog = getattr(self, '_manual_backup_dialog', None)
        if dialog is not None:
            dialog.close()
            dialog.deleteLater()
            self._manual_backup_dialog = None
        self._manual_backup_worker = None
        self._manual_backup_thread = None


    def show_backup_log(self):
        log_path = self.backup_directory() / 'MPW_Backup_Pruefprotokoll.jsonl'
        if not log_path.is_file():
            return self.message('Backup-Prüfprotokoll', 'Noch kein Prüfprotokoll im Backup-Ordner vorhanden.')
        try:
            records = []
            for line in log_path.read_text(encoding='utf-8').splitlines()[-100:]:
                entry = json.loads(line)
                records.append(f"{entry.get('timestamp', '?')}  [{entry.get('status', '?')}]  "
                               f"{entry.get('file', '?')}\n{entry.get('details', '')}")
        except (OSError, ValueError) as exc:
            return self.error(f'Prüfprotokoll konnte nicht gelesen werden: {exc}')
        dialog = QMessageBox(self)
        dialog.setWindowTitle('Backup-Prüfprotokoll – letzte 100 Einträge')
        dialog.setText(f"{len(records)} {self.backup21_text('Protokolleinträge angezeigt.')}")
        dialog.setDetailedText('\n\n'.join(reversed(records)))
        dialog.exec()

    def reset_backup_filters(self):
        """Restore all archive filters without changing the archive list order."""
        self.backup_history_filter.clear()
        self.backup_type_filter.setCurrentIndex(0)
        self.backup_age_filter.setCurrentIndex(0)
        self.filter_backup_history()

    def open_backup_folder(self):
        """Open the configured archive directory in the OS file manager."""
        folder = self.backup_directory()
        if not folder.is_dir():
            QMessageBox.warning(self, self.backup21_text('Backup-Ordner nicht erreichbar'),
                                self.backup_dialog_text('backup_folder_missing', folder=folder))
            return
        if not QDesktopServices.openUrl(QUrl.fromLocalFile(str(folder.resolve()))):
            QMessageBox.warning(self, self.backup21_text('Backup-Ordner'),
                                self.backup_dialog_text('backup_explorer_failed', folder=folder))

    def reveal_selected_backup(self):
        """Show the selected ZIP in the file manager without opening its contents."""
        item = self.backup_history.currentItem()
        if item is None or item.isHidden():
            QMessageBox.information(self, self.localized_dialog_title('Backup auswählen'),
                                    self.backup_selection_text('backup_visible'))
            return
        value = item.data(Qt.ItemDataRole.UserRole)
        if not value:
            QMessageBox.information(self, self.localized_dialog_title('Backup auswählen'),
                                    self.backup_selection_text('backup_any'))
            return
        archive = Path(value)
        if not archive.is_file():
            QMessageBox.warning(self, self.localized_dialog_title('Backup nicht gefunden'),
                                self.backup_selection_text('backup_file_missing', path=archive))
            self.refresh_backup_history()
            return
        try:
            if sys.platform == 'win32':
                # Pass an argument list, not a shell command; paths may contain spaces.
                subprocess.Popen(['explorer.exe', '/select,', str(archive.resolve())])
            elif not QDesktopServices.openUrl(QUrl.fromLocalFile(str(archive.parent.resolve()))):
                QMessageBox.warning(self, self.localized_dialog_title('Dateimanager'),
                                    f'Der Ordner konnte nicht geöffnet werden:\n{archive.parent}')
        except OSError as exc:
            QMessageBox.warning(self, self.localized_dialog_title('Dateimanager'),
                                f'Der Datei-Explorer konnte nicht gestartet werden:\n{exc}')

    def show_backup_context_menu(self, position):
        """Offer safe shortcuts for the backup under the pointer; no implicit restore."""
        item = self.backup_history.itemAt(position)
        if item is None or item.isHidden():
            return
        value = item.data(Qt.ItemDataRole.UserRole)
        if not value or not Path(value).is_file():
            return
        self.backup_history.setCurrentItem(item)
        menu = QMenu(self.backup_history)
        inspect_action = menu.addAction(self.translated_context_label('Backup-Inhalt anzeigen'))
        verify_action = menu.addAction(self.translated_context_label('Backup prüfen'))
        menu.addSeparator()
        reveal_action = menu.addAction(self.translated_context_label('Im Explorer zeigen'))
        copy_action = menu.addAction(self.translated_context_label('Backup-Pfad kopieren'))
        filename_action = menu.addAction(self.translated_context_label('Backup-Dateiname kopieren'))
        details_action = menu.addAction(self.translated_context_label('Backup-Details kopieren'))
        selected = menu.exec(self.backup_history.viewport().mapToGlobal(position))
        if selected is inspect_action:
            self.inspect_selected_backup()
        elif selected is verify_action:
            self.check_selected_backup()
        elif selected is reveal_action:
            self.reveal_selected_backup()
        elif selected is copy_action:
            self.copy_selected_backup_path()
        elif selected is filename_action:
            self.copy_selected_backup_filename()
        elif selected is details_action:
            self.copy_selected_backup_details()

    def copy_selected_backup_path(self):
        """Copy the selected existing archive's absolute path, without changing the file."""
        item = self.backup_history.currentItem()
        if item is None or item.isHidden():
            QMessageBox.information(self, self.localized_dialog_title('Backup auswählen'),
                                    self.backup_selection_text('backup_visible'))
            return
        value = item.data(Qt.ItemDataRole.UserRole)
        if not value or not Path(value).is_file():
            QMessageBox.warning(self, self.localized_dialog_title('Backup nicht gefunden'),
                                self.backup_selection_text('backup_unavailable'))
            self.refresh_backup_history()
            return
        QApplication.clipboard().setText(str(Path(value).resolve()))
        self.statusBar().showMessage('Backup-Pfad in die Zwischenablage kopiert.', 5000)

    def copy_selected_backup_filename(self):
        """Copy only the filename of an existing selected ZIP backup."""
        item = self.backup_history.currentItem()
        if item is None or item.isHidden():
            QMessageBox.information(self, self.localized_dialog_title('Backup auswählen'),
                                    self.backup_selection_text('backup_visible'))
            return
        value = item.data(Qt.ItemDataRole.UserRole)
        if not value or not Path(value).is_file():
            QMessageBox.warning(self, self.localized_dialog_title('Backup nicht gefunden'),
                                self.backup_selection_text('backup_unavailable'))
            self.refresh_backup_history()
            return
        QApplication.clipboard().setText(Path(value).name)
        self.statusBar().showMessage('Backup-Dateiname in die Zwischenablage kopiert.', 5000)

    def copy_selected_backup_details(self):
        """Copy a compact, readable report for one existing archive."""
        item = self.backup_history.currentItem()
        if item is None or item.isHidden():
            QMessageBox.information(self, self.localized_dialog_title('Backup auswählen'),
                                    self.backup_selection_text('backup_visible'))
            return
        value = item.data(Qt.ItemDataRole.UserRole)
        if not value:
            QMessageBox.warning(self, self.localized_dialog_title('Backup nicht gefunden'),
                                self.backup_selection_text('backup_path_missing'))
            return
        path = Path(value)
        try:
            stat = path.stat()
            if not path.is_file():
                raise FileNotFoundError(str(path))
        except OSError:
            QMessageBox.warning(self, self.localized_dialog_title('Backup nicht gefunden'),
                                self.backup_selection_text('backup_unavailable'))
            self.refresh_backup_history()
            return
        backup_type = ('Automatisch' if path.name.startswith('MPW_auto_')
                       else 'Manuell / sonstige')
        report = ('MPW – Backup-Details\n'
                  f'Dateiname: {path.name}\n'
                  f'Typ: {backup_type}\n'
                  f'Größe: {stat.st_size:,} Bytes ({stat.st_size / 1048576:.2f} MiB)\n'
                  f'Geändert: {datetime.fromtimestamp(stat.st_mtime):%d.%m.%Y %H:%M:%S}\n'
                  f'Pfad: {path.resolve()}')
        QApplication.clipboard().setText(report)
        self.statusBar().showMessage('Backup-Details in die Zwischenablage kopiert.', 5000)

    def filter_backup_history(self, query=None):
        """Filter visible backup entries without touching archive files."""
        query = (query if isinstance(query, str) else self.backup_history_filter.text()).strip().casefold()
        total = 0
        visible = 0
        for index in range(self.backup_history.count()):
            item = self.backup_history.item(index)
            archive_path = item.data(Qt.ItemDataRole.UserRole)
            if not archive_path:
                item.setHidden(False)
                continue
            total += 1
            filename = Path(archive_path).name
            type_filter = self.backup_type_filter.currentIndex()
            automatic = filename.startswith('MPW_auto_')
            age_days = {1: 7, 2: 30, 3: 90}.get(self.backup_age_filter.currentIndex())
            recent_enough = True
            if age_days is not None:
                try:
                    recent_enough = Path(archive_path).stat().st_mtime >= (
                        datetime.now() - timedelta(days=age_days)).timestamp()
                except OSError:
                    recent_enough = False
            matches = (query in filename.casefold() and recent_enough and
                       (type_filter == 0 or (type_filter == 1 and automatic) or
                        (type_filter == 2 and not automatic)))
            item.setHidden(not matches)
            visible += int(matches)
        selected = self.backup_history.currentItem()
        if selected is not None and selected.isHidden():
            self.backup_history.setCurrentItem(None)
        self.backup_filter_count.setText(self.backup_archive_status_text('count', visible=visible, total=total))

